window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-clinica-medica-med-clm-17"]={"block":"med:med-clinica-medica-med-clm-17","label":"MED · MED CLM 17","count":444,"questions":[{"id":"med-clinica-medica-med-clm-17-345463","number":"345463","sourceNumber":"345463","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente de 12 anos, previamente hígida, sem história de febre ou signos\ninflamatórios, comparece à consulta com queixas\nrelatadas pela mãe que incluem palidez, cansaço,\nalteração do humor, tontura, taquicardia, taquipneia leve, dificuldade no aprendizado. A primeira\nhipótese diagnóstica, nessas condições, é:","options":{"A":"Linfoma.","B":"Anemia carencial.","C":"Cardiopatia congênita.","D":"Hemorragia digestiva."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-345470","number":"345470","sourceNumber":"345470","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente de 34 anos de idade procurou atendimento por quadro de astenia há cerca\nde dois meses. Ao exame físico: paciente\ndescorado ++/4; anictérico; hidratado e com fígado\npalpável (três polpas digitais abaixo do rebordo costal). Traube ocupado. Aos exames, Hb 8,5,\nleucócitos 3.300, plaquetas 80.000, VCM 100, HCM 34, RDW 15, DHL 725, bilirrubinas totais 2,\n\nTGO 20, TGP 18, B12 225 (VR 175) e ácido fólico 7 (VR 4). Com base nesse caso hipotético,\nassinale a alternativa que apresenta a conduta mais adequada:","options":{"A":"Convocar equipe da hematologia para biópsia de medula, devido à suspeita de leucemia\nmielóide aguda.","B":"Solicitar dosagem de ácido metilmalônico e homocisteína.","C":"Prescrever corticóide em dose elevada por se tratar de anemia hemolítica autoimune.","D":"Investigar sítio primário de neoplasia."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-345493","number":"345493","sourceNumber":"345493","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Diante de um paciente com anemia ferropriva, o único resultado de exame que NÃO\nesperamos encontrar é o de:","options":{"A":"Níveis aumentados de hepcidina.","B":"Hemoglobina abaixo de 11g/Dl.","C":"Zinco-protoporfirina eritrocitária livre elevada.","D":"Aumento dos receptores séricos de transferrina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-291754","number":"291754","sourceNumber":"291754","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\nachado mais provável na análise do sangue periférico:","options":{"A":"Hemáceas em fragmentadas e presença de parasitas amastigotas.","B":"Hemáceas em foice e corpúsculos de Howell-Jolly.","C":"Hemáceas em alvo e corpúsculos de Heinz.","D":"Hemáceas hipocrômicas e anisocitose intensa."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-291755","number":"291755","sourceNumber":"291755","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\nexame padrão-ouro para o diagnóstico da principal hipótese diagnóstica:","options":{"A":"Biópsia de medula óssea.","B":"Mielograma.","C":"Eletroforese de hemoglobina.","D":"Biópsia hepática."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-291756","number":"291756","sourceNumber":"291756","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\ntratamento farmacológico mais adequado para a principal hipótese diagnóstica:","options":{"A":"Sulfato ferroso.","B":"Anfotericina B.","C":"Hidroxiureia.","D":"Complexo B e ácido fólico."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-283284","number":"283284","sourceNumber":"283284","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quanto ao diagnóstico laboratorial das anemias, o encontro de hemoglobina de 9,0 g/dl,\nVCM diminuído < 80 fl e RDW elevado > 14,5 sugere anemia:","options":{"A":"Falciforme.","B":"Ferropriva.","C":"Aplásica.","D":"Megaloblástica."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-281116","number":"281116","sourceNumber":"281116","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação às anemias hipocrômicas e microcíticas:","options":{"A":"A causa mais comum é deficiência de vitamina B12.","B":"Devem ser tratadas com sulfato ferroso.","C":"Devem ser investigadas com mielograma.","D":"Os principais diagnósticos diferenciais são anemia ferropriva, talassemia e anemia de doença\ncrônica.","E":"Os reticulócitos geralmente estão aumentados por se tratar de anemia hiperproliferativa."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-281145","number":"281145","sourceNumber":"281145","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança de 5 anos é levada ao Pronto Socorro Pediátrico devido à início súbito de\nfebre e palidez cutâneo mucosa grave. Você coleta um hemograma que evidencia níveis muito\nbaixos de hemoglobina, caracterizando um quadro de Crise Aplásica. O agente viral mais envolvido\nnesses episódios, com potencial de letalidade, é:","options":{"A":"Eritrovírus B19.","B":"Herpes simples tipo 1.","C":"Epstein Bar.","D":"Citomegalovirus.","E":"Influenza A."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-251870","number":"251870","sourceNumber":"251870","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O diagnóstico de anemia hemolítica só pode ser realizado com exames\ncomplementares, entre os exames que devem ser\nrealizados, assinale a alternativa ERRADA:","options":{"A":"Hemograma completo, juntamente com índices de glóbulos vermelhos e contagem de plaquetas.\n\nComo os reticulócitos são células maiores, o volume corpuscular médio nestes pacientes pode ser\naumentado em níveis similares aos encontrados na anemia megaloblástica.","B":"Esfregaço de sangue periférico: pode demonstrar hemácias esferocíticas (como na anemia\nhemolítica autoimune ou esferocitose hereditária). Outras alterações na forma de eritrócitos\ntambém podem ser encontradas.","C":"Lactato desidrogenase (LDH): aumentada nas anemias hemolíticas.","D":"Teste de Coombs direto ou de antiglobulina direto: negativo nas anemias hemolíticas\nautoimunes."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-247174","number":"247174","sourceNumber":"247174","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente do sexo masculino, 56 anos, apresenta quadro de anemia. Queixa-se de\nfraqueza, tontura e sensação de formigamento\nnos pés. O hemograma revela hemoglobina de\n10g/dL, normalidade e hipersegmentação de neutrófilos. Apresenta história de internação hospitalar\nprévia devido a trauma abdominal, tendo sido submetido a laparotomia exploradora e ressecção\ncirúrgica de íleo terminal. Não apresenta, respectivamente, a hipótese diagnóstica mais provável e\no tratamento mais apropriado para a condição.","options":{"A":"Anemia ferropriva - Sulfato ferroso por via oral.","B":"Anemia perniciosa - Vitamina B12 por via oral.","C":"Anemia por deficiência de folato - Ácido fólico por via oral.","D":"Anemia por deficiência de vitamina B12 - Vitamina B12 por via parenteral.","E":"Anemia multicarencial - Ácido fólico, vitamina B12 e sulfato ferroso por via oral."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-247175","number":"247175","sourceNumber":"247175","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente do sexo feminino, 26 anos, apresenta queixa de fadiga e dispneia aos\nesforços. Apresenta pressão arterial de 115/70\nmmHg e a frequência cardíaca de 110 bpm. Ao se\nlevantar, a pressão arterial cai para 95/55 mmHg e a frequência cardíaca se eleva para 128 bpm. O\nhemograma apresenta hemoglobina de 7,8 g/dL, volume corpuscular médio de 74 fL, leucometria\nde 4.300/µL e contagem de plaquetas de 395.000/µL. Assinale a alternativa CORRETA, que\napresenta a hipótese diagnóstica mais provável.","options":{"A":"Anemia ferropriva.","B":"Anemia hemolítica.","C":"Anemia aplástica.","D":"Anemia falciforme.","E":"Anemia perniciosa."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-247188","number":"247188","sourceNumber":"247188","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 6 anos encaminhada ao ambulatório por anemia e icterícia diagnosticadas\nhá cerca de três anos. Nega outras queixas.\nAntecedentes familiares: mãe retirou o baço quando\nera criança devido a anemia. Ao exame físico: bom estado geral, ictérica +/4+, palidez cutânea\n\n+/4+, acianótica, afebril. Fígado não palpável e baço palpável a 2 cm do rebordo costal esquerdo.\nSolicitado exames: Hemoglobina 10,5 g/dL, VCM 90 fl Reticulócitos 8,0% Bilirrubina Total 4,5\nmg/dL, e Direta 1,0 mg/dL. Qual é o melhor exame para confirmar o diagnóstico?","options":{"A":"Eletroforese de hemoglobina.","B":"Dosagem de ferro sérico e ferritina sérica.","C":"Prova de fragilidade osmótica.","D":"Mielograma.","E":"Coombs direto."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-217710","number":"217710","sourceNumber":"217710","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dentre as hemoglobinopatias, a anemia falciforme é a mais encontrada dentro da\npediatria, sendo CORRETO afirmar que:","options":{"A":"A dactilite aguda falcêmica, se apresentando como síndrome mão-pé, é frequentemente o\nprimeiro surto de que a doença falcêmica está presente em uma criança.","B":"Com o passar dos meses de vida, outras complicações da anemia falciforme tendem a aparecer,\nsendo os episódios vaso-oclusivos mais\nfrequentes entre 3 e 5 anos de vida.","C":"Dificilmente crianças menores, com anemia falciforme, podem ter esplenomegalia associada à\ndoença hemolítica, com progressão para síndrome\ndo hiperesplenismo.","D":"Nos meninos, o priapismo é uma complicação rara, que resulta da concentração do sangue no\ncorpo cavernoso, causando obstrução do fluxo venoso."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-182672","number":"182672","sourceNumber":"182672","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação à anemia ferropriva na infância, marque a alternativa CORRETA:","options":{"A":"Ao avaliar o hemograma percebemos níveis de hemoglobina e HCM baixos, associados ao VCM\nelevado.","B":"Não é a principal causa de anemias na infância.","C":"O tratamento consiste em administração de antihelminticos, complexos contendo ferro na dose\nde 3 a 6 mg/kg/dia de ferro elementar,\nalém de dieta rica em alimentos com boa biodisponibilidade\ndesse elemento.","D":"Indica-se transfusão de concentrado de hemácias a todas as crianças com hemoglobina <7g/dl."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-159063","number":"159063","sourceNumber":"159063","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quais as alterações que se espera encontrar no hemograma de uma criança com\nanemia ferropriva?","options":{"A":"VCM baixo e RDW baixo.","B":"VCM alto e RDW normal.","C":"VCM baixo e RDW alto.","D":"VCM baixo e RDW normal."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-159070","number":"159070","sourceNumber":"159070","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Beatriz, 4 anos de idade, dá entrada na Unidade de Saúde com importante palidez,\nmas hemodinamicamente estável. O Hemograma evidência\nhemoglobina de 5 g/dI com importante\nmicrocitose e hipocromia. Qual a melhor conduta?","options":{"A":"Internar e fazer ferro endovenoso.","B":"Fazer hemotransfusão.","C":"Prescrever vitamina B12.","D":"Prescrever sulfato ferroso oral e orientação alimentar."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-135952","number":"135952","sourceNumber":"135952","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São complicações da Glomerulonefrite difusa aguda, EXCETO:","options":{"A":"Insuficiência renal aguda;","B":"Encefalopatia hipertensiva;","C":"Taquidispneia;","D":"Proteinúria."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-84472","number":"84472","sourceNumber":"84472","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na síndrome nefrótica, existe uma associação imprescindível para tal diagnóstico:","options":{"A":"Proteinúria > 50 mg/kg/dia e albumina < 2,5 mg.","B":"Proteinúria e hipercolesterolemia.","C":"Proteinúria e anasarca.","D":"Proteinúria e hematúria.","E":"Edema e hematúria."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-84475","number":"84475","sourceNumber":"84475","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um dos exames confirmatórios da Glomerulonefrite pós-estreptocócica é:","options":{"A":"ASLO positivo.","B":"EAS com hematúria.","C":"Complemento C3 e C4 consumidos.","D":"Complemento C3 e C4 aumentados.","E":"Complemento C3 e C4 normais."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-50063","number":"50063","sourceNumber":"50063","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 4 anos de idade com relato de edema facial e abdominal com estiramento\nda cicatriz umbilical, regular estado geral,\nprocedente da zona rural. A mãe refere um pico febril de\n37,9 graus e inapetência nas últimas 72 horas. O exame de urina mostrou proteinúria leve, cilindros\nhemáticos, leucocitúria leve e mais de 60 hemácias por campo. A PA no momento do exame é de\n120 x 85 mmHg. A criança não refere cefaleia. Em relação ao caso clínico, assinale a melhor\nconduta:","options":{"A":"Iniciar antibioticoterapia.","B":"Somente restrição hídrica e dieta hipossódica seriam necessárias.","C":"Internar o paciente e iniciar sulfametoxazol e hidroclorotiazida para diminuir o edema.","D":"Iniciar inibidores da ECA (enzima conversora de angiotensina), diuréticos e medidas gerais de\ncontrole."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-37093","number":"37093","sourceNumber":"37093","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à Síndrome Nefrótica, assinale a alternativa correta:","options":{"A":"A Síndrome Nefrótica caracteriza-se por proteinúria maciça, hipoalbuminemia, edema,\nhipercolesterolemia e lipidúria","B":"Na infância, 80% dos casos correspondem à Síndrome Nefrótica Primária ou Idiopática","C":"O complemento apresenta-se diminuído","D":"As principais variantes de Síndrome Nefrótica Idiopática na criança são a lesão histológica\nmínima e a glomeruloesclerose segmentar e focal","E":"A peritonite pode manifestar-se como complicação"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-29375","number":"29375","sourceNumber":"29375","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"É a forma mais comum de glomerulopatia primária em nosso meio, a apresentação\ntípica é de síndrome nefrótica em 70%, com\nhipertensão entre 30 a 50% e hematúria em metade\ndos pacientes. Os níveis de complemento e outros testes sorológicos são normais:","options":{"A":"Membranosa","B":"Membranoproliferativa","C":"Lesão mínima","D":"Esclerose segmentar e focal (GESF)","E":"Pós-estreptocócica"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313428","number":"313428","sourceNumber":"313428","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São os mais pobres, os mais vulneráveis e os menos educados, os mais afetados pela\ndeficiência de ferro. São eles também os mais beneficiados com a reposição. Assinale a alternativa\ncorreta.","options":{"A":"Além da anemia e prejuízo no desempenho físico, intelectual e de trabalho, há relatos de\nfunções neurotransmissoras, imunológicas e inflamatórias\nalteradas e maior risco de infecções.","B":"Além da anemia e prejuízo no desempenho físico, intelectual e de trabalho, há relatos de\nfunções neurotransmissoras, imunológicas e\ninflamatórias alteradas e menor risco de infecções.","C":"Além da anemia e prejuízo no desempenho físico, intelectual e de trabalho, mas não de funções\nneurotransmissoras, imunológicas e inflamatórias alteradas e maior risco de infecções.","D":"Além da anemia e prejuízo no desempenho físico, mas não ocorre intelectual e de trabalho."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313430","number":"313430","sourceNumber":"313430","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A Ferritina Sérica é o marcador mais utilizado para avaliar as reservas orgânicas de\nferro, sendo correta a alternativa:","options":{"A":"Estando aumentada em caso de deficiência desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e variação entre diferentes técnicas de dosagem.","B":"Estando diminuída em caso de excesso desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e variação entre diferentes técnicas de dosagem.","C":"Estando diminuída em caso de deficiência desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e variação entre diferentes técnicas de dosagem.","D":"Estando diminuída em caso de deficiência desse mineral, embora seja sujeita a considerável\nvariabilidade biológica e nunca variação entre diferentes técnicas de dosagem."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313432","number":"313432","sourceNumber":"313432","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Os sintomas usuais da Anemia por Deficiência de Ferro (ADF) incluem fraqueza,\ncefaleia, irritabilidade, síndrome das pernas\ninquietas e vários graus de fadiga e intolerância aos\nexercícios ou apetite pervertido, sendo correto que:","options":{"A":"Pica (apetite pervertido por barro ou terra, papéis, amido). Pode ainda ocorrer pica por gelo,\nque\né considerada bastante inespecífica para DF.","B":"Pica (apetite pervertido por barro ou terra, papéis, amido). Mas não pode ocorrer pica por gelo.","C":"Pica por gelo apenas, que é considerada bastante específica para DF.","D":"Pica (apetite pervertido por barro ou terra, papeis, amido). Pode ainda ocorrer pica por gelo,\nque\né considerada bastante específica para DF."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313435","number":"313435","sourceNumber":"313435","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"No entanto, muitos pacientes com Anemia por Deficiência de Ferro são assintomáticos,\nsem clínica típica e só reconhecem os sintomas\nretrospectivamente, após o tratamento. Assinale a\nalternativa correta.","options":{"A":"Pacientes com ferritina baixa e sem anemia nunca podem ter os mesmos sintomas.","B":"Pacientes com ferritina normal e sem anemia podem ter os mesmos sintomas.","C":"Pacientes com ferritina baixa e com anemia não podem ter os mesmos sintomas.","D":"Pacientes com ferritina baixa e sem anemia podem ter os mesmos sintomas."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-307071","number":"307071","sourceNumber":"307071","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menino, 8 anos de idade, é trazido pela genitora ao ambulatório com queixa de lesões\nde pele e dor leve em articulações. Relata\nque, há aproximadamente uma semana, apresentou\nfebre, cefaleia, coriza e adinamia. As lesões de pele, por vezes clareiam e retornam; e são pouco\npruriginosas. A genitora informa que o menor é falcêmico. Ao exame, está hipoativo, afebril,\nhipocorado ++/IV. Observa-se rubor facial, concentrado nas bochechas, e exantema macular, de\naspecto rendilhado, em membros, poupando regiões plantares e palmares. Diante do caso, indique\na possível complicação decorrente dessa doença.","options":{"A":"Febre reumática.","B":"Aplasia medular.","C":"Encefalite.","D":"Mielite."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-283709","number":"283709","sourceNumber":"283709","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez,\nqueixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA: 120 x 65\nmmHg, FC: 100 bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas, com\nsopro sistólico panfocal. Fígado palpável a 4 cm do rebordo costal direito e espaço de Traube livre.\nHá ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, identifique o achado\nmais provável na análise do sangue periférico:","options":{"A":"Hemácias em fragmentadas e presença de parasitas amastigotas.","B":"Hemácias em foice e corpúsculos de Howell-Jolly.","C":"Hemácias em alvo e corpúsculos de Heinz.","D":"Hemácias hipocrômicas e anisocitose intensa."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-283710","number":"283710","sourceNumber":"283710","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\nexame padrão-ouro para o diagnóstico da principal hipótese diagnóstica:","options":{"A":"Biópsia de medula óssea.","B":"Mielograma.","C":"Eletroforese de hemoglobina.","D":"Biópsia hepática."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-283711","number":"283711","sourceNumber":"283711","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, sexo masculino, 17 anos de idade, procedente de zona rural, procura\natendimento médico pela primeira vez, queixando-se de dores ósseas e astenia, desde a infância.\nRefere ainda dispneia aos esforços, dores abdominais esporádicas em hipocôndrio direito e duas\ninternações prévias por pneumonia. Ao exame físico, descorado ++/4, ictérico ++/4, PA:\n120x65mmHg, FC: 100bpm. À ausculta, apresenta ritmo cardíaco regular, bulhas normofonéticas,\ncom sopro sistólico panfocal. Fígado palpável a 4cm do rebordo costal direito e espaço de Traube\nlivre. Há ainda uma úlcera rasa em maléolo direito. Diante do caso apresentado, Identifique o\ntratamento farmacológico mais adequado para a principal hipótese diagnóstica:","options":{"A":"Sulfato ferroso.","B":"Anfotericina B.","C":"Hidroxiureia.","D":"Complexo B e ácido fólico."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-275971","number":"275971","sourceNumber":"275971","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia falciforme é uma doença do tecido hematopoiético hereditária que se\ncaracteriza por alteração no formato da hemácia, apresentando um tipo de hemoglobina que se\ncristaliza na falta de oxigênio. Relacionados a seguir encontra-se condições e sintomas\nrelacionados a patologia, assinale a que não faz parte da sintomatologia habitual:","options":{"A":"Dores articulares e ósseas e atraso no crescimento.","B":"Tendencia a infecção e feridas nas pernas.","C":"Distúrbios neurológicos, pulmonares e renais.","D":"Priapismo.","E":"Disgeusia."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-279043","number":"279043","sourceNumber":"279043","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale o fator que não é responsável por desencadear dor nos pacientes portadores\nde anemia falciforme.","options":{"A":"Alcalose.","B":"Variação de temperatura.","C":"Infecção.","D":"Desidratação."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-252875","number":"252875","sourceNumber":"252875","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem, 22 anos de idade, procura atendimento médico por alterações de exames\nlaboratoriais de rotina. Assintomático. No\ninterrogatório sistemático, referiu ter notado olhos\namarelados, há cerca de 2 anos, por cerca de 2 dias, mas não procurou atendimento médico. Nega\ncomorbidades. Exame físico sem alterações. Exames laboratoriais com bilirrubinas totais de 2,89\nmg/dl, com bilirrubina indireta de 2,03 mg/dl; AST = 18 U/l (VR = 30); ALT = 16 U/L (VR = 30); FA =\n55 U/L (VR = 100); GGt = 20 U/L (VR = 60) AntiHCV não reagente; AntiHBs reagente; AntiHAV 1gG\nreagente Eletroforense de hemoglobina: HbA1 = 59%; HbA2 = 4%; HbS = 37%. O risco que o filho\ndeste paciente terá de nascer com anemia falciforme, caso a mãe possua traço falcêmico, é de:","options":{"A":"0 (zero)%","B":"25%","C":"50%","D":"100%"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249396","number":"249396","sourceNumber":"249396","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"No paciente que apresenta diagnóstico de anemia falciforme pelo teste do pezinho, o\nresultado encontrado é:","options":{"A":"HgFSC.","B":"HgFSA.","C":"HgFA.","D":"HgFS."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249398","number":"249398","sourceNumber":"249398","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quais das alterações bioquímicas apresentadas abaixo estão relacionadas com a\npresença de hemólise?","options":{"A":"LDH, TGO, bilirrubina, haptoglobina.","B":"TGO, LDH, fosfatase alcalina, amilase.","C":"Haptoglobina, bilirrubina, ferritina, fosfatase alcalina.","D":"Ferritina, TGO, ácido úrico, LDH."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-212225","number":"212225","sourceNumber":"212225","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na anemia hemolítica, podemos encontrar nos exames laboratoriais as seguintes\nalterações:","options":{"A":"Bilirrubina direta elevada, desidrogenase láctica elevada e haptoglobina elevada.","B":"Bilirrubina indireta elevada, desidrogenase láctica diminuída e haptoglobina elevada.","C":"Bilirrubina indireta elevada, desidrogenase láctica elevada e haptoglobina elevada.","D":"Bilirrubina indireta elevada, desidrogenase láctica elevada e haptoglobina diminuída.","E":"Bilirrubina direta elevada, desidrogenase láctica elevada e haptoglobina diminuída."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-212158","number":"212158","sourceNumber":"212158","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dadas as afirmativas quanto à Síndrome Torácica Aguda na doença falciforme, I. É a\nforma mais comum de complicação pulmonar. II. Representa um marcador importante de\nmortalidade precoce. III. A presença de infiltrado novo em radiografia de tórax envolvendo pelo\nmenos um segmento pulmonar completo constitui um critério diagnóstico obrigatório. IV. A\nrecorrência da síndrome é associada à hipertensão pulmonar. verifica-se que está(ão) correta(s)","options":{"A":"I, II, III e IV.","B":"I, III e IV, apenas.","C":"II e IV, apenas.","D":"II e III, apenas.","E":"I, apenas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-219916","number":"219916","sourceNumber":"219916","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 39 anos, vegetariana, comparece ao consultório médico com exames\nadmissionais que evidenciam anemia macrocítica associada a níveis séricos de vitamina B12\ndiminuídos. Marque a alternativa INCORRETA sobre essa afecção:","options":{"A":"Alterações nas células mucosas geram glossite, anorexia e diarreia.","B":"Conversão da homocisteína em metionina está aumentada.","C":"Elevação sérica da lactato desidrogenase e da bilirrubina indireta são secundárias à destruição\nmedular das células eritroides.","D":"Parestesias e distúrbios do equilíbrio e propriocepção são manifestações neurológicas."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-215228","number":"215228","sourceNumber":"215228","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Anemia Aplástica (AA) ou aplasia de medula óssea é uma doença rara, caracterizada\npor pancitopenia moderada a grave no sangue\nperiférico e hipocelularidade acentuada na medula\nóssea, sendo a mais frequente das síndromes de falência medular. Está inadequado que:","options":{"A":"Estima-se que a incidência de AA adquirida seja de 2-4 pessoas por 1.000.000 ao ano, com três\npicos de incidência.","B":"Pico de incidência ocorre primeiro entre os indivíduos de 10-25 anos e outro Pico de incidência\nnos maiores de 60 anos, sem diferenças entre os\nsexos.","C":"Há relatos de que populações de origem asiática têm maior incidência da doença.","D":"Na AA por causas congênitas, o pico de incidência parece situar-se entre 2-5 anos de idade."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-215254","number":"215254","sourceNumber":"215254","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O diagnóstico de Anemia Aplástica AA é realizado pela associação dos seguintes\nachados: pancitopenia no sangue periférico\n(hemoglobina menor de 10 g/dl, plaquetas <\n50.000/mm3 e neutrófilos < 1.500/mm3), baixa contagem de reticulócitos (abaixo do limite\nconsiderado normal pelo método) e medula óssea hipocelular à biópsia, com diminuição de todos\nos elementos hematopoiéticos e seus precursores, na ausência de células estranhas à medula\nóssea, fibrose ou hematofagocitose. Sobre isso, podemos aceitar que:","options":{"A":"Pacientes com AA têm maior probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral.\nAs análises citogenética e imunofenotípica\ncomplementares não podem auxiliar na diferenciação diagnóstica, porém isoladamente não devem\nser utilizadas como ferramenta diagnóstica.","B":"Pacientes com AA têm maior probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral.\nAs análises citogenética e imunofenotípica\ncomplementares podem auxiliar na diferenciação diagnóstica, porém isoladamente não devem ser\nutilizadas como ferramenta diagnóstica.","C":"Pacientes com AA têm maior probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral. As\nanálises citogenética e imunofenotípica\ncomplementares podem auxiliar na diferenciação diagnóstica, isoladamente devem ser utilizadas\ncomo ferramenta diagnóstica.","D":"Pacientes com AA têm menor probabilidade de desenvolver mielodisplasias e doenças\nneoplásicas hematológicas do que a população geral.\nAs análises citogenética e imunofenotípica\ncomplementares podem auxiliar na diferenciação diagnóstica, porém isoladamente não devem ser\nutilizadas como ferramenta diagnóstica."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-215293","number":"215293","sourceNumber":"215293","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A grande maioria dos casos de Anemia Aplástica AA é adquirida, com uma pequena\nproporção de pacientes apresentando a forma\ncongênita da doença. São suas formas\nconstitucionais as listadas abaixo, indique a que foge ao contexto:","options":{"A":"Disceratose congênita.","B":"Anemia de Fanconi.","C":"Manifestação idiossincrática.","D":"Síndrome de Shwachman-Diamond."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-182793","number":"182793","sourceNumber":"182793","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à Síndrome Torácica Aguda, assinale a alternativa CORRETA:","options":{"A":"A oxigenioterapia está indicada apenas em hipoxemia severa.","B":"Caracteristicamente não há dor torácica.","C":"Podem ocorrer infartos pulmonares.","D":"A mortalidade é extremamente baixa."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-181384","number":"181384","sourceNumber":"181384","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, sexo feminino, foi encaminhada para o ambulatório para investigação de\nanemia. Trazia um hemograma com Hb: 9 mg/dl\ne VCM: 115. Após investigação completa, foi\ndiagnosticada com Anemia Perniciosa. A respeito desse assunto, dadas as afirmativas: I. É a causa\nmais comum de deficiência de vitamina B12; II. É mais frequente antes dos 30 anos de idade; III.\nAnticorpos anticélulas parietais e os anticorpos antifator intrínseco são os principais\nautoanticorpos;\n\nIV. Não existe associação com câncer gástrico. Verifica-se que está(ão) correta(s):","options":{"A":"II, apenas.","B":"I e II, apenas.","C":"I e III, apenas.","D":"III e IV, apenas.","E":"I, II, III e IV."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183039","number":"183039","sourceNumber":"183039","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à anemia ferropriva.","options":{"A":"Segundo a Organização Mundial de Saúde define-se anemia como uma ?condição na qual o\nconteúdo de hemoglobina no sangue está abaixo do normal ou como resultado da carência de um\nou mais nutrientes essenciais, seja qual for a causa dessa deficiência?, no caso da anemia\nferropriva há deficiência de ferro.","B":"A anemia ferropriva traz os seguintes efeitos adversos ou consequências: diminuição da\nprodutividade e da capacidade de aprendizado,retardo do crescimento e apatia.","C":"A dieta inadequada não estána lista das causas de anemia ferropriva.","D":"Sinais e sintomas da carência de ferro são inespecíficos, necessitando de exames laboratoriais\npara que seja confirmado o\n\ndiagnóstico de anemia ferropriva."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183083","number":"183083","sourceNumber":"183083","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"As gestantes têm maior risco de desenvolver Deficiência de Ferro (DF), e Anemia\n(ADF) pelas altas demandas fisiológicas\npróprias e da unidade feto?placentária, difíceis de serem\nsupridas apenas pela dieta, além da perda sanguínea que pode ocorrer durante o parto. Em\nrelação a isso, assinale a alternativa INCORRETA:","options":{"A":"Devido à anemia, essas mulheres têm menor ganho de peso durante a gestação.","B":"Existe uma forte relação entre o status de ferro da mãe e a depressão, o stress, as funções\ncognitivas e as interações mãe-filho, mas a deficiência de ferro não afeta o seu humor e as\ninterações com o RN, e a suplementação não protege contra estes efeitos.","C":"A ADF na gestação é frequentemente diagnosticada e tratada, mas os efeitos destes\ntratamentos permanecem largamente desconhecidos e\nmais pesquisas precisam ser realizadas\npara melhorar o prognóstico materno e neonatal de mulheres com anemia moderada e grave em\nlugares com poucos recursos.","D":"Devido à anemia, essas mulheres têm maiores riscos de partos prematuros, placenta prévia,\nhemorragias, ruptura prematura de membranas, pré-eclâmpsia, eclâmpsia, sepsis pós-natal, maior\nrisco de morte, menor desempenho laboral, fadiga, fraqueza e dispneia"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183116","number":"183116","sourceNumber":"183116","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A prevalência de anemia por DF (ADF) aumenta em populações com carências\nnutricionais; com ingestão ou absorção inadequada\nde ferro. Dessa forma, assinale a interação\ndescrita de maneira INADEQUADA:","options":{"A":"Hábitos vegetarianos; dietas com muito chá ou café, que aumentam a absorção de ferro.","B":"Sem vitamina C (frutas cítricas), que favorece a sua absorção.","C":"Baixo nível socioeconômico e educacional.","D":"Presença de infestações endêmicas (malária, ascaridíase, helmintoses, protozooses intestinais)."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183124","number":"183124","sourceNumber":"183124","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Os sintomas usuais da Anemia por Deficiência de Ferro incluem fraqueza, cefaleia,\nirritabilidade, síndrome das pernas inquietas e\nvários graus de fadiga e intolerância aos exercícios\nou pica (apetite pervertido por barro ou terra, papeis, amido). Sendo INCORRETO apenas que:","options":{"A":"No entanto, muitos pacientes são assintomáticos, sem clínica típica e só reconhecem os\nsintomas retrospectivamente, após o tratamento.","B":"Pacientes com ferritina baixa e sem anemia podem ter os mesmos sintomas.","C":"Pode ainda ocorrer pica por gelo, que é considerada pouco específica para Deficiência de Ferro.","D":"Idosos costumam apresentar início insidioso com sintomas relacionados à exacerbação de suas\ncomorbidades subjacentes (piora da angina, aumento da confusão mental, dispneia)."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-181433","number":"181433","sourceNumber":"181433","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assim como ocorre nos lactentes, os adolescentes são uma população de risco para\nanemia ferropriva. A recomendação de 8 a 15 mg/kg/dia de ferro nessa fase se deve a:","options":{"A":"carências nutricionais por maior demanda energética.","B":"aumento do volume sanguíneo e diminuição da massa das hemácias.","C":"aumento de necessidades específicas para ganho\npondero-estatural.","D":"pico na velocidade de crescimento e aumento na massa das hemácias.","E":"dietas restritas e monótonas, especialmente em relação ao consumo de vegetais."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183119","number":"183119","sourceNumber":"183119","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A ADF ? Anemia por Deficiência de Ferro na gestação é frequentemente diagnosticada\ne tratada, mas os efeitos destes tratamentos\npermanecem largamente desconhecidos e mais\npesquisas precisam ser realizadas para melhorar o prognóstico materno e neonatal de mulheres\ncom anemia moderada e grave em lugares com poucos recursos. Sobre esse tema, assinale a\nalternativa INCORRETA:","options":{"A":"Pode também apontar para uma doença grave subjacente com sangramento oculto, que deve\nser afastada com investigação\n\nadequada em homens e mulheres na pós-menopausa, principalmente no que diz respeito ao\ndiagnóstico precoce da doença Maligna Colorretal.","B":"Independente da etiologia, quando o sangue tem células vermelhas insuficientes ou estas\ncarregam hemoglobina insuficiente\n\npara entregar oxigênio dequadamente para os tecidos significa que houve falha na produção das\nhemácias e sobrevém anemia,\n\nmuitas vezes multifatorial num mesmo indivíduo e por isto uma síndrome complexa para avaliação\ne estabelecimento da conduta a adotar.","C":"Alta prevalência de anemia não está associada à idade avançada e a condições agudas ou\ncrônicas, como a Doença Renal Crônica. Em\npessoas com 85 ou mais anos, a prevalência é de 5%\npara homens e de 20% para mulheres.","D":"Além disto, a ADF pode ser causada por hemorragias diversas, como as devidas a traumas ou\npor melena, hematêmese, hemoptise, menstruações, partos ou por múltiplas gestações."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-152636","number":"152636","sourceNumber":"152636","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente alimentado predominantemente com leite de cabra, poderia apresentar qual\ndeficiência?","options":{"A":"Piridoxina.","B":"Cálcio.","C":"Ácido Fólico.","D":"Ferro.","E":"Ácido ascórbico."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-161133","number":"161133","sourceNumber":"161133","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à função esplênica, é INCORRETO afirmar que:","options":{"A":"Durante o desenvolvimento fetal tem função hematopoiética.","B":"As opsoninas produzidas no baço, como properdina e tuftsina, encontram-se com níveis séricos\naumentados após esplenectomia.","C":"É a substância biológica removida pelo baço em indivíduos saudáveis: corpos de Howell-Jolly,\ncorpos de Heinz, acantócitos, hemácias\nsenescentes.","D":"O baço está envolvido na destruição de plaquetas na Púrpura Trombocitopênica Imune."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-158817","number":"158817","sourceNumber":"158817","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Anemias hemolíticas podem ser classificadas quanto ao local que ocorre a hemólise,\nsendo denominadas intra ou extravascular. Podem\ntambém ser classificadas de acordo com as\ncausas, como defeito intrínseco ou extrínseco as hemácias. Qual a causa de anemia hemolítica por\ndefeito intrínseco das hemácias?","options":{"A":"Hiperesplenismo.","B":"Deficiência de G6PD.","C":"Estenose de valva aorta.","D":"Anemia hemolítica autoimune.","E":"Hemoglobinúria paroxística noturna."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-161246","number":"161246","sourceNumber":"161246","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Podemos entender sobre as síndromes betatalassêmicas como um grupo de doenças\nhereditárias caracterizadas por uma deficiência genética na síntese de cadeias beta de globina.\n\nSobre isso, aponte a alternativa INCORRETA.","options":{"A":"A betatalassemia afeta um ou ambos os genes da betaglobina (cromossoma 11).","B":"Estas mutações pontuais, ou mais comumente deleções, causando uma inadequada síntese de\nbetaglobina, componente da hemoglobina, resultam em anemia.","C":"Ela é herdada como uma doença autossômica recessiva; no entanto, mutações dominantes\ntambém foram relatadas.","D":"O defeito pode ser uma ausência completa da proteína betaglobina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-161251","number":"161251","sourceNumber":"161251","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São fatores adicionais que influenciam as manifestações clínicas da Síndrome\nTalassêmica, ou seja, as mesmas mutações podem ter diferentes manifestações clínicas em\npacientes diferentes. Os seguintes fatores são conhecidos por influenciar o fenótipo clínico,\nEXCETO por","options":{"A":"concentrações de hemoglobina fetal intracelulares.","B":"anemia com necessidade de transfusão de hemácias.","C":"co-hereditariedade com talassemia alfa.","D":"coexistência de traço falciforme."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-158791","number":"158791","sourceNumber":"158791","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Kauê, dezesseis meses de vida, foi submetido a exames complementares: dosagem de\nferritina: 8 mcg/dl; ferro sérico: 25 mcg/dl; hemoglobina: 9 g/dl. Nesse caso, qual o diagnóstico\nmais\nprovável e a melhor conduta?","options":{"A":"Não tem anemia ferropriva e também não há indicação de iniciar profilaxia com ferro.","B":"Tem anemia ferropriva e já deve iniciar tratamento com 2 mg de ferro elementar/kg/dia.","C":"Tem anemia ferropriva e já deve iniciar tratamento com 5 mg de ferro elementar/kg/dia.","D":"Não tem anemia ferropriva, porém já se deve iniciar profilaxia com 2 mg de ferro\nelementar/kg/dia até os dois anos de vida.","E":"Não tem anemia ferropriva, porém já se deve iniciar profilaxia com 1 mg de ferro\nelementar/kg/dia até os dois anos de vida."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-134345","number":"134345","sourceNumber":"134345","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 87 anos de idade, diabético e hipertenso, em uso de glibenclamida,\nmetiformina e captopril. Evolui com acentuada\ndeterioração neurológica nos últimos 3 dias. Como\nfoi realizada tomografia de crânio sem contraste e essa não demonstrou achados que justificassem\no quadro, foi solicitado então tomografia com contraste. Aponte a alternativa em que o item NÃO\npode ser atribuído como boa prática.","options":{"A":"Tomografia sem contraste sempre antes, porque se ocorrer extravasamento de contraste ocorre\nextensão maior da lesão secundária.","B":"Podemos manter medicação ambulatorial.","C":"Pacientes internados e com deterioração se beneficiam com melhor controle metabólico.","D":"Importante adequada hidratação."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-109793","number":"109793","sourceNumber":"109793","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 7 anos é trazida ao Posto de Saúde pela mãe que refere que há 1\ndia seu filho vem apresentando urina de cor avermelhada, cefaleia e dificuldade para respirar.\nTem história prévia de febre e dor de garganta que melhorou com remédio caseiro. Ao exame,\nencontra-se descorado, edemaciado, afebril, FC = 110, FR = 25, Sat02 = 88% (AA), PA =\n130x85mmHg, ACV = RCR 2T sem sopro, AR = MV com roncos e diminuição em bases\nbilateralmente, Abdome globoso, RHA+. Qual o HD MAIS provável?","options":{"A":"Pneumonia com derrame pleural.","B":"Glomerulonefrite difusa aguda.","C":"Kawasaki.","D":"Amigdalite."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-86592","number":"86592","sourceNumber":"86592","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Das glomerulopatias abaixo, qual a que normalmente está associada à baixa do\ncomplemento sérico?","options":{"A":"Glomerulonefrite esclerosante focal.","B":"Nefropatia por IgA.","C":"Membranosa.","D":"Lesão mínima.","E":"Proliferativa difusa."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-108585","number":"108585","sourceNumber":"108585","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre o uso de diuréticos pode-se dizer:","options":{"A":"Ajudam a controlar quadros de hipeuricemia, principalmente os tiazidicos.","B":"Diferente das demais classes, a classe dos diuréticos de alça é muito bem tolerada em grandes\ndoses mesmo em pacientes com hipovolemia.","C":"São raramente utilizados nas síndromes nefróticas.","D":"Amilorida, triantereno e espironolactona são exemplos de diuréticos poupadores de potássio.","E":"Todas as anteriores."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-327260","number":"327260","sourceNumber":"327260","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, com história de sangramento oral durante a\nescovação dos dentes, equimoses pelo corpo\nsem causa aparente e hipermenorréia. Seu exame\nfísico da cabeça, tórax e abdome não apresenta alterações dignas de nota. Não há massas ou\nvisceromegalias abdominais palpáveis. Observam-se equimoses em joelhos e petéquias em\nmembros inferiores. No seu hemograma, o hematócrito, a hemoglobina e o leucograma são\nnormais, mas a contagem de plaquetas é de 22.000. Encaminhada para acompanhamento com o\nHematologista, foi submetido a mielograma que evidenciou presença normal de megacariócitos e\nnão foi observado sinal de malignidade. O Hematologista iniciou tratamento clínico com corticóides,\nporém obteve resposta não satisfatória, sendo encaminhado ao Cirurgião para avaliação da\npossibilidade de esplenectomia. Sobre o caso acima, assinale a alternativa CORRETA:","options":{"A":"A esplenectomia é bem indicada para o caso já que a esferocitose descrita acima não\nrespondeu adequadamente ao tratamento clínico.","B":"A plaquetopenia deve ser manejada com transfusão de concentrado de plaquetas 24 horas\nantes do procedimento cirúrgico.","C":"A esplenectomia deve ser postergada já que a patologia descrita evolui com sucessivos infartos\nesplênicos, evoluindo para progressiva perda de massa esplênica e asplenia.","D":"Esta paciente deverá ser vacinada contra Haemophilus influenza, Streptococcus pneumoniae e\nNeisseria meningitidis cerca de 2 semanas antes da esplenectomia."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-327283","number":"327283","sourceNumber":"327283","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"PSD, 9 anos, sexo feminino, natural e procedente da zona rural de Itacoatiara-AM,\nresidente em área, sem rede de esgoto e sem\ntratamento de água. Queixa de dores abdominais,\napresenta-se apático e só quer permanecer deitado. Ao exame, observa-se palidez cutânea, pele\ncom aspecto amarelado, embora não esteja ictérico. Na ausculta cardíaca: sopro sistólico ++/6+,\nem foco mitral sem irradiação, sem frêmito. Hemograma de urgência: Hg- 8,3g/dL; Ht-25%; VCM-\n63fl e RDW-21,5%. O diagnóstico mais provável e uma possível etiologia seria:","options":{"A":"Amenia Ferropriva secundária à Ancilostomíase.","B":"Anemia Megaloblástica secundária à dieta com leite de cabra.","C":"Beta-talassemia secundária à erro inato do metabolismo.","D":"Anemia de doença crônica secundária à Doença Inflamatória Intestinal."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-286762","number":"286762","sourceNumber":"286762","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Ana, 2 anos, foi diagnosticada com anemia ferropriva e recebeu prescrição de sulfato\nferroso 5 mg/kg/dia de ferro elementar. O\nparâmetro laboratorial mais específico para o diagnóstico\nde anemia por deficiência de ferro e o parâmetro laboratorial de resposta mais precoce ao\ntratamento são, respectivamente:","options":{"A":"Ferritina e hematócrito.","B":"Ferritina e reticulócitos.","C":"Ferro sérico e hematócrito.","D":"Ferro sérico e reticulócitos."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-252221","number":"252221","sourceNumber":"252221","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando as anemias hemolíticas autoimunes (AHAI), assinale a alternativa\nCORRETA:","options":{"A":"O teste de Coombs indireto detecta anticorpos na superfície das hemácias, enquanto o teste de\nCoombs direto detecta anticorpos no soro.","B":"A terapia com ciclosporina é a medida terapêutica de 1ª linha nas AHAI por anticorpos quentes.","C":"O teste de Coombs direto negativo na maioria das vezes, afasta a hipótese de anemia\nhemolítica.","D":"Anticorpos da classe IgM são os principais responsáveis pelas AHAI por anticorpos quentes,\ncausando hemólise extravascular."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-252281","number":"252281","sourceNumber":"252281","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pré-escolar de 02 anos, portador de anemia falciforme, é levado à emergência\napresentando dor abdominal, palidez acentuada\n(Hg 3 g/dl), hipovolemia, reticulocitose, taquicardia,\ntaquipneia, prostração, baço 5 cm do Rebordo Costal Esquerdo (RCE). A hipótese diagnóstica mais\nprovável é:","options":{"A":"Sequestro esplênico.","B":"Crise aplástica.","C":"Colelitíase aguda.","D":"Hepatite A."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-208410","number":"208410","sourceNumber":"208410","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A doença falciforme é uma alteração genética caracterizada por um tipo de\nhemoglobina mutante designada por hemoglobina S\n(ou Hb S) que provoca a distorção dos\neritrócitos, fazendo-os tomar a forma de \"foice\" ou \"meia-lua\". Avalie se as afirmativas a seguir\nsão\nfalsas (F) ou verdadeiras (V): I. O exame diagnóstico é a eletroforese de hemoglobina em acetato\nde celulose ou em agarose. II. A crise vaso-oclusiva é a principal característica da doença, resulta\nde um conjunto de interações do endotélio, fatores plasmáticos, leucócitos, falcização e rigidez\neritrocitária. III. As úlceras de perna podem estar presentes nos portadores de doença falciforme.\nAssinale a alternativa CORRETA:","options":{"A":"F, V e F","B":"V, V e F","C":"V, V e V","D":"F, V e V"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-208353","number":"208353","sourceNumber":"208353","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente de 11 meses, sexo feminino, foi atendida no serviço de ambulatório pois a\nmãe queixa de quadro de irritabilidade,\nanorexia, letargia e palidez. Ao exame, observamos palidez\nnas palmas das mãos, nos vincos palmares, unhas e conjuntiva. Tem exames laboratoriais com os\nseguintes resultados: hemoglobina = 9 g/dl; VCM < 70 mg/l; saturação da transferrina < 16%, RDW\naumentado e ferritina sérica diminuída. Qual o diagnóstico desta anemia?","options":{"A":"Anemia megaloblástica.","B":"Anemia ferropriva.","C":"Anemia falciforme.","D":"Anemia da doença crônica."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-151881","number":"151881","sourceNumber":"151881","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança com 15 meses de idade, apresentou as seguintes manifestações clínicas:\nretardo do crescimento, hepatomegalia,\nhipoglicemia grave, colesterol, triglicerídeos e ácido úrico\nelevados. Qual o defeito básico, característico nas doenças do metabolismo do carboidrato:","options":{"A":"Deficiência da enzima de ramificação.","B":"Deficiência de glicogênio síntetase.","C":"Deficiência de fosforilase hepática.","D":"Deficiência de glicose-6-fosfatase."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-151888","number":"151888","sourceNumber":"151888","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pré-escolar de 3 anos apresenta \"palidez\" nas palmas da mão, pregas palmares, leito\nungueal e conjuntivas, irritabilidade, anorexia, hemoglobina = 7 g/dl, RDW (índice de anisocitose)\n17%, VCM = 55 m³. A dieta da família é adequada, com boas condições socioeconômicas. Qual o\nexame abaixo mais indicado para a investigação da \"palidez\"?","options":{"A":"Hematoscopia.","B":"Parasitológico.","C":"Dosagem de ferritina.","D":"Pesquisa de sangue oculto nas fezes."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-103830","number":"103830","sourceNumber":"103830","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactentes que desenvolvem síndrome nefrótica dentro dos primeiros três meses de vida\nsão considerados como portadores de:","options":{"A":"Síndrome nefrótica primária.","B":"Síndrome nefrótica secundária.","C":"Síndrome nefrótica congênita.","D":"Síndrome nefrótica idiopática."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-80947","number":"80947","sourceNumber":"80947","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Entre os achados abaixo, qual é o menos esperado na evolução da Glomerulonefrite\nDifusa Aguda (GNDA) ou glomerulonefrite\npós-infecciosa?","options":{"A":"Edema.","B":"Proteinúria maior que 3,5 g/24h.","C":"Hipertensão arterial.","D":"Hemácias dismórficas na urina.","E":"Oligúria."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-60825","number":"60825","sourceNumber":"60825","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Podem estar associados ao surgimento de síndrome nefrítica, EXCETO:","options":{"A":"Citomegalovírus.","B":"Treponema pallidum.","C":"Plasmodium malariae.","D":"Staphylococcus aureus.","E":"Strongyloides stercoralis."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-61538","number":"61538","sourceNumber":"61538","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em um paciente com insuficiência renal pré-renal, os achados abaixo são esperados,\nEXCETO:","options":{"A":"Sódio urinário menor que 20 mEq/L.","B":"Cilindros hialinos no sedimento urinário.","C":"Fração excretora de sódio menor que 1%.","D":"Razão ureia: creatinina sérica maior que 20:1.","E":"Osmolaridade urinária menor que 500 mOsm/kg."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-49806","number":"49806","sourceNumber":"49806","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual dos achados abaixo é o menos provável de ser encontrado na Nefropatia por\nLesão Mínima?","options":{"A":"Edema.","B":"Hiperlipidemia.","C":"Hematúria.","D":"Hipoalbuminemia.","E":"Cilindros graxos na urina."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-26455","number":"26455","sourceNumber":"26455","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O mecanismo pelo qual os Anti-inflamatórios Não Hormonais (AINH) podem levar à\nInsuficiência Renal (IR) é:","options":{"A":"aumento da diurese provocando uma IRA pré-renal.","B":"estimulação da produção das prostaglandinas renais que normalmente mantêm a arteríola\naferente dilatada.","C":"inibição da produção das prostaglandinas renais que normalmente mantêm a arteríola aferente\ndilatada.","D":"estimulação da produção das prostaglandinas renais que normalmente mantêm a arteríola\neferente dilatada.","E":"inibição da produção das prostaglandinas renais que normalmente mantêm a arteríola eferente\ndilatada."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-26456","number":"26456","sourceNumber":"26456","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A glomerulonefrite difusa aguda (GNDA) é uma doença:","options":{"A":"que acomete especialmente os lactentes","B":"que se manifesta com edema, habitualmente devido a perda protéica urinária","C":"cuja evolução para cronicidade ocorre em cerca de 20% dos casos","D":"que pode ocorrer após infecção por alguns agentes infecciosos, sendo o mais importante o\nStreplococcus beta-hemolítico do grupo A","E":"na qual os níveis de C3 são elevados"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-26682","number":"26682","sourceNumber":"26682","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na glomerulonefrite aguda pós-infecciosa, é correto:","options":{"A":"Não existe hipertensão arterial","B":"A hematúria é não dismórfica","C":"O prognóstico em 90% dos casos tem evolução desfavorável","D":"O complemento C3 está baixo","E":"70% dos glomérculos tem crescentes epiteliais"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-26518","number":"26518","sourceNumber":"26518","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Escolar de 8 anos, apresentando quadro sugestivo de GNDA pós estreptocócica, na\nquarta semana de doença ainda mantém\nhipertensão arterial e hematúria macroscópica. Exames\ncomplementares: Proteinúria 70 mg/Kg/dia; ureia 90 mg/dl; creatinina 3,7 mg/dl; ultrassonografia de\nvias urinária, rins aumentados de volume, sem perda da relação corticomedular. Neste caso\n\nindica-se:","options":{"A":"Restrição hídrica rigorosa e dieta hipoproteica;","B":"Plasmaférese e pulsoterapia ciclofosfamida;","C":"Biópsia renal e pulsoterapia com metilprednisolona;","D":"Diuréticos de alça e inibidores da enzima conversora;","E":"Corticoide e ciclofosfamida por via oral;"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-324668","number":"324668","sourceNumber":"324668","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher, 40 anos de idade, procura a UBS por apresentar olhos amarelados,\nesporadicamente. Nega comorbidades ou uso de\nmedicações. Ao exame físico, bom estado geral,\nsinais vitais estáveis, icterícia 1+ / 4. Não há alterações no exame segmentar, exceto espaço de\nTraube ocupado. Solicitados exames, com os seguintes resultados: Hb: 10,5g/dL, VCM: 100fL,\nCHCM: 35,1g/dL, RDW: 17%, leucócitos: 5930/mm³, plaquetas: 160mil/mm³, ferritina: 1000ng/mL,\níndice de saturação de transferrina: 54%, bilirrubinas totais: 3,8g/dL, direta: 0,9g/dL, indireta:\n2,89g/dL, AST: 26U/L (VR: 31), ALT: 29U/L (VR: 31U/L), Albumina: 4,0g/dL, RNI: 1,0.\n\nConsiderando o caso clínico descrito, indique o resultado mais provável no caso, entre os seguintes\nexames:","options":{"A":"Haptoglobina baixa.","B":"Reticulócitos baixos.","C":"Ácido metilmalônico elevado.","D":"Lactato desidrogenase baixa."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-324669","number":"324669","sourceNumber":"324669","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher, 40 anos de idade, procura a UBS por apresentar olhos amarelados,\nesporadicamente. Nega comorbidades ou uso de\nmedicações. Ao exame físico, bom estado geral,\nsinais vitais estáveis, icterícia 1+ / 4. Não há alterações no exame segmentar, exceto espaço de\nTraube ocupado. Solicitados exames, com os seguintes resultados: Hb: 10,5g/dL, VCM: 100fL,\nCHCM: 35,1g/dL, RDW: 17%, leucócitos: 5930/mm³, plaquetas: 160mil/mm³, ferritina: 1000ng/mL,\níndice de saturação de transferrina: 54%, bilirrubinas totais: 3,8g/dL, direta: 0,9g/dL, indireta:\n2,89g/dL, AST: 26U/L (VR: 31), ALT: 29U/L (VR: 31U/L), Albumina: 4,0g/dL, RNI: 1,0. Diante do\n\nquadro, indique o exame mais importante para realização do diagnóstico etiológico:","options":{"A":"Pesquisa de mutação para hemocromatose hereditária.","B":"Coombs direto.","C":"Biópsia hepática.","D":"Colangiopancreatografia por ressonância magnética (CPRM)."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-324670","number":"324670","sourceNumber":"324670","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher, 40 anos de idade, procura a UBS por apresentar olhos amarelados,\nesporadicamente. Nega comorbidades ou uso de\nmedicações. Ao exame físico, bom estado geral,\nsinais vitais estáveis, icterícia 1+ / 4. Não há alterações no exame segmentar, exceto espaço de\nTraube ocupado. Solicitados exames, com os seguintes resultados: Hb: 10,5g/dL, VCM: 100fL,\nCHCM: 35,1g/dL, RDW: 17%, leucócitos: 5930/mm³, plaquetas: 160mil/mm³, ferritina: 1000ng/mL,\níndice de saturação de transferrina: 54%, bilirrubinas totais: 3,8g/dL, direta: 0,9g/dL, indireta:\n2,89g/dL, AST: 26U/L (VR: 31), ALT: 29U/L (VR: 31U/L), Albumina: 4,0g/dL, RNI: 1,0. Identifique o\nmecanismo patológico relacionado à esplenomegalia apresentada pela paciente:","options":{"A":"Hipertensão portal.","B":"Depósito de ferro.","C":"Depósito de proteína amiloide.","D":"Aumento da função fagocítica."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-284613","number":"284613","sourceNumber":"284613","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menina, 8 anos de idade, negra, encaminhada para avaliação no ambulatório de\nreferência com história de anemia crônica. A\nacompanhante (tia) relata que a menor queixa-se de\ncansaço fácil e dor em membros inferiores, frequentemente. Refere anorexia. Não sabe informar\nsobre quadro semelhante em familiares. Ao exame está em regular estado geral, ativa, hidratada,\neupneica, afebril, sem alterações em dados vitais; peso: 24 kg; com mucosas descoradas ++/IV.\nNão há adenomegalias. A ausculta cardíaca apresenta sopro holossistólico II/VI, audível em focos\nda base. Ausculta respiratória e restante do exame segmentar sem alterações. Exames realizados\nhá 45 dias: hematócrito: 24,6% e hemoglobina: 8,2 g/dl. Indique o parâmetro que aponta a\npresença de anisocitose no hemograma, nesse caso:","options":{"A":"RDW.","B":"VCM.","C":"HCM.","D":"Contagem de reticulócitos."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-284614","number":"284614","sourceNumber":"284614","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menina, 8 anos de idade, negra, encaminhada para avaliação no ambulatório de\nreferência com história de anemia crônica. A\nacompanhante (tia) relata que a menor queixa-se de\ncansaço fácil e dor em membros inferiores, frequentemente. Refere anorexia. Não sabe informar\nsobre quadro semelhante em familiares. Ao exame está em regular estado geral, ativa, hidratada,\neupnéica, afebril, sem alterações em dados vitais; Peso: 24 Kg; com mucosas descoradas ++/IV.\nNão há adenomegalias. A ausculta cardíaca apresenta sopro holossistólico II/VI, audível em focos\nda base. Ausculta respiratória e restante do exame segmentar sem alterações. Exames realizados\nhá 45 dias: hematócrito: 24,6% e hemoglobina: 8,2g/dL. Indique o achado, no esfregaço de sangue\nperiférico, que permitiria fechar o diagnóstico etiológico (e patognomônico) desse tipo de anemia.","options":{"A":"Ovalócitos.","B":"Esferócitos.","C":"Drepanócitos.","D":"Hemáceas em alvo."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-284615","number":"284615","sourceNumber":"284615","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menina, 8 anos de idade, negra, encaminhada para avaliação no ambulatório de\nreferência com história de anemia crônica. A\nacompanhante (tia) relata que a menor queixa-se de\ncansaço fácil e dor em membros inferiores, frequentemente. Refere anorexia. Não sabe informar\nsobre quadro semelhante em familiares. Ao exame está em regular estado geral, ativa, hidratada,\neupnéica, afebril, sem alterações em dados vitais; Peso: 24 Kg; com mucosas descoradas ++/IV.\nNão há adenomegalias. A ausculta cardíaca apresenta sopro holossistólico II/VI, audível em focos\nda base. Ausculta respiratória e restante do exame segmentar sem alterações. Exames realizados\nhá 45 dias: hematócrito: 24,6% e hemoglobina: 8,2g/dL. Indique o momento a partir do qual o\nexame específico pode ser realizado para o diagnóstico definitivo da causa da anemia em foco.","options":{"A":"Desde o nascimento.","B":"Após o período neonata.l","C":"Após o primeiro ano de vida.","D":"A partir de 3 meses de idade."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62795","number":"62795","sourceNumber":"62795","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, sexo masculino, 25 anos de idade, tabagista, evolui há uma semana com\nquadro de febre, hemoptise, dispneia e hematúria. Há 48 horas, relata diminuição do volume\nurinário. Diante desses achados clínicos, a principal suspeita diagnóstica é:","options":{"A":"Lúpus eritematoso sistêmico.","B":"Poliarterite nodosa.","C":"Sarcoidose.","D":"Púrpura de Henoch-Schönlein.","E":"Síndrome de Goodpasture."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62799","number":"62799","sourceNumber":"62799","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, sexo masculino, 25 anos de idade, tabagista, evolui há uma semana com\nquadro de febre, hemoptise, dispneia e hematúria. Há 48 horas, relata diminuição do volume\nurinário. A melhor opção terapêutica para esse caso é:","options":{"A":"Plasmaférese e corticoide.","B":"Transplante renal.","C":"Pulsoterapia com corticoide.","D":"Corticoide e ciclofosfamida.","E":"Imunoglobulina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62802","number":"62802","sourceNumber":"62802","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, 70 anos de idade, portador de hipertensão arterial sistêmica, diabetes e\ndislipidemia, realizou cineangiocoronariografia após quadro de angina instável. Nega insuficiência\nrenal prévia. Após 15 dias do procedimento, evolui com quadro de febre, dor abdominal e livedo\nreticular em membros inferiores. A avaliação laboratorial mostrou leucograma de 14500 com 15%\nde eosinófilo, LDH: 1500 e cretinina: 2,4 mg/dl. O diagnóstico mais provável é","options":{"A":"nefropatia por contraste.","B":"ateroembolismo.","C":"tromboangeíte obliterante.","D":"dissecção de aorta.","E":"vasculite de Churg-Strauss."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62825","number":"62825","sourceNumber":"62825","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, 34 anos de idade, branco, admitido em unidade hospitalar com quadro de\nanasarca. Sumário de urina com proteína ++++. Foi feita suspeita de síndrome nefrótica. No\nterceiro dia de internamento, evoluiu com quadro de dispneia súbita. Pressão arterial normal e\nradiografia de tórax com pequeno derrame pleural à direita. O padrão de histologia renal mais\nprovável para esse caso é","options":{"A":"lesão mínima.","B":"membranosa.","C":"glomeruoesclerose segmentar e focal.","D":"membranoproliferativa.","E":"glomerulonefrite mesangiocapilar."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62865","number":"62865","sourceNumber":"62865","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, sexo feminino, seis anos de idade, é internada com história de oligúria,\ncefaleia e aumento de peso. Acompanha febre\nbaixa. Ao exame físico, REG, ativa, eupneica, TA:\n130 X 90 mmHg, edema nos MMII. Os exames laboratoriais iniciais mostram hemograma com\ndiscreta anemia normocítica normocrômica, ureia um pouco elevada, creatinina no limite superior.\nSumário de urina com hemácias ++++, proteína +, bactérias. O diagnóstico mais provável é:","options":{"A":"glomerulonefrite aguda.","B":"síndrome nefrótica.","C":"ITU.","D":"litíase renal.","E":"abscesso renal."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-49451","number":"49451","sourceNumber":"49451","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem, 32 anos de idade, descendente de orientais, durante periódico de saúde, fez\nexames com os seguintes resultados: creatinina sérica = 1,8 mg/dl, ureia = 46 mg/dl, ácido úrico =\n8,0 mg/dl. Sumário de urina: hemoglobina ++, proteínas ++, 35 hemácias/campo, com hemácias\ncrenadas. Ultrassonografia de aparelho urinário normal. Hemograma sem alterações. O paciente\nestá assintomático. Relata um episódio de urina avermelhada há um ano, após esforço físico. Nega\nlesões de pele, nega secreções ou sintomas uretrais. Exames anteriores mostram contagens de\nhemácias superiores a 15/campo, nos últimos quatro anos. Ao exame físico, apresenta PA = 140 x\n90 mmHg, sem outras alterações. O diagnóstico mais provável é:","options":{"A":"Urolitíase por oxalúria.","B":"Papiloma de bexiga.","C":"Nefropatia por deposição de lgA.","D":"Hemoglobinúria paroxística.","E":"Hematúria benigna do exercício."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-49468","number":"49468","sourceNumber":"49468","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem, 33 anos de idade, mulato, há um mês com anasarca e hipertensão arterial.\nNega história de hepatite, uso de álcool ou\ndrogas. Nega diabetes. Pai e mãe são hipertensos.\nExame físico: edema periorbitário, PA: 150 x 100 mmHg. Palidez cutaneomucosa. Sem estase de\njugulares. Aparelho respiratório: murmúrios rudes em bases. Aparelho cardiovascular: íctus no 5º\nEICE. Bulhas rítmicas, 2T. Abdome: ascite moderada, fígado e baço impalpáveis. Edema de MMII\naté a raiz das coxas, frio e depressivo. Exames de laboratório: ureia: 75 mg/dl, creatinina: 2,0 ,\nalbumina sérica: 1,8 g/dl, anti-HCV negativo. Proteinúria de 24 horas: 3,2 g. Glicemia: 100 mg/dl. A\nabordagem farmacológica mais eficiente para evitar a progressão da doença, no caso, preconiza o\nuso de:","options":{"A":"Diuréticos de alça.","B":"Albumina.","C":"Corticosteroides.","D":"Inibidores de enzima de conversão de angiotensina.","E":"Bloqueadores de canais de cálcio."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-34953","number":"34953","sourceNumber":"34953","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A manifestação mais comum de nefrotoxicidade, após uso de anti-inflamatórios não\nhormonais, é:","options":{"A":"hemodinamicamente mediada com diminuição da síntese renal de prostaglandinas.","B":"nefrite intersticial aguda por reação imunológica.","C":"síndrome nefrótica por aumentar a excreção de proteínas urinárias.","D":"necrose cortical por mecanismos ainda não esclarecidos.","E":"obstrução tubular por precipitação intraluminal de ácido úrico."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-27502","number":"27502","sourceNumber":"27502","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, 13 anos de idade, sexo masculino, há 4 anos iniciou com quadro de edema\nprogressivo, acompanhado de baixa da acuidade auditiva. Os exames realizados mostram\nelevação de ureia e creatinina, hematúria, proteinúria. A história familiar revelou que dois tios\nmaternos apresentaram insuficiência renal associada às alterações auditivas. Nos antecedentes do\npaciente, consta hematúria microscópica notada desde os 5 anos de idade. O diagnóstico mais\nprovável é:","options":{"A":"infecção urinária.","B":"síndrome de Alport.","C":"refluxo vesicoureteral.","D":"glomerulonefrite pós-estreptocócica .","E":"vasculite renal do lúpus."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-11152","number":"11152","sourceNumber":"11152","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, branco, sexo masculino, iniciou, aos 3 anos e 11 meses, edema progressivo\naté anasarca, em 2 semanas. A genitora relata\naumento de 3 kg. Antecedentes pessoais não\nsignificativos. História familiar: mãe e tio maternos albinos. Ao exame físico, apresentava-se\nnormotenso, com edema generalizado, peso de 23 kg, altura de 107 cm. Os exames\ncomplementares iniciais revelaram hipoalbuminemia de 1,4 g/dl e proteinúria de 4,7 g/dia. O\ndiagnóstico mais provável é:","options":{"A":"síndrome nefrótica.","B":"citomegalia.","C":"tuberculose renal.","D":"AIDS/SIDA.","E":"síndrome nefrítica."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-11195","number":"11195","sourceNumber":"11195","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança, 5 anos de idade, vem há 2 semanas com febre, mal estar e dor nas\narticulações. Há 8 dias vem apresentando edema\nem face e MMII, urina escura e em menor\nquantidade. Ao exame, TA: 140 x 100 mm/Hg. O exame de urina mostra hemácias +++, proteínas\n\n++, cilindros hemáticos e granulosos. Ureia e creatinina discretamente elevados. O diagnóstico\nmais provável é:","options":{"A":"infecção urinária","B":"síndrome nefrótica","C":"glomerulonefrite aguda","D":"litíase renal","E":"lúpus eritematoso sistêmico"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-11196","number":"11196","sourceNumber":"11196","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança, 5 anos de idade, vem há 2 semanas com febre, mal estar e dor nas\narticulações. Há 8 dias vem apresentando\nedema em face e MMII, urina escura e em menor\nquantidade. Ao exame, TA: 140x100 mm/Hg.O exame de urina mostra hemácias +++, proteínas ++,\ncilindros hemáticos e granulosos. Ureia e creatinina discretamente elevados. Os exames indicados\npara identificação do agente causal dessa patologia são:","options":{"A":"ASLO e cultura de orofaringe","B":"complemento sérico, fração C8 e fração C10","C":"sumário e cultura de urina","D":"pesquisa de células LE e FAN","E":"biópsia renal e histoquímica"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-314291","number":"314291","sourceNumber":"314291","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre a anemia falciforme, analise as assertivas e identifique com V as verdadeiras e\ncom F as falsas. ( ) A anemia falciforme\nestá associada a um estado inflamatório crônico. ( ) O\nendotélio vascular lesado na crise vasoclusiva libera fatores pró-coagulantes e vasoconstrictores.\n( )\nOs pacientes com anemia falciforme apresentam níveis reduzidos de marcadores de ativação da\ntrombina, plaquetas e células endoteliais, mostrando que não há ativação da coagulação na\ndoença. A alternativa que contém a sequência correta, de cima para baixo, é","options":{"A":"F V F","B":"F F V","C":"V F V","D":"V F F","E":"V V F"},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-283845","number":"283845","sourceNumber":"283845","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 19 anos, com queixa de fadiga importante, ao exame físico, visto hipocromia\nacentuada de mucosas. Na investigação laboratorial, foi diagnosticada anemia com 5% de\nreticulócitos. A alternativa que contém a causa para essa anemia é","options":{"A":"Doença inflamatória crônica.","B":"Deficiência de vitamina B12.","C":"Policitemia vera.","D":"Ferropriva.","E":"Hemólise."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249987","number":"249987","sourceNumber":"249987","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa incorreta sobre a alfa talassemia:","options":{"A":"Os indivíduos com deleção de 2 alfa-globinas são descritos como portadores de traço\nalfa-talassêmico.","B":"A anemia ferropriva, a saturação de ferro e a ferritina normais são diagnósticos diferenciais.","C":"A alfa-talassemia major é extremamente rara.","D":"A alfa-talassemia ocorre pelo aumento da cadeia de alfa da globina, havendo sobra de cadeia\nbeta."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249988","number":"249988","sourceNumber":"249988","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A avaliação do paciente com anemia deve conter obrigatoriamente uma história familiar\ne pessoal detalhada, além de exame físico\ncompleto e exames laboratoriais inicias. Dentro dos\nexames laboratoriais que devem ser solicitados em um primeiro momento estão todos os abaixo,\nexceto:","options":{"A":"Hemograma completo.","B":"Contagem de reticulócitos.","C":"DHL.","D":"Hematoscopia."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249989","number":"249989","sourceNumber":"249989","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação à anemia, assinale a alternativa a alternativa correta:","options":{"A":"A anemia é um diagnóstico que atinge até 25% da população.","B":"Os quadros crônicos de anemia sempre apresentam palidez, taquicardia e letargia.","C":"A produção diária de reticulócitos é maior do que a destruição m condições fisiológicas.","D":"A capacidade de fixação do ferro (TIBC) auxilia no cálculo de saturação de ferro para avaliar a\npresença de deficiência de ferro."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249991","number":"249991","sourceNumber":"249991","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa correta sobre o traço falcêmico.","options":{"A":"Apresenta hemograma normal.","B":"Apresenta anemia leve a moderada.","C":"Apresenta esplenomegalia discreta.","D":"Apresenta dores ósseas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-181149","number":"181149","sourceNumber":"181149","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O achado de glicosúria isolada em um exame de urina, não associada à hiperglicemia\ndo paciente, sugere alteração em qual segmento\nrenal?","options":{"A":"No túbulo distal.","B":"Na alça de Henle.","C":"No tubo coletor.","D":"No túbulo proximal."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-111832","number":"111832","sourceNumber":"111832","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 7 anos é trazida ao Posto de Saúde pela mãe que refere que há 1 dia seu\nfilho vem apresentando urina de cor\navermelhada, cefaleia e dificuldade para respirar. Tem história\nprévia de febre e dor de garganta que melhorou com remédio caseiro. Ao exame, encontra-se\ndescorado, edemaciado, afebril, FC = 110, FR = 25, Sat02 = 88% (AA), PA = 130 x 85 mmHg, ACV\n\n= RCR 2T sem sopro, AR = MV com roncos e diminuição em bases bilateralmente, Abdome\ngloboso, RHA+. Qual é o HD MAIS provável?","options":{"A":"Pneumonia com derrame pleural.","B":"Glomerulonefrite difusa aguda.","C":"Kawasaki.","D":"Amigdalite."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-111845","number":"111845","sourceNumber":"111845","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Correlacione as colunas. (a) Síndrome Nefrótica. (b) GNDA. (c) ITU. (d) Néfron. (e)\nHematúria. ( ) Urocultura define o diagnóstico. ( ) Edema, proteinúria e hipoalbuminemia. ( )\nUnidade formadora do rim. ( ) Edema, hematúria e hipertensão. ( ) Presença de glóbulos\nvermelhos na urina, acima de um limite estabelecido.","options":{"A":"a / b / d / c / e.","B":"c / a / d / b / e.","C":"a / b / c / e / d.","D":"c / b / d / a / e."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-111881","number":"111881","sourceNumber":"111881","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dos elementos abaixo, quais são aqueles que NÃO são encontrados habitualmente no\nexame de Urina Tipo 1?","options":{"A":"Glicose e Aminoácidos.","B":"Sódio e Glicose.","C":"Sódio e Potássio.","D":"Aminoácidos e Potássio."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-350875","number":"350875","sourceNumber":"350875","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem, 58 anos, apresenta adinamia progressiva há 6 meses, associada a perda\nponderal de 8kg no mesmo período (peso\nhabitual 78kg e atual 70kg) e constipação de início\nrecente. Buscou assistência médica, sendo observado ao exame físico palidez cutâneo-mucosa\n2+/4+, hemodinamicamente estável, sendo solicitados os seguintes exames: Hemoglobina 9,2g/dL\n(V.R.?13g/dL), VCM 68fL (V.R 80 A 98fL), CHCM 25g/dL (V.R. 32 a 36d/dL), RDW 21% (V.R. 11 a\n\n15%), Leucócitos 9800 com diferencial normal Plaquetas 522mil. Qual a melhor abordagem\ndiagnóstica a seguir?","options":{"A":"Referenciar paciente para hematologista.","B":"Solicitar dosagem de vitamina B12 e ácido fólico e endoscopia digestiva alta.","C":"Solicitar reticulócitos, índice de saturação de transferrina, ferritina e colonoscopia.","D":"Solicitar eletroforese de proteínas séricas, mielograma, imunofenotipagem e biopsia óssea."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-321299","number":"321299","sourceNumber":"321299","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, 72 anos, sexo masculino, diagnosticado com hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, desde os 56 anos, sob uso de losartana e metformina desde então, com\nbom controle pressórico e dos níveis glicêmicos. Apresenta ainda doença renal crônica estágio 2,\nem conduta expectante. Em consulta de rotina, referiu que há 4 meses apresenta \"formigamento\"\nem mãos, bilateralmente, indolor, sem outras queixas. Ao exame, apresenta discreta palidez\ncutâneo-mucosa, redução da sensibilidade vibratória e proprioceptiva distal em membros\nsuperiores, função motora preservada, sem alterações em membros inferiores. Foram solicitados\nexames complementares laboratoriais que evidenciaram: Hb 10,1g/dl; Ht 30%; VCM 122 fL CHCM\n32g/dL; Leucócitos 2900/mm³; Neutrófilos 1520/mm³; Linfócitos 880/mm³; Plaquetas 88000/mm³;\nUreia 66mg/dL; Cr 1,2mg/dL; Proteínas totais 6,9g/dL; Albumina 4,6g/dL; Globulina 2,3g/dL; Cálcio\nsérico 8,6 mg/dL HbA1c 5,6%. Qual a melhor investigação a ser realizada e o diagnóstico mais\nprovável?","options":{"A":"Aspirado de medula óssea, visto tratar-se provavelmente de leucemia aguda.","B":"Eletroneuromiografia de quatro membros, visto tratar-se de quadro típico de neuropatia\ndiabética.","C":"Eletroforese e imunofixação de proteínas séricas, visto quadro clínico-laboratorial sugestivo de\nmieloma múltiplo.","D":"Dosagem de reticulócitos, vitamina B12, bilirrubina indireta e desidrogenase láctica, visto\nhipótese diagnóstica de deficiência de vitamina B12."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-292814","number":"292814","sourceNumber":"292814","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, 26 anos, procura unidade básica de saúde com queixa de adinamia leve,\ngengivorragia durante escovação e parestesias em mãos e pés. Refere que os sintomas iniciaram\nhá cerca de 6 semanas. Refere que há 2 anos faz reposição de levotiroxina, pois \"tireoide deixou\nde funcionar\"(sic). Ao exame físico, apresentava palidez cutâneo-mucosa 2+/4+, língua\ndespapilada, ausência de adenomegalias ou visceromegalias. Foi solicitado hemograma que\nevidenciou hemoglobina 7,8 g/dL, hematócrito 22%, VCM 118, leucócitos 4.800 (neutrófilos 1.580),\nplaquetas 42.000/mm3, reticulócitos 38.000. Considerando a principal hipótese diagnóstica, que\noutros exames laboratoriais devem ser solicitados a fim de confirmar o diagnóstico e qual alteração\nesperada nesses exames?","options":{"A":"Desidrogenase láctica elevada, homocisteína diminuída e bilirrubina indireta elevada.","B":"Teste de antiglobulina direta positivo, bilirrubina direta elevada e homocisteína diminuída.","C":"Ácido metilmalônico elevado, bilirrubina indireta elevada e desidrogenase láctica elevada.","D":"Índice de saturação de transferrina diminuído, ferritina diminuída e desidrogenase láctica\nnormal."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-259715","number":"259715","sourceNumber":"259715","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 22 anos, sem comorbidades, vem em consulta ambulatorial com queixa de\nfadiga há 3 meses. Apresenta exame físico inalterado, exceto pela presença de palidez\n\ncutâneo-mucosa. Traz o seguinte hemograma: hemoglobina 9,0 g/dl (Valor de referência (VR):12 a\n\n16); hematócrito 23% (VR: 36 a 48); VCM 80 fl (VR: 76 a 100); HCM 24 (VR: 27 a 33); CHCM 28\n\n(VR: 32 a 36); leucócitos 6.800/mm3; plaquetas 250.000/mm3 (VR: 140.000 a 450.000). Contagem\nde reticulócitos 100.000/mm3. Ausência de\nalterações morfológicas no esfregaço do sangue\nperiférico. A investigação laboratorial subsequente mais indicada para essa paciente é:","options":{"A":"Cinética de ferro e mielograma.","B":"Mielograma, função renal e função tireoidiana.","C":"Cinética de ferro, função renal e função tireoidiana.","D":"Cinética de ferro, dosagem de vitamina B12 e dosagem de ácido fólico."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-234043","number":"234043","sourceNumber":"234043","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente masculino, 25 anos, vegetariano, apresenta-se para exame admissional com\nexames realizados. Traz o seguinte hemograma:\nhemácias = 5,3 milhões/mm³ (VR = 4,5?6\nmilhões/mm³); Hb = 11,1 g/dl (VR = 13,5?17,5); Ht = 33% (VR = 40?52); VCM = 72 fl (VR = 81?99);\nHCM = 25 pg (VR = 30?34); RDW = 13% (VR = 12?14); leucócitos = 6.500/mm³ (VR =\n\n4.000?10.000); plaquetas = 452.000/mm³ (VR = 150.000?450.000) ? presença de hemácias em\nalvo. Demais exames sem anormalidades. Nega\netilismo. Relata estar assintomático e nega\ndoenças prévias, mas relata que sempre teve alguma alteração em hemogramas anteriores, sendo\nque nunca lhe foi orientado nenhum tratamento específico. LEGENDA: VR = Valor de Referência;\nVCM = Volume Corpuscular Médio; HCM = Hemoglobina Corpuscular Média; RDW = índice de\nanisocitose. Em relação ao diagnóstico provável para a anemia encontrada, qual exame seria mais\nespecífico para confirmação?","options":{"A":"Perfil bioquímico do ferro.","B":"Dosagem de vitamina B12.","C":"Eletroforese de hemoglobina.","D":"Mielograma usando corante azul da Prússia."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-234047","number":"234047","sourceNumber":"234047","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Alice, 9 meses de idade, é atendida no ambulatório de puericultura com história de\npalidez cutâneo-mucosa progressiva e irritabilidade há 3 meses. Refere aleitamento materno\nexclusivo até os 2 meses de idade e depois iniciado leite de cabra. Apresenta dieta pobre em\ncarnes e verduras. O pediatra diagnosticou anemia por deficiência de folatos. Quais alterações\ndescritas abaixo no hemograma são mais compatíveis com essa anemia?","options":{"A":"Anisocitose, macrocitose, trombocitopenia, leucopenia.","B":"Anisocromia, neutrófilos hipersegmentados, leucocitose.","C":"Poiquilocitose, hipercromia, reticulocitose, pancitopenia.","D":"Anisopoiquilocitose, microcitose, trombocitose, neutropenia."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-199841","number":"199841","sourceNumber":"199841","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente masculino de 26 anos comparece ao pronto-socorro referindo anemia desde a\ninfância e que há um dia iniciou com quadro de dor em membros inferiores, no momento, de forte\nintensidade. Nega febre, dispneia ou outras queixas. Encontra-se descorado, ictérico, eupneico e\ncom fácies de dor. Hemograma evidenciou hemoglobina = 6,2 g/dl, leucócitos = 13.400/mm³, com\nneutrofilia e plaquetas = 762.000/mm³. A lâmina de sangue periférico encontra-se em anexo. Além\nda busca por foco infeccioso e analgesia, qual melhor abordagem imediata para controle do\nquadro?","options":{"A":"Hidratação vigorosa.","B":"Antibiótico empírico.","C":"Transfusão simples de concentrado de hemácias.","D":"Transfusão de troca de concentrado de hemácias."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-150876","number":"150876","sourceNumber":"150876","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente feminino, 20 anos, procura ambulatório queixando-se de fraqueza, mal-estar e\ndores ocasionais nas pernas há aproximadamente um mês. Ao exame físico, apresenta língua\ncareca, palidez cutâneo-mucosa, frequência cardíaca de 88 batimentos por minuto, sem outras\nalterações. Ao hemograma, apresenta Hb = 7,0 g/dl; VCM = 62 fl; RDW = 18%; leucócitos = 3.700;\nneutrófilos = 2.200; plaquetas = 615.000/mm³. Qual a conduta apropriada, além da revisão do\nesfregaço do sangue periférico e da contagem de reticulócitos?","options":{"A":"Solicitar eletroforese de hemoglobina, iniciar ácido fólico e avaliar indicação de início de\ntransfusão crônica.","B":"Solicitar Coombs direto, desidrogenase láctica, bilirrubina total e frações, e iniciar\ncorticoide e\nácido fólico.","C":"Solicitar proteína C-reativa, VHS, investigar doença de base e transfundir uma unidade de\nconcentrado de hemácias.","D":"Solicitar ferro, ferritina e capacidade total de fixação do ferro, iniciar ferro oral e avaliar\nfonte de\nsangramento."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-150827","number":"150827","sourceNumber":"150827","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente masculino, 50 anos, encontra-se internado para investigação de síndrome\nconsumptiva. Relata desconforto abdominal e constipação, sem outras queixas. Ao exame físico,\nencontra-se descorado 2+/4+; FC = 82 bpm; PA = 132 x 86 mmHg, sem outras alterações.\n\nApresenta hemograma com Hb = 7,1 g/dl; VCM = 92 fl; RDW = 16%; leucócitos = 5.300/mm³,\ndiferencial normal e plaquetas de 322.000/mm³. Qual a conduta apropriada?","options":{"A":"Não transfundir e iniciar reposição de ferro e ácido fólico.","B":"Não transfundir e iniciar investigação com contagem de reticulócitos.","C":"Transfundir concentrado de hemácias e solicitar hemograma para avaliar incremento.","D":"Transfundir concentrado de hemácias e solicitar endoscopia digestiva para investigação."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-150855","number":"150855","sourceNumber":"150855","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A mãe de um menino de cinco anos de idade relata que ele está com aparência\nanêmica, nas últimas duas semanas, sem causa\naparente. Ao exame clínico, apresenta apenas\npalidez cutâneo-mucosa e leve icterícia; o restante do exame é normal. Os resultados laboratoriais\nrevelam hemoglobina de 6,5 g% e Coombs direto positivo. Qual a principal hipótese diagnóstica?","options":{"A":"Doença falciforme.","B":"Esferocitose hereditária.","C":"Anemia hemolítica autoimune.","D":"Anemia por deficiência de glicose-6-fosfato desidrogenase."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-102150","number":"102150","sourceNumber":"102150","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem de 28 anos comparece para avaliar anemia. Ele tem queixas de episódios de\ndor abdominal e astenia, há dois anos. Conta também que em alguns momentos acha que sua\nurina está mais escura. O exame físico é inexpressivo, exceto por palidez (++/4+). Avaliação\nlaboratorial mostra hemoglobina 9,2 g/dl, com normocitose e normocromia, leucócitos 3.500/mm³,\nplaquetas 105.000/mm³, haptoglobina indetectável, desidrogenase lática 1.620 U/L, bilirrubina\nindireta 1,8 mg/dl e índice de saturação da transferrina 6%. Qual o diagnóstico mais provável?","options":{"A":"Favismo.","B":"Esferocitose.","C":"Anemia hemolítica autoimune.","D":"Hemoglobinúria paroxística noturna."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-102114","number":"102114","sourceNumber":"102114","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança de cinco anos de idade dá entrada na enfermaria de pediatria por\napresentar urina escura, oligúria, edema\nperiorbital e cefaleia. No final da segunda semana de\ninternamento, ainda apresenta: hipertensão arterial de leve intensidade, hematúria glomerular,\nproteinúria, C3 diminuído, ureia e creatinina normais. Qual a hipótese diagnóstica mais provável?","options":{"A":"Nefropatia por IgA.","B":"Glomerulonefrite pós-infecciosa.","C":"Glomerulonefrite membranoproliferativa.","D":"Glomerulopatia da púrpura de Henoch-Schönlein."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-81304","number":"81304","sourceNumber":"81304","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um homem de 32 anos apresentava cefaleia e disartria há 3 semanas. Há 12 dias fez\numa tomografia computadorizada com contraste endovenoso, que revelou um tumor cerebral\nvolumoso. Há 24h foi admitido no hospital por estado epiléptico, tipo grande mal, controlado com\nfenitoína. Evolui com dores difusas pelo corpo e oligúria nas últimas 12 horas. Seus exames\nmostram hemoglobina 10 g/dl, Aspartatoaminotransferase (AST), Desidrogenase Láctica (LDH) e\nácido úrico elevados. Seu sumário de urina mostra hemoglobina +++ com 3 hemácias por campo.\nHaptoglobina 300 mg/dl (ref. 36 a 195 mg/dl), ureia 95 mg/dl e creatinina 10,2 mg/dl. Qual a causa\nmais provável da insuficiência renal desse paciente?","options":{"A":"Lise tumoral.","B":"Rabdomiólise.","C":"Hemólise intravascular.","D":"Toxicidade pelo contraste radiológico."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-65762","number":"65762","sourceNumber":"65762","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 65 anos, feminina, branca, apresenta parestesias em membros inferiores,\ncom dificuldade para caminhar, associadas a quadro\ndemencial de início recente. Nega outras\nqueixas. Os reflexos patelar e aquileu estão reduzidos bilateralmente. Qual dos achados de\nexames laboratoriais seria suficiente para confirmar o diagnóstico mais provável para o quadro\ndessa paciente?","options":{"A":"Folato baixo.","B":"Tiamina baixa.","C":"Homocisteína elevada.","D":"Ácido metilmalônico elevado.","E":"Hormônio tireoestimulante baixo."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-65774","number":"65774","sourceNumber":"65774","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente foi submetido ao tratamento quimioterápico para linfoma de Burkitt. Após a\nprimeira sessão de quimioterapia e suporte terapêutico adequado, apresentou diminuição da\ndiurese para 200 ml/24h e aumento de 20% do seu peso usual. Queixava-se de adinamia. Ao\nexame físico: peso: 40 kg, pressão arterial: 120/80 mmHg, presença de adenopatia cervical.\n\nLaboratorialmente evidenciava hipocalcemia (cálcio total de 7,8 mg/dl); hiperfosfatemia (PO4--: 8,0\nmg/dl); hiperuricemia (ácido úrico: 15,6 mg/dl); aumento da creatinina sérica para 3,6 mg/dl (antes\ndo tratamento era 0,6 mg/dl), hipercalemia (5,8 mg/dl) e bicarbonato de 17 mEq/L. Sedimentoscopia\nurinária: numerosos cristais de ácido úrico. O eletrocardiograma está reproduzido na figura abaixo.\nO estudo ecográfico abdominal e renal foi normal. A conduta inicial mais adequada ao caso seria\nprescrever: (VER IMAGEM)","options":{"A":"alopurinol.","B":"hemodiálise.","C":"gluconato de cálcio.","D":"insulina IV e glicose.","E":"bicarbonato de sódio."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":["question_bank/media/medcurso/med-clinica-medica-med-clm-17/65774.png"],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-65716","number":"65716","sourceNumber":"65716","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança de 13 anos de idade vem apresentando há duas semanas, após infecção\nde vias aéreas superiores e de forma\nprogressiva, edema periorbitário, de abdome e de membros\ninferiores. Os exames revelam proteinúria maciça, hipoalbuminemia, colesterol elevado. Nos\núltimos dias, a pressão arterial encontra-se elevada e surge hematúria macroscópica. Qual\nsíndrome deve ser considerada como principal suspeita diagnóstica?","options":{"A":"Nefropatia por IgA.","B":"Nefrite intersticial aguda.","C":"Síndrome de Goodpasture.","D":"Glomerulonefrite pós-infecciosa.","E":"Síndrome nefrótica de apresentação atípica."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-51171","number":"51171","sourceNumber":"51171","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 68 anos, diabética, procurou a emergência com dor lombar, mialgia\ngeneralizada, febre e calafrios. Encontrava-se\ntaquicárdica, hipotensa e com volume urinário de 250\nml/dia. Exames laboratoriais apresentavam uma proteína C-reativa elevada; hemograma com\nleucocitose; ureia e creatinina elevadas. Uma urografia excretora evidenciou imagem tipo ?ring\nshadow?. Qual o diagnóstico mais provável?","options":{"A":"Abscesso renal.","B":"Pielonefrite aguda.","C":"Tuberculose renal.","D":"Necrose de papila renal."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-45373","number":"45373","sourceNumber":"45373","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na glomerulonefrite aguda pós-estreptocócica, é correto afirmar:","options":{"A":"Está associada geralmente à infecções por\nenterobactérias, principalmente a E. coli O157:H7.","B":"A agressão renal é decorrente da ação direta da bactéria no glomérulo renal.","C":"Todos os casos devem ser hospitalizados.","D":"A hipertensão arterial leve pode ser inicialmente\ncontrolada com repouso e dieta.","E":"As recidivas ocorrem com frequência."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-32525","number":"32525","sourceNumber":"32525","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem de 46 anos portador de câncer de estômago há dois meses. Evolui há 15 dias\ncom quadro de anasarca. Exames complementares revelam: creatinina sérica = 1,0 mg/dl,\nalbumina sérica = 2,3 g/dl, C3 e C4 em níveis normais, sumário de urina com proteínas 4+, sem\nhemácias e proteinúria de 24h = 12 g. Qual o melhor diagnóstico?","options":{"A":"Amiloidose AA.","B":"Nefropatia membranosa.","C":"Nefrite tubulointersticial.","D":"Glomeruloesclerose segmentar e focal.","E":"Glomerulonefrite membranoproliferativa tipo II."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-37417","number":"37417","sourceNumber":"37417","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre a síndrome nefrítica, analise as afirmativas abaixo e, em seguida, assinale a\nalternativa correta: I. A redução da filtração glomerular é resultado do processo inflamatório\nrenal,\ncom lesão por deposição de imunocomplexos circulantes e ativação da cascata do complemento. II.\nOs níveis séricos de ureia e creatinina necessariamente correlacionam-se com a gravidade e\nintensidade da doença. III. A biópsia renal sempre deve ser realizada na suspeita de síndrome\nnefrítica de qualquer etiologia IV. O tratamento consiste em repouso na fase aguda, correção do\nvolume extracelular, tratamento da hipertensão arterial e controle das complicações.","options":{"A":"As alternativas I e III estão corretas.","B":"As alternativas II e IV estão corretas.","C":"As alternativas I e IV estão corretas.","D":"As alternativas II, III e IV estão corretas.","E":"As alternativas I, II e III estão corretas."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-37423","number":"37423","sourceNumber":"37423","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Correlacione as alterações estruturais das glomerulonefrites com o quadro clínico e, em\nseguida, assinale a alternativa correta: I. Proteinúria nefrótica (> 3,5 g/24h), hipoalbuminemia,\nedema, dislipidemia. II. Insuficiência renal aguda, oligúria hipertensão, edema, hematúria e\nproteinúria. III. Proteinúria, hematúria com declínio da taxa de filtração glomerular, hipertensão\ncom\nproliferação das células e da matriz mesangial. IV. Proteinúria não nefrótica, insuficiência renal\ncrônica e fibrose intersticial glomerular. ( ) GN proliferativa difusa (nefrite lúpica); ( )\nEsclerose\nglobal (nefropatia diabética); ( ) GN membranosa (idiopática); ( ) GN mesangioproliferativa\n(nefropatia por IGA).","options":{"A":"II; IV; III; I.","B":"III; I; II; IV.","C":"I; II; III; IV.","D":"II; IV; I; III.","E":"II; III; I; IV."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-30861","number":"30861","sourceNumber":"30861","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menina, 1 ano e 6 meses, apresenta poliúria e deficit ponderoestatural. Os exames\nlaboratoriais revelam alcalose metabólica\nhipoclorêmica e hipocalêmica e níveis elevados de renina\ne aldosterona. Esse quadro corresponde, provavelmente, a:","options":{"A":"Síndrome de Bartter.","B":"Síndrome de Fanconi.","C":"Acidose tubular renal.","D":"Diabetes insipidus nefrogênico.","E":"Galactosemia."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-37435","number":"37435","sourceNumber":"37435","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O raquitismo é uma doença óssea. Possui múltiplas etiopatogenias, dentre as quais\npodemos citar as doenças gastrointestinais que cursam com má absorção, EXCETO:","options":{"A":"Doença celíaca.","B":"Fibrose cística do pâncreas.","C":"Síndrome de Fanconi.","D":"Espru.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-22931","number":"22931","sourceNumber":"22931","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual das seguintes glomerulopatias NÃO cursa com redução de complemento sérico?","options":{"A":"Glomerulonefrite da crioglobulinemia","B":"Glomerulonefrite membranoproliferativa","C":"Glomerulonefrite do lúpus","D":"Glomerulonefrite pós-estreptocóccica","E":"Glomerulonefrite da doença de Goodpasture"},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-29452","number":"29452","sourceNumber":"29452","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à glomerulonefrite aguda pós-infecciosa é correto afirmar:","options":{"A":"A doença se manifesta preferencialmente em crianças menores de dois anos;","B":"O edema em geral é generalizado;","C":"A hipertensão é o segundo sinal mais comum da doença;","D":"É uma causa importante de insuficiência renal em pediatria."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-9014","number":"9014","sourceNumber":"9014","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação às nefropatias associadas às doenças sistêmicas, é CORRETO afirmar\nque:","options":{"A":"A amiloidose cursa com síndrome nefrótica e os rins são aumentados de volume.","B":"O lúpus eritematoso sistêmico apresenta apenas manifestações nefríticas. A presença de\nsíndrome nefrótica é incomum.","C":"A hepatite C, ao contrário da hepatite B, não causa lesão renal.","D":"O carcinoma broncogênico está associado ao aparecimento de glomerulopatia\nmembranoproliferativa."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-9015","number":"9015","sourceNumber":"9015","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem de 52 anos, desempregado, etilista pesado queixando-se de lombalgia, febre\nvespertina, anorexia e perda de peso. Ao exame, encontra-se apenas emagrecido. US abdominal\nrevelou calcificações esparsas no parênquima renal direito e o sumário de urina evidencia\nhematúria microscópica, piúria microscópica e ausência de bactérias. Qual a PRINCIPAL hipótese\ndiagnóstica para o caso?","options":{"A":"Amiloidose renal","B":"Infecção urinária por anaeróbios","C":"Tuberculose renal","D":"Carcinoma de células renais"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-9064","number":"9064","sourceNumber":"9064","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Josias, 10 anos, chegou à emergência do IJF com quadro de edema, hipertensão\narterial e hematúria. O pediatra de plantão\ndesconfiou de uma glomerulonefrite difusa aguda\npós-estreptocócica. Além do sumário de urina, que outro exame seria bastante elucidativo para\nesse diagnóstico?","options":{"A":"Eletrocardiograma","B":"Complemento sérico (C3)","C":"Eletroforese de hemoglobina","D":"Creatinina"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-6947","number":"6947","sourceNumber":"6947","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quanto à leucemia mieloide crônica (LMC) com cromossomo Philadelphia positivo,\nassinale a alternativa CORRETA:","options":{"A":"Trata-se de doença maligna, de natureza genética, na qual se observa a translocação t(9, 21),\nsendo assim, potencialmente transmissível para a prole dos pacientes afetados.","B":"A inibição farmacológica do gene de fusão bcr-abl pode induzir uma remissão clínica,\nhematológica, citogenética e molecular.","C":"O transplante de medula óssea está contraindicado, pois esta patologia acomete, em geral,\npacientes com idade superior a 55 anos.","D":"O quadro hematológico característico da fase crônica inclui leucocitose acentuada com desvio\nescalonado à esquerda e excesso de blastos, trombocitopenia e anemia.","E":"O cromossomo Philadelphia está presente em cerca de 95% dos pacientes acometidos e essa\nalteração citogenética é suficiente para o diagnóstico exclusivo LMC."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-8900","number":"8900","sourceNumber":"8900","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma menina de 4 anos de idade apresenta-se com edema periorbitário no início da\nmanhã. Sua albumina sérica é de 1,5 g/dl. O diagnóstico mais provável é:","options":{"A":"Síndrome nefrótica","B":"Acidose tubular renal","C":"Síndrome de Bartter","D":"Glomerulonefrite aguda","E":"Nefropatia por IgA (nefropatia de Berger)"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-13480","number":"13480","sourceNumber":"13480","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente, 2 anos há 4 dias tem apresentado oligúria, palidez cutâneo- mucosa,\npetéquias e equimoses. Há 1 semana teve\nquadro diarréico e fezes com muco e sangue. Exames\nlaboratoriais: Ureia 65 Creatinina 1,5 Sumário de urina: hematúria ++ e proteinúria +. Para\ncomplementar o diagnóstico mais provável a esse caso, você deveria solicitar:","options":{"A":"Creatinina urinária/plasmática e Fração de Excreção de Sódio.","B":"Sódio Urinário e Osmolaridade urinária/plasmática.","C":"Hemograma, plaquetas, reticulócitos e esfregaço sanguíneo.","D":"Ultrassonografia de rins e vias urinárias.","E":"Proteínas Totais e Frações, CH50 e C3."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-17815","number":"17815","sourceNumber":"17815","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 19 anos, procura emergência por dor em cotovelo e febre. Refere inchaço,\ndor e vermelhidão no cotovelo direito há\ncerca de 24h, acompanhado de febre de até 40ºC com\ncalafrios. Exame físico evidencia artrite em cotovelo direito com demais articulações normais. Não\nhá outros achados no exame físico. Exames laboratoriais evidenciam somente leucocitose de\n\n19.500 células com desvio à esquerda (9% de bastões). Qual a melhor conduta a ser adotada?","options":{"A":"Solicitar FAN e iniciar analgésico","B":"Realizar artrocentese de cotovelo e iniciar antibiótico empírico","C":"Realizar artrocentese de cotovelo e aguardar culturas","D":"Iniciar antibiótico empírico","E":"Iniciar anti-inflamatório não-esteroide e solicitar hemoculturas"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-349756","number":"349756","sourceNumber":"349756","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à Doença Falciforme, assinale a alternativa INCORRETA.","options":{"A":"Não é indicado aconselhamento genético futuro, para evitar preocupações para a família.","B":"As crises álgicas se iniciam antes de 12 meses em muitos casos.","C":"A hidratação venosa está indicada no início do tratamento em caso de crises álgicas.","D":"O alívio da dor não é alcançado com paracetamol nos casos com recidivas.","E":"As complicações da perfusão são pouco importantes durante as crises álgicas."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-365640","number":"365640","sourceNumber":"365640","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança de 1 ano de idade foi levada para consulta de rotina. Na história clínica, a\nmãe referiu desmame completo aos 3 meses de vida, passando a ofertar leite de vaca integral.\n\nNegou uso de ferro oral até o momento. Foram solicitados exames complementares para avaliar\npossível deficiência de ferro. Qual é a alteração laboratorial inicial nos casos de deficiência de\nferro?","options":{"A":"Redução do ferro sérico","B":"Redução da ferritina","C":"Microcitose","D":"Anisocitose"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-322216","number":"322216","sourceNumber":"322216","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"José, 55 anos, retorna à UBS para mostrar exames solicitados pelo seu médico da\nfamília após queixar-se de cansaço há alguns\nmeses. Dentre os resultados, tem-se: ferro sérico 45\nmcg/dl (VR 60-150 mcg/dl), ferritina 170 ng/ml (VR 10-150 ng/ml) TBIC 200 mcg/dl (VR 250-360\nmcg/dl) e saturação de transferrina 28% (VR 30-40%). Dessa forma, o diagnóstico mais provável é","options":{"A":"talassemia.","B":"hemocromatose.","C":"anemia ferropriva.","D":"anemia de doença crônica.","E":"anemia megaloblástica."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-284277","number":"284277","sourceNumber":"284277","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma paciente de 32 anos de idade procurou a unidade básica de saúde com queixa de\nastenia há dois meses. É tabagista de um maço por dia há dez anos. Refere ciclos menstruais\nregulares, com sangramento volumoso por doze dias a cada ciclo. Exame físico: pressão arterial de\n120 x 80 mmHg; frequência cardíaca de 110; e saturação de oxigênio de 97%. Hipocorada ++/4+,\nanictérica, acianótica e eupneica. Exame cardiopulmonar: ritmo cardíaco regular, com sopro\nsistólico ++/6+, pancardíaco, sem irradiação. Murmúrios vesiculares audíveis bilateralmente, sem\nruídos adventícios. Restante do exame físico normal. Com base nessa situaçaõ hipotética, julgue o\nitem a seguir. A contagem de reticulócitos deve estar aumentada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-284278","number":"284278","sourceNumber":"284278","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma paciente de 32 anos de idade procurou a unidade básica de saúde com queixa de\nastenia há dois meses. É tabagista de um maço por dia há dez anos. Refere ciclos menstruais\nregulares, com sangramento volumoso por doze dias a cada ciclo. Exame físico: pressão arterial de\n120 x 80 mmHg; frequência cardíaca de 110; e saturação de oxigênio de 97%. Hipocorada ++/4+,\nanictérica, acianótica e eupneica. Exame cardiopulmonar: ritmo cardíaco regular, com sopro\nsistólico ++/6+, pancardíaco, sem irradiação. Murmúrios vesiculares audíveis bilateralmente, sem\nruídos adventícios. Restante do exame físico normal. Com base nessa situaçaõ hipotética, julgue o\nitem a seguir. O sopro cardíaco identificado trata-se, provavelmente, de sopro funcional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-284279","number":"284279","sourceNumber":"284279","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma paciente de 32 anos de idade procurou a unidade básica de saúde com queixa de\nastenia há dois meses. É tabagista de um maço por dia há dez anos. Refere ciclos menstruais\nregulares, com sangramento volumoso por doze dias a cada ciclo. Exame físico: pressão arterial de\n120 x 80 mmHg; frequência cardíaca de 110; e saturação de oxigênio de 97%. Hipocorada ++/4+,\nanictérica, acianótica e eupneica. Exame cardiopulmonar: ritmo cardíaco regular, com sopro\nsistólico ++/6+, pancardíaco, sem irradiação. Murmúrios vesiculares audíveis bilateralmente, sem\nruídos adventícios. Restante do exame físico normal. Com base nessa situaçaõ hipotética, julgue o\nitem a seguir. Espera-se encontrar corpúsculos de Howell-Jolly no esfregaço de sangue periférico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-284297","number":"284297","sourceNumber":"284297","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um lactente com dez meses de vida, nascido de parto normal a termo, com peso\nadequado e sem intercorrência, foi levado\npor sua mãe à unidade de atenção básica para uma\nconsulta de puericultura, apresentando unhas quebradiças, irritabilidade, queilite angular e\nastenia.\nAo exame físico, o pediatra observou palidez da face, das palmas das mãos e da mucosa oral e\nconjuntival e solicitou um hemograma, que demonstrou hemoglobina igual a 10,5 g/dl e hematócrito\n31%, o que o fez suspeitar de anemia ferropriva. A mãe informou que ele é amamentado ao seio\nmaterno, mas recebe complementação com leite de vaca em pó desde o 6.º mês, aceita pouca\nalimentação de sal e nunca fez suplementação com ferro oral. Com base nessa situação hipotética,\njulgue o item a seguir. A dosagem de ferritina é uma ferramenta diagnóstica que pode ser utilizada\ndesde o primeiro estágio da anemia, ainda na depleção de ferro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-255733","number":"255733","sourceNumber":"255733","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Certo paciente de 10 anos de idade apresenta-se com febre e artrite. Além disso,\napresenta episódio prévio comprovado de infecção\nestreptocócica. Seu eletrocardiograma\ndemonstrava um intervalo PR maior que 0,2 ms e o ecocardiograma estava normal. Apresenta\nhemograma de 9.5 g/dL, ferritina sérica de 12 microgramas/L e RDW era aumentado. No que se\nrefere a esse caso clínico e aos conhecimentos médicos correlatos, julgue o item a seguir. Podem\nocorrer glomerulopatias nesse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-177596","number":"177596","sourceNumber":"177596","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"J.S.A., de 55 anos de idade, negra, viúva, com três filhos, hígida, com alimentação\nsaudável, assídua praticante de exercício\nfísico, vai à consulta para a realização de exames de\nrotina. Refere menopausa há 15 anos. Ao exame físico completo, não se encontra nenhuma\nalteração, exceto palidez de mucosas. Apresenta hemograma realizado em pronto atendimento por\nqueixas gripais, há 2 semanas, com anemia microcítica e índice de anisocitose aumentado. Com\nrelação à avaliação desse quadro, julgue o item a seguir. A gastrite atrófica como causa de anemia\nperniciosa é um diagnóstico provável para esse caso.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-32189","number":"32189","sourceNumber":"32189","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"D. Leda levou seu filho Pedro, de quatro anos de idade, ao pediatra, pois notou que ele\nestava com o rosto e os pés inchados e a urina escurecida. Ao exame físico, o médico observou\nedema bipalpebral bilateral, edema de pés e pernas, FC = 140 bpm, FR = 20 rpm e PA = 120 x 80\nmmHg. Além disso, apresentava lesões crostosas nos membros inferiores e fígado palpável a três\ndedos do rebordo costal direito. A respeito desse caso clínico, assinale a alternativa correta.","options":{"A":"O paciente apresenta uma forma de complicação da doença em questão com indicação de\ninternação imediata.","B":"A dosagem de Antiestreptolisina (ASLO) deverá ser elevada, uma vez que há indícios de\nestreptococcia cutânea concomitante.","C":"Deve-se solicitar a dosagem de proteína total e frações, mesmo que não haja proteinúria.","D":"A dieta de início que deve ser preconizada é a hipossódica.","E":"Não há indicação de prescrição de penicilina benzatina, uma vez que as lesões de pele estão\nem fase de cicatrização."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-366161","number":"366161","sourceNumber":"366161","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. Infere-se do texto que o quadro possa ser decorrente de uma doença\nautossômica dominante.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-366232","number":"366232","sourceNumber":"366232","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. Conclui-se do quadro exposto que o paciente em questão tem 3 de 4\ncritérios os quais são utilizados para diagnóstico clínico da condição apresentada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-366228","number":"366228","sourceNumber":"366228","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma mulher de 54 anos de idade relata fadiga, díspneia em esforços intensos,\nlipotimia, palpitações e perda de peso não\nquantificada nos últimos seis meses. Não menciona\nrestrições alimentares, porém, refere síncope há um mês. Informa que foi hospitalizada\nrecentemente, recebendo transfusão sanguínea devido a uma \"\"Importante alteração no sangue\"\".\nAntecedentes médicos incluem hipertensão arterial sistêmica, obesidade, hipotireoidismo,\nesteatose hepática e dislipidemia, negando tabagismo e etilismo. Na história familiar, destaca-se a\npresença de artrite reumatoide na mãe, que está em tratamento com anti-hipertensivos e\nhipolipemiantes. No exame físico, observa-se palidez cutaneomucosa, sem outras alterações\nevidentes. Os exames laboratoriais revelam hemoglobina de 9,8 g/dL, hematócrito de 37,4%, VCM\nde 114 fL, HCM de 41 e leucograma com quantitativo sem alterações notáveis, exceto por uma\nanomalia visualizada no esfregaço de sangue periférico, conforme imagem apresentada acima.\n\nConsiderando o quadro clínico, exames laboratoriais e achado de série branca e assunto correlatos\nque o caso clínico suscita, julgue o item que\nsubsecutivo. A principal hipótese diagnóstica etiológica\ne deficiência de vitamina B12.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-366227","number":"366227","sourceNumber":"366227","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma mulher de 54 anos de idade relata fadiga, díspneia em esforços intensos,\nlipotimia, palpitações e perda de peso não\nquantificada nos últimos seis meses. Não menciona\nrestrições alimentares, porém, refere síncope há um mês. Informa que foi hospitalizada\nrecentemente, recebendo transfusão sanguínea devido a uma \"\"Importante alteração no sangue\"\".\nAntecedentes médicos incluem hipertensão arterial sistêmica, obesidade, hipotireoidismo,\nesteatose hepática e dislipidemia, negando tabagismo e etilismo. Na história familiar, destaca-se a\npresença de artrite reumatoide na mãe, que está em tratamento com anti-hipertensivos e\nhipolipemiantes. No exame físico, observa-se palidez cutaneomucosa, sem outras alterações\nevidentes. Os exames laboratoriais revelam hemoglobina de 9,8 g/dL, hematócrito de 37,4%, VCM\nde 114 fL, HCM de 41 e leucograma com quantitativo sem alterações notáveis, exceto por uma\nanomalia visualizada no esfregaço de sangue periférico, conforme imagem apresentada acima.\n\nConsiderando o quadro clínico, exames laboratoriais e achado de série branca e assunto correlatos\nque o caso clínico suscita, julgue o item\nque subsecutivo. É frequente a coexistência de\nHipotireoidismo de Hashimoto com a deficiência de vitamina B12 como etiologia do quadro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-343410","number":"343410","sourceNumber":"343410","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A conduta para anemia em crianças menores de 12 meses, usando fórmulas com leite\nde vaca não enriquecidas com ferro é:","options":{"A":"Indicação de 1 a 2 mg/kg/dia de ferro dos 4 aos 18 meses. Se não tiver sido suplementada,\nsolicite hemograma entre 9 e 12 meses.","B":"Indicação de 2 a 4 mg/kg/dia de ferro dos 2 aos 6 meses, quando deve ser solicitado\nhemograma.","C":"Indicação de 2 mg/kg/dia após 1 mês de vida por 2 meses. Depois, reduza a dose para 1 a 2\nmg/kg/dia até os 18 meses. Solicite hemograma aos 15 meses.","D":"Nenhuma das alternativas anteriores."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-268893","number":"268893","sourceNumber":"268893","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma paciente de 23 anos de idade, sem comorbidades conhecidas, compareceu ao\npronto atendimento com queixa de astenia e de redução da capacidade de exercício e negou\nsangramentos. Ao exame físico, estava hipocorada 3+/4 e não havia outras alterações.\n\nVerificam-se FC = 100 bpm, FR = 22 irpm e SatO? = 97%. Os exames iniciais mostram\nhemoglobina = 7,8 g/dL, hematócrito = 22%,\nVCM = 98 fl, HCM = 32 pg e bilirrubinas totais = 2,0\nmg/dL, sendo 1,3 indireta e 0,7 direta. Para confirmar a hipótese diagnóstica de anemia hemolítica,\nespera-se encontrar","options":{"A":"teste de Coombs direto positivo, aumento de reticulócitos e aumento da haptoglobina.","B":"elevação da desidrogenase láctica, aumento de reticulócitos e queda da haptoglobina.","C":"queda da desidrogenase láctica, aumento de reticulócitos e queda da haptoglobina.","D":"elevação da desidrogenase láctica, queda de reticulócitos e teste de Coombs direto positivo.","E":"teste de Coombs direto positivo, que, isoladamente, já é suficiente para confirmar hemólise."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-266432","number":"266432","sourceNumber":"266432","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada à pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de Doença do Refluxo Gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Nos casos de pacientes com\nDRGE de longa data, o uso contínuo de Inibidor de Bomba de Prótons (IBP) pode comprometer a\nabsorção da vitamina B12.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-274621","number":"274621","sourceNumber":"274621","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quanto à ocorrência dos três mecanismos fisiopatológicos essenciais na anemia, é\nCORRETO afirmar:","options":{"A":"Destruição de micróglia, diminuição da contagem de hemácias devido à hemorragia, falência na\nprodução de hemoglobina.","B":"Destruição de eritrócitos, diminuição da contagem de eritrócitos devido à hemorragia, falência na\nprodução de eritrócitos.","C":"Destruição de eritrócitos, diminuição da contagem de células devido à hemorragia, aumento na\nprodução de eritrócitos.","D":"Aumento de eritrócitos, diminuição da contagem de eritrócitos devido à hemorragia, falência na\nprodução de hemoglobina."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-273346","number":"273346","sourceNumber":"273346","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dentre as combinações de exames laboratoriais abaixo, a que tem a maior\nprobabilidade de representar uma doença megaloblástica secundária à depleção de folato é:","options":{"A":"reticulocitose e elevação da homocisteína.","B":"anemia macrocítica e elevação do ácido metilmalônico.","C":"leucopenia e elevação da homocisteína.","D":"plaquetopenia e elevação do ácido metilmalônico."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-291504","number":"291504","sourceNumber":"291504","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um homem de 57 anos de idade comparece ao ambulatório de clínica médica de\nhospital de média complexidade para\navaliação diagnóstica de quadro de fraqueza, cansaço,\nadinamia e desequilíbrio nos membros inferiores (MMII). Segundo informa, seu estado geral era\nbom até 3 meses antes, quando passou a perceber fraqueza e adinamia. Pensou ser decorrente do\nhipotireoidismo, mas após reavaliação hormonal, sua endocrinologista informou-lhe que a tireoidite\nde Hashimoto estava bem controlada, não sendo necessário nenhum reajuste da dose de\nlevotiroxina em uso crônico (125 mcg/dia). Como os sintomas persistiram, procurou facultativo que\nlhe solicitou um hemograma completo, cujo resultado revelou o seguinte padrão: hemoglobina = 7,6\ng/dl (valor de referência = 13 a 16,5 g/dl); hematócrito = 26% (valor de referência = 40 a 52%);\nhemácias = 2,3 × 10?/mcl (valor de refer?ncia = 4,5 a 6,0 × 10?/mcl); volume corpuscular médio =\n113 fl (valor de referência = 80 a 100 fl); leucócitos = 2.800/mcl (valor de referência = 6.000 a\n10.000/mcl), com contagem diferencial normal; plaquetas = 86.000/mcl (valor de referência = 150 a\n400 × 10³/mcl). Ao exame físico procedido na consulta, o paciente encontra-se bastante pálido,\nictérico (+/4+), normotenso, levemente taquicárdico (104 bpm) e hidratado; exame do aparelho\ncardiovascular revela apenas sopro sistólico pancardíaco, enquanto o exame do aparelho\nrespiratório e do abdome é normal. Contudo, ao exame neurológico, é observada perda da\npropriocepção consciente e da sensibilidade vibratória nos MMII, sendo o reflexo cutâneo-plantar\nem extensão bilateral. Uma hematoscopia realizada durante o exame no ambulatório revela a\npresença de plurissegmentação dos neutrófilos. A etiologia mais provável da anemia do paciente\nem apreço é:","options":{"A":"Hipotireoidismo.","B":"Anemia hemolítica autoimune.","C":"Anemia perniciosa.","D":"Deficiência de ácido fólico."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-263393","number":"263393","sourceNumber":"263393","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um Agente Comunitário de Saúde solicita que o médico da equipe avalie uma senhora\nde 78 anos de idade que vem apresentando\nconfusão mental nos últimos meses. Ao realizar a\navaliação, o médico nota que a paciente está em regular estado geral, confusa e descorada. O\nexame físico mostrou reflexo de Babinski presente bilateralmente e incoordenação motora.\n\nConsiderando o caso clínico apresentado, assinale a alternativa que contempla CORRETAMENTE\no exame laboratorial que deve ser solicitado, o\nresultado e o diagnóstico.","options":{"A":"Hemograma; VCM = 120 fl; anemia perniciosa.","B":"Hemograma; VCM = 80 fl; anemia por deficiência de ácido fólico.","C":"FAN; positivo com padrão nuclear pontilhado fino denso; encefalopatia renal.","D":"FAN; positivo com padrão nuclear pontilhado grosso; encefalopatia lúpica."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-291548","number":"291548","sourceNumber":"291548","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um adolescente do sexo masculino, de 13 anos de idade, em atendimento de rotina,\nrelata desânimo e cansaço para ajudar nas\natividades domésticas e inapetência. Recordatório\nalimentar: 3 sanduiches de pão de forma com manteiga e batata frita no almoço e no jantar, nos\nintervalos ingere balas e biscoitos, além de 1 000 mL de leite por dia. Exame físico sem alterações,\npeso, estatura e IMC no percentil 50 das curvas de referência e G3P3 de acordo com estadiamento\nde Tanner. Hemograma: hemoglobina = 12,1 g/dL; hematócrito = 35%; VCM ? 75fl; CHCM ?\n\n26,5g/dl. Considerando que a Organização Mundial de Saúde refere, de maneira geral para\nadolescentes, valores normais de hemoglobina ? 12g%, é correto afirmar que","options":{"A":"o paciente apresenta anemia megaloblástica, sendo necessária a correção dietética com\nalimentos fontes de vitamina B12 e folatos.","B":"o paciente não apresenta alterações clínicas ou laboratoriais, sendo necessário investigar outras\ncausas que justifiquem as queixas do mesmo.","C":"o paciente apresenta anemia carencial por deficiência de ferro, sendo necessária a correção\ndietética e a administração de sulfato ferroso.","D":"o paciente não apresenta anemia, contudo o resultado laboratorial sugere deficiência de ferro,\ndevendo-se realizar a orientação dietética pertinente."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-158056","number":"158056","sourceNumber":"158056","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 22 anos de idade, negra, atendende de telemarketing, apresenta-se ao\npronto-socorro queixando-se de dor muito intensa nos antebraços esquerdo e direito. Nega trauma\ne esforços físicos não usuais. O exame físico é normal, exceto pela dor. As radiografias não\ndemonstram alterações. A paciente refere que apresenta esses sintomas desde criança, várias\nvezes ao ano, com exames sempre normais, frequentemente sendo liberada com prescrição de\nanti-inflamatórios não hormonais, sem grande melhora dos sintomas. Já apresentou esses mesmos\nsintomas em diversas topografias do esqueleto apendicular. No histórico médico progresso, refere\napenas uma anemia em investigação, de etiologia não definida. Relata que dois dos três irmãos\n\napresentam quadro clínico semelhante. Considerando esse caso clínico e o provável diagnóstico da\npaciente, assinale a alternativa CORRETA.","options":{"A":"O uso de penicilina V oral está indicado para essa paciente em razão da maior suscetibilidade a\ninfecções por bactérias encapsuladas.","B":"A presença de leucocitose sem desvio nos exames laboratoriais não é achado compatível.","C":"Aumento expressivo de LDH e da bilirrubina direta são esperados com diminuição da\nhaptoglobina.","D":"A presença de corpúsculos de Howell-Jolly na hematoscopia não é compatível com quadro\nclínico da paciente.","E":"Essa paciente apresenta indicação de profilaxia para as crises, sendo que, quando iniciada a\nmedicação, certos níveis de mielossupressão são toleráveis."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-168481","number":"168481","sourceNumber":"168481","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança com 6 anos de idade, portadora de anemia falciforme, é internada com\nquadro de febre de 38,5°C, associada a\ntosse, dispineia intensa e dor torácica há 3 dias. Ao exame\nfísico, encontra-se hipoativa, hipocorada +++/4, taquipineica, taquicárdica, com sopro sistólico de\n\n++/6, fígado a 2 cm do rebordo costal direito e baço não papável, saturação de O2 = 92% em ar\nambiente. Radiografia de tórax revela opacificações em lobos inferiores. O hemograma revela\nhemoglobina = 6,0 g/dL (valor de referência: 12 a 16 g/dL), sendo a hemoglobina do mês anterior\nigual a 7,2 g/dL. Foram iniciados os procedimentos de oxigenioterapia com máscara com\nreservatório a 10 L/min, hidratação venosa e analgesia, observando-se elevação da saturação de\nO2 para 94%. Nesse caso, a conduta terepêutica adequada é","options":{"A":"transfusão de concentrado de hemácias e início de antibioticoterapia empírica de amplo\nespectro.","B":"transfusão de concentrado de hemácias e instalação de BIPAP.","C":"antibioticoterapia empírica de amplo espectro e surfactante.","D":"exosanguineotransfusão parcial e instalação de BIPAP."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-133958","number":"133958","sourceNumber":"133958","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 5 anos de idade apresenta queixa de edema corporal há três dias,\nhematúria, e cefaleia holocraniana. Nega\nvômitos e febre no período. De antecedentes patológicos\nreferia amigdalite tratada por conta própria com anti-inflamatórios há 20 dias. Ao exame,\n\nobservou-se edema periorbital e de membros inferiores, associado a pressão arterial de 130 x 85\nmmHg. Foi realizado exame sumário de urina que evidenciou hematúria de 4+ com proteinúria de\n1+. Não apresentou alterações no hemograma completo e proteínas totais e frações normais.\n\nConsiderando essa situação hipotética, é CORRETO afirmar que o quadro clínico:","options":{"A":"Sugere Glomeruloesclerose Segmentar e Focal (GESF), e seu tratamento deve ser realizado\ncom o uso de corticoterapia e agentes\ncitotóxicos.","B":"Laboratorial sugere síndrome nefrótica por lesão mínima, e seu tratamento deve ser realizado\ncom corticoterapia.","C":"Laboratorial sugere síndrome nefrítica, com possibilidade de glomerulonefrite aguda\n\npós-estreptocócica, e o tratamento deve ser realizado com restrição hídrica e salina, erradicação da\ncepa estreptocócica e uso de diuréticos.","D":"Sugere doença de Berger, e seu tratamento deve ser realizado com uso de sintomáticos e\ncorticoterapia, se necessário.","E":"Sugere infecção de trato urinário, e deverá ser iniciado antibioticoterapia venosa."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-111292","number":"111292","sourceNumber":"111292","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menina de oito anos dá entrada no Pronto-Socorro Infantil com história de diminuição\nda diurese e a mãe referindo que quando acordou\nestava ?inchada? e sentindo falta de ar aos\nesforços. Ao exame, encontra-se levemente edemaciada, taquicárdica, PA: 150 x 100 mmHg.\n\nApresenta lesões cicatriciais de impetigo em membros inferiores e a radiografia de tórax mostra\naumento do índice cárdio-torácico. Qual dos exames abaixo é decisivo para confirmação do\ndiagnóstico?","options":{"A":"Dosagem de anti-estreptolisina O (ASLO).","B":"Ecocardiograma.","C":"Dosagem do fator C3 do complemento.","D":"Dosagem de ureia e creatinina.","E":"Exame de Urina tipo I."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-80682","number":"80682","sourceNumber":"80682","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa que apresenta a condição e (ou) mecanismo que associa (m) à\nisquemia renal, podendo levar a quadro de insuficiência renal aguda.","options":{"A":"Hipervolemia por iatrogenia.","B":"Vasoconstricção sistêmica com vasodilatação renal.","C":"Sepse.","D":"Uso de dipirona injetável.","E":"Litíase biliar"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-80746","number":"80746","sourceNumber":"80746","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um menino de oito anos de idade é atendido no pronto-socorro com edema de\nmembros inferiores e de face, hematúria e dor de\ncabeça. O pediatra observou, no exame físico,\npresença de lesões infectadas em ambas as pernas e níveis pressóricos elevados para a idade.\nCom base nesse caso hipotético, assinale a alternativa que apresenta a conduta que o pediatra\ndeverá adotar.","options":{"A":"Iniciar corticoide oral no pronto-socorro e prescrever amoxacilina oral para casa, com\norientações de manter dieta com pouco sal.","B":"Indicar internação com restrição hidrossalina, repouso relativo no leito, diurético, prescrever\npelicilina benzatina IM e anti-hipertensivo conforme nível pressórico.","C":"Indicar internação e prescrever digitálico, dependendo dos níveis pressóricos.","D":"Prescrever uma dose de penicilina banzatina IM, diurético e fenobarbital, dependendo dos níveis\nde hipertensão, para serem feitos no\npronto-socorro.","E":"Administrar diurético endovenoso e imunoglobulina."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-97842","number":"97842","sourceNumber":"97842","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um lactente, negro, com um ano de idade, foi encaminhado ao Ambulatório de\nPediatria pelo surgimento de quadro recente\nde febre e palidez acompanhadas de dor e inchaço\nnos dedos das mãos e pés. Na ocasião foi colhido hemograma e prescrito analgésico. O lactente,\nnascido com 38 semanas de gestação, foi amamentado exclusivamente até quatro meses de vida,\nquando foi introduzida alimentação complementar. A mãe acha que a criança não aceita bem a\nrefeição salgada e toma quatro mamadeiras por dia. Nega doenças anteriores. Ao exame físico, a\ncriança encontra-se descorada ++/4+, sem outras alterações. A mãe traz hemograma anterior:\nHemoglobina = 8,5 g/dl (Valor de referência = 10,5 - 13,5 g/dl); Hematócrito = 25% (Valor de\nreferência = 33% - 39%); VCM = 85 fl (Valor de referência = 70 - 86 fl); RDW normal; reticulócitos =\n4% CVSs (Valor de referência = 0,5% - 2,5% CVSs); leucócitos = 14,400/mm³ (Valor de referência\n\n= 6,000 - 17,000/mm³); plaquetas = 323,000/mm³ (Valor de referência = 150,000 - 350,00/mm³).\nCom base no quadro clínico e no hemograma\napresentados, qual o diagnóstico correto e qual\nexame laboratorial deve(m) ser solicitado(s) para confirmação do diagnóstico?","options":{"A":"Anemia ferropriva; perfil de ferro sérico.","B":"Talassemia; eletroforese de hemoglobina.","C":"Anemia falciforme; eletroforese de hemoglobina.","D":"Anemia megaloblástica; dosagem de vitamina B12 e ácido fólico sérico."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-97740","number":"97740","sourceNumber":"97740","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma mulher com 34 anos de idade, em atendimento ambulatorial, refere palpitação,\nfraqueza e sensação de desmaio, iniciadas há\ntrês meses e que vêm se agravando. A paciente não\nrefere emagrecimento ou febre e está em uso irregular de anticoncepcional oral e de fluoxetina - 40\nmg/dia. Ao exame encontra-se descorada, hidratada, sem visceromegalias, taquicárdica, com\nbulhas rítmicas e normofonéticas. O resultado do hemograma revela: hemoglobina:7,8 g/dl (Valor\nde referência = 12 - 16 g/dl); hematócrito: 25% (Valor de referência = 36% - 46%); volume\ncorpuscular médio: 70 fl (Valor de referência= 80 - 100 fl); RDW diminuído; leucócitos totais:\n7.470/mm³ (Valor de referência = 4.500 - 11.000/mm³) - [3% bastões, 55% segmentados, 35%\nlinfócitos, 7% monócitos]; plaquetas: 234.000/mm³ (Valor de referência = 150.000 - 350.000/mm³).\nSobre as hipóteses diagnósticas e a investigação laboratorial complementar para essa paciente, é\ncorreto afirmar que se trata de provável anemia:","options":{"A":"ferropriva e espera-se que a dosagem de ferro sérico, a ferritina e o índice de saturação de\ntransferrina estejam baixos.","B":"por perda crônica de sangue, por via menstrual ou gastrointestinal, e espera-se aumento na\ncontagem de reticulócitos.","C":"secundária à neoplasia, sendo necessário o rastreamento nos sítios mais comuns para mulher,\nmama e colo de útero.","D":"devido à deficiência ou erro alimentar na ingestão de ferro, não sendo necessária investigação\nadicional para a paciente."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-75562","number":"75562","sourceNumber":"75562","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher com 50 anos de idade procura Ambulatório de Clínica Médica com queixa de\nfadiga e dispneia aos esforços. Informa ser portadora de refluxo gastroesofágico, em uso frequente\nde cimetidina para alívio sintomático. Tem endoscopia digestiva normal. Não tem outras queixas.\n\nAo exame físico apresenta palidez cutâneo-mucosa e não\n\nhá outros achados relevantes. Hemograma mostra: Ht = 22%; Hb = 7,1 g/dl; VCM = 102 fl; CHCM =\n33%; Leucócitos = 2.500/mm³ (neutrófilos = 1.200, linfócitos = 800, monócitos = 500); Plaquetas =\n95.000/mm³; Reticulócitos ausentes.\n\nCom base nesses achados, qual o diagnóstico mais provável?","options":{"A":"Anemia perniciosa.","B":"Anemia aplásica.","C":"Anemia hemolítica.","D":"Anemia de doença crônica.","E":"Anemia por deficiência de folato."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-137549","number":"137549","sourceNumber":"137549","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança com 6 anos de idade, moradora em zona rural, é trazida por sua mãe à\nUnidade Básica de Saúde (UBS) por apresentar palidez, falta de apetite, perda de peso e\nrendimento escolar insatisfatório observados há dois meses.\n\nAlém da dosagem de hemoglobina e hematimetria, que outros exames, com seus respectivos\nresultados, servirão para o diagnóstico de uma anemia carencial?","options":{"A":"Morfologia das hemácias: normocítica e normocrômica; ferritina baixa; ferro sérico normal;\ncapacidade de ligação do ferro baixa; saturação de transferrina normal.","B":"Morfologia das hemácias: microcítica e hipocrômica;\n\nferritina baixa; ferro sérico baixo; capacidade de ligação do ferro elevada; saturação de\ntransferrina\nbaixa","C":"Morfologia das hemácias: normocítica e normocrômica;\n\nferritina normal; ferro sérico baixo; capacidade de ligação do ferro baixa; saturação de\ntransferrina\nnormal.","D":"Morfologia das hemácias: microcítica e normocrômica;\n\nferritina baixa; ferro sérico baixo; capacidade de ligação do ferro elevada; saturação de\ntransferrina\nbaixa.","E":"Morfologia das hemácias: normocítica e hipocrômica; ferritina normal; ferro sérico normal;\ncapacidade de ligação do ferro baixa; saturação de transferrina normal."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-138398","number":"138398","sourceNumber":"138398","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança com um ano de idade foi amamentada com leite materno exclusivamente até\nos seis meses, quando passou a receber alimentação complementar com frutas, papa salgada\ncomposta de vegetais, cereais e, às vezes, carne. Na ocasião da consulta de puericultura, por\napresentar palidez, o médico solicitou eritrograma que apresentou os seguintes resultados :\nHemoglobina = 10,2 mg/dL (valor normal = 11 - 13 mg/dL); Hematócrito = 30,8 % (valor normal =\n36-44 %); Volume\n\nCorpuscular Médio = 75 fL (valor normal = 77- 101 fL); Hemoglobina Corpuscular Média = 21 pg\n(valor normal = 23-31 pg); Concentração de\nHemoglobina Corpuscular Média = 26 g/dL (valor\nnormal = 28-33 g/dL) e RDW = 15,5 % (valor normal <14 %). A hipótese diagnóstica elaborada pelo\nmédico e o exame complementar que melhor confirrma esse diagnóstico são, respectivamente,","options":{"A":"anemia falciforme e contagem de reticulócitos.","B":"anemia por deficiência de ácido fólico e dosagem\nde folatos.","C":"anemia megaloblástica e eletroforese de hemoglobina.","D":"anemia carencial ferropriva e dosagem da ferritina\nsérica.","E":"talassemia e dosagem de ferro sérico."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-138401","number":"138401","sourceNumber":"138401","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher com 48 anos de idade, parda, comerciante, procura o posto de saúde por\napresentar astenia, palidez e fadiga fácil ao\nrealizar suas tarefas diárias. Na história da doença\natual relata que esteve bem de saúde até há 15 dias, quando iniciaram estes sinais e sintomas.\nNega doenças como diabetes, hipertensão, doenças da tireóide. Nega também o uso de\nmedicamentos. Ao exame físico apresenta palidez, icterícia (2+/4+), esplenomegalia de 4 cm do\nrebordo costal esquerdo e hepatomegalia de 2 cm do rebordo costal direito. Exames laboratoriais\nrealizados mostram hemoglobina = 4,2 g/ dL; hematócrito = 13 %; VCM = 110 fL (VR = 80 ? 100\nfL); HCM = 32 pg (VR = 26 ? 34 pg); leucograma = 10.500 / mm3 com diferencial normal; plaquetas\n\n= 240.000 /mm3; reticulócitos aumentados; bilirrubina total = 4,0 mg/dL (VR=0,3 -1,2 mg/dL) com\nfração direta de 0,8 mg/dl (VR = 0 - 0,2\nmg/dL). Qual o diagnóstico mais provável para a anemia da\npaciente?","options":{"A":"Anemia por déficit de produção ocasionada por\ndeficiência de vitamina B12","B":"Anemia do tipo regenerativa provocada por doença hemolítica adquirida.","C":"Anemia arregenerativa por deficiência quantitativa\nde células progenitoras associada à hepatite viral.","D":"Anemia por deficiência na síntese do heme durante a diferenciação das células eritroides.","E":"Anemia por deficiência na síntese da globina durante a diferenciação das células eritroides."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-31039","number":"31039","sourceNumber":"31039","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando que, durante a investigação clínica de um paciente de 48 anos de idade\ncom acidose metabólica hiperclorêmica com hiato aniônico (ânion gap) plasmático dentro da\nnormalidade, tenha-se obtido o diagnóstico de acidose tubular renal distal tipo 1, julgue o item a\nseguir: Hipercalciúria, nefrocalcinose e nefrolitíase são alterações que devem ser investigadas no\npaciente em tela, pois estão frequentemente associadas a essa nefropatia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-138740","number":"138740","sourceNumber":"138740","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança do sexo masculino, com três anos de idade e que apresenta anemia falciforme,\né levado pela mãe à consulta na Unidade Básica\nde Saúde porque está tendo febre há quatro dias,\nchegando a 39°C. Apresenta tosse produtiva que aumentou de intensidade. Encontra-se em estado\ngeral de prostração e a mãe notou que a criança está mais pálida e ictérica nos últimos dias. O\npediatra encaminhou a criança de imediato para o hospital de referência, considerando que","options":{"A":"as infecções são as complicações mais frequentes\nna anemia falciforme, acompanhadas de\n\nesplenomegalia que se acentua após os cinco anos de idade.","B":"a importância das infecções como complicações na anemia falciforme, deve-se à maior\nsusceptibilidade à bactéria Salmonella na faixa etária abaixo dos cinco anos.","C":"a mortalidade entre crianças falcêmicas menores de cinco anos é elevada, sendo as\ncomplicações mais frequentes as infecções por Haemophilus influenzae tipo b (Hib) e por\npneumococo.","D":"as infecções são as complicações mais frequentes, e o uso de profilaxia com penicilina é\ncontra-indicado pelos riscos de aumento da taxa de colonização por cepas de pneumococos\nresistentes.","E":"as infecções são as complicações mais frequentes, o que leva à necessidade de profilaxia com\npenicilina, recomendada do momento do diagnóstico da anemia falciforme e mantida por toda a\nvida."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-351612","number":"351612","sourceNumber":"351612","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente com 13 anos de idade, com diagnóstico de anemia falciforme comparece à\nconsulta de rotina no ambulatório e questiona seu médico sobre seu risco de apresentar um\nacidente vascular cerebral (AVC), pois seu irmão mais novo, também portador de anemia\nfalciforme, está internado no hospital devido a um AVC. Nesse caso, é CORRETO afirmar que as\nrecomendações para a prevenção de AVC são:","options":{"A":"Realizar ecografia transcraniana com Doppler, apenas se o paciente apresentar sintomas.","B":"Verificar o uso de hidroxiureia e sua eficácia pelos níveis de HbF e rever resultados de sua\núltima ecografia transcraniana, repetindo-a, se necessário.","C":"Iniciar esquema de transfusão crônica, se houver alteração na velocidade de fluxo da artéria\ncerebral acima de 270cm/seg.","D":"Manter níveis de HbS inferiores a 50%."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-368189","number":"368189","sourceNumber":"368189","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dentre as doenças hematológicas a seguir, aquela que tem como indicação primária o\ntratamento pela esplenectomia é a","options":{"A":"eliptocitose hereditária.","B":"talassemia maior.","C":"anemia falciforme.","D":"esferocitose hereditária."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-359218","number":"359218","sourceNumber":"359218","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na anemia ferropriva, a resposta terapêutica à reposição com ferro pode ser avaliada\npelo exame clínico e/ou exames laboratoriais.\nNesse contexto, correlacione a COLUNA II de acordo\ncom a COLUNA I. COLUNA I; I - 24h de tratamento; II - 48h de tratamento; III - 1 semana de\ntratamento; IV - 30 dias de tratamento; V - 4 meses de tratamento; COLUNA II; ( ) Resposta\nmedular inicial, hiperplasia eritróide. ( ) Aumento do nível de hemoglobina. ( ) Reposição de\nreservas de ferro. ( ) Melhora da irritabilidade, recuperação de enzimas férricas. ( )\nReticulocitose.\n\nAssinale a alternativa que apresenta a sequência CORRETA.","options":{"A":"I, II, IV, V, III","B":"III, V, IV, I, II","C":"II, IV, V, I, III","D":"IV, I, III, II, V"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-352204","number":"352204","sourceNumber":"352204","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente masculino, 9 meses, compareceu para puericultura com quadro de palidez\ncutâneomucosa. História pregressa não relevante. Exame físico sem outras alterações. O\nhemograma revelou hemoglobina de 9,1 g/dl, VCM e HCM baixos, RDW elevado. Teste de pezinho\ncom eletroforese de hemoglobina mostrando padrão FAS. Considerando o relato, assinale a\ncorreta:","options":{"A":"Repetir eletroforese de hemoglobina para confirmar traço falciforme e iniciar profilaxia com\nácido\nfólico e ferro.","B":"Repetir eletroforese de hemoglobina para confirmar doença falciforme e iniciar antibioticoterapia\nprofilática.","C":"Realizar dosagem de ferro sérico, ferritina e saturação de tranferrina para confirmar anemia por\ndeficiência de ferro e iniciar tratamento com ferro oral.","D":"Hemoglobina normal para a idade (anemia fisiológica do lactente). Não há necessidade de\nnovos exames e deverá ser iniciado profilaxia com\nferro oral."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-334720","number":"334720","sourceNumber":"334720","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São causas de anemia normocítica.","options":{"A":"Doença renal, doença crônica.","B":"Deficiência de ferro, lesão medular.","C":"Mielodisplasia, talassemia minor.","D":"Anemia sideroblástica, anemia hemolítica."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-335071","number":"335071","sourceNumber":"335071","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre as características e os contextos clínicos que diferenciam a anemia aguda da\nanemia crônica, numere a coluna II de acordo com a coluna I. COLUNA I 1. Anemia aguda 2.\n\nAnemia crônica COLUNA II ( ) Hemorragias secundárias a trauma, sequestro hepático,\nsangramento gastrintestinal ou gênito-urinário. (\n) Etiologia específica de destruição ou diminuição\nda produção das hemácias; pode apresentar reticulocitose. ( ) Processo progressivo que o\norganismo instala para ajustar a reduzida capacidade de transporte de O2 . ( ) Anemia hemolítica\nsecundária à microangiopatia e à coagulação intravascular disseminada. ( ) Doença falciforme com\ncrise aplástica, anemia dilucional após rápida infusão de cristaloides. Assinale a sequência\ncorreta.","options":{"A":"2 1 2 1 2","B":"2 2 1 1 2","C":"1 1 1 2 1","D":"1 2 2 1 1"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-321181","number":"321181","sourceNumber":"321181","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia não é uma entidade específica, mas sim o resultado de diversos processos\npatológicos subjacentes. Sobre as anemias, é CORRETO afirmar que:","options":{"A":"Uma forma de diferenciar anemias por deficiência de ferro de talassemia é através do Red Cell\nDistribution Width (RDW) que na talassemia está aumentado.","B":"A anemia megaloblástica por deficiência de ácido fólico pode ocorrer como resultado da ingesta\ninadequada de folato, da diminuição da absorção de folato, ausência de secreção do fator\nintrínseco ou distúrbios adquiridos do metabolismo do folato.","C":"Na anemia fisiológica da infância não é necessário tratamento, apenas que a dieta do neonato\npossua os nutrientes necessários para a\nhematopoiese, como ferro e ácido fólico.","D":"Na anemia falciforme, os pacientes devem receber ácido fólico, 1mg/dia, para prevenir a\ndeficiência secundária de ácido fólico."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-335104","number":"335104","sourceNumber":"335104","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Estudos demostram que a anemia ferropriva afeta dois bilhões de pessoas, sendo\n51,2% da população pediátrica com idade entre\ndois meses e cinco anos. Os fatores como nível\nsocioeconômico, aspectos demográficos e nível de escolaridade dos pais associam-se à alta\nprevalência. Acerca da anemia ferropriva, a resposta terapêutica da reposição com ferro pode ser\navaliada por meio do exame clínico e / ou exames laboratoriais. A esse respeito, numere a\nCOLUNA II de acordo com a COLUNA I. COLUNA I 1. 24 horas de tratamento; 2. 48 horas de\ntratamento; 3. Uma semana de tratamento; 4. 30 dias de tratamento; 5. Quatro meses de\ntratamento. COLUNA II ( ) Resposta medular inicial, hiperplasia eritroide. ( ) Aumento do nível de\nhemoglobina. ( ) Reposição de reservas de ferro. ( ) Melhora da irritabilidade, recuperação de\nenzimas férricas. ( ) Reticulocitose. Assinale a sequência correta.","options":{"A":"1 2 4 5 3","B":"3 5 4 1 2","C":"2 4 5 1 3","D":"4 1 3 2 5"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-304842","number":"304842","sourceNumber":"304842","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem de 22 anos apresenta quadro de fadiga e baixo rendimento físico há cerca de 6\nmeses. Nega outras doenças no período. Ao exame físico, encontrava-se hipocorado, sem outras\nalterações relevantes. O hemograma evidenciou eritrócitos = 2.210.000/mL; hemoglobina = 8,1\ng/dL; hematócrito = 24,1%; VCM = 82,5 fL; HCM = 31pg; CHCM = 38,2%; RDW = 24,2%. O\n\ndiagnóstico etiológico do caso pode ser confirmado por:","options":{"A":"Eletroforese de hemoglobina.","B":"Dosagem de vitamina B12 e ácido fólico.","C":"Testes de Coombs e de fragilidade eritrocitária.","D":"Dosagem de ferritina e índice de saturação da transferrina."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313277","number":"313277","sourceNumber":"313277","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando o caso da questão anterior, o médico identifica uma possível deficiência\nde vitamina B12 e folatos na análise da série\nvermelha. O achado identificado, para levar a essa\nhipótese diagnóstica é:","options":{"A":"Presença de leptócitos.","B":"Presença de dacriócitos.","C":"Presença de microcitose.","D":"Inclusões de Howell-Jolly.","E":"Presença de macrocitose."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-304995","number":"304995","sourceNumber":"304995","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considere que um homem de 41 anos de idade apresenta hemograma com\nhemoglobina = 10 g/L, VCM = 72 fL,\nleucócitos = 3.500/mm³, plaquetas = 170.000/mm³ e ferritina =\n50 ng/mL. Nesse caso, qual é o provável diagnóstico?","options":{"A":"Anemia ferropriva.","B":"Anemia falciforme.","C":"Talassemia.","D":"Sideroblastose."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-314035","number":"314035","sourceNumber":"314035","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação aos critérios morfológicos para classificação das anemias, assinalar a\nalternativa CORRETA:","options":{"A":"A anemia por deficiência de ferro é do tipo macrocítica normocrômica.","B":"A anemia secundária à doença crônica é do tipo macrocítica normocrômica.","C":"A anemia hemolítica é do tipo microcítica hipocrômica.","D":"A anemia por deficiência de folato ou de vitamina B12 é do tipo macrocítica normocrômica.","E":"A anemia aplásica é do tipo microcítica hipocrômica."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-314076","number":"314076","sourceNumber":"314076","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à anemia por deficiência de ferro, analisar os itens abaixo: I. O controle da\nabsorção do ferro pelas células das criptas duodenais é crucial, uma vez que não há um\nmecanismo fisiológico regulável para a excreção do ferro. II. Nos Países desenvolvidos, as\ninfecções por helmintos, que incluem a ancilostomíase e a esquistossomose, estão entre as causas\nmais comuns de perda sanguínea pela via gastrointestinal. III. A anemia ferropriva manifesta-se por\nmeio de sintomas inespecíficos, como fraqueza, palidez, tontura, diminuição da tolerância aos\nexercícios físicos e irritabilidade. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-283885","number":"283885","sourceNumber":"283885","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual dos sintomas ou sinais abaixo NÃO ocorre na anemia ferropriva grave?","options":{"A":"Hipertrofia gengival.","B":"Queilose.","C":"Coiloníquia.","D":"Disfagia secundária à Síndrome de Plummer-Vinson.","E":"Fadiga."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-266367","number":"266367","sourceNumber":"266367","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Anemia é definida pela redução da concentração de hemoglobina e/ou massa\neritrocitária, com variações de acordo com a\nidade, sexo, raça e a altitude em relação ao nível do\nmar. Podem ser classificadas do ponto de vista fisiológico e morfológico. Na classificação\nmorfológica das anemias é CORRETO afirmar:","options":{"A":"A deficiência de ferro, a anemia responsiva à tiamina e a anemia da doença hepática causam\nanemias microcíticas.","B":"A deficiência de ferro, as síndromes talassêmicas e as deficiências de vitamina B12 causam\nanemias microcíticas.","C":"A deficiência de vitamina B12 e ácido fólico, o hipotireoidismo e a aplasia medular congênita ou\nadquirida causam anemias macrocíticas.","D":"A deficiência de vitamina B12 e ácido fólico, a doença inflamatória crônica e a intoxicação pelo\nchumbo causam anemias macrocíticas."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-287856","number":"287856","sourceNumber":"287856","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre as anemias, assinalar a alternativa CORRETA:","options":{"A":"A principal causa de anemia no mundo é a deficiência de vitamina B12.","B":"A anemia ferropriva e a talassemia são consideradas anemias microcíticas.","C":"Solicitar apenas o hemograma é suficiente para a abordagem completa das anemias.","D":"A anemia em homens na faixa dos cinquenta anos e nas mulheres pós-menopausa é\nconsiderada um achado comum.","E":"A anemia perniciosa é comum em crianças, sendo causada, na maior parte das vezes, por\ndeficiência de ácido fólico."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-287904","number":"287904","sourceNumber":"287904","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação às anemias, assinalar a alternativa CORRETA:","options":{"A":"A Organização Mundial da Saúde estima que apenas 10% de todas as anemias sejam causadas\npor deficiência de ferro.","B":"O ferro não heme, encontrado nos produtos de origem vegetal e em alguns produtos de origem\nanimal, tem menor biodisponibilidade do que o ferro heme.","C":"Não há relação entre o alto consumo de leite de vaca e a inibição da absorção do ferro.","D":"A geofagia é um sintoma muito raro de ser encontrado em crianças com anemia.","E":"Em um quadro de deficiência de ferro, com anemia, é esperado que a saturação da transferrina\nesteja acima de 16%."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-234407","number":"234407","sourceNumber":"234407","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um homem de 35 anos vai ao pronto atendimento queixando-se de dispneia ao\ncaminhar 1 quarteirão, com piora progressiva há 7 dias. Nega febre ou outros sintomas.\n\nDesconhece ser portador de doenças prévias e nega o uso de medicamentos ou drogas quaisquer.\nAo exame físico, apresenta-se alerta,\norientado, com as mucosas descoradas, ictéricas e\nhidratadas. Os dados vitais são: PA = 120 x 76 mmHg; FC = 92 bpm; FR = 17 ipm; SpO? em ar\nambiente 98%. Está eupneico em repouso. Sem alterações no restante do exame físico. Exames\nde laboratório: hemoglobina = 6,9 g/dl; HCM = 32 pg; VCM = 102 fl; CHCM = 35 g/dl; RDW =\n18,4%; leucócitos = 7.560/mm³; neutrófilos segmentados = 5.980/ mm³; plaquetas = 230.000/mm³;\nproteína C-reativa = 12 mg/L; creatinina = 1,5 mg/dl; ureia = 90 mg/dl; Coombs direto positivo;\nlactato desidrogenase = 1.090 U/L; bilirrubina total = 2,5 mg/dl; bilirrubina direta = 0,5 mg/dl;\nbilirrubina indireta = 2,0 mg/dl; reticulócitos = 12,2%. Considerando o caso descrito, assinale a\nconduta terapêutica imediata MAIS ADEQUADA para esse paciente:","options":{"A":"Administrar 1 mg/kg de prednisona pela via oral.","B":"Administrar eritropoietina pela via subcutânea.","C":"Administrar ferro pela via intravenosa.","D":"Transfundir 600 ml de concentrado de hemácias."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-246353","number":"246353","sourceNumber":"246353","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 35 anos, vigilante, previamente hígida, comparece ao ambulatório de clínica\nmédica referindo parestesia em membros inferiores de evolução há cerca de um ano. Há 2 meses\nsua mãe faleceu de câncer gástrico e, desde então, está apresentando dificuldade de concentração\ne déficit de memória recente. Após o falecimento de sua mãe a paciente foi submetida a\nendoscopia digestiva alta, que evidenciou gastrite atrófica confirmada por biópsia, com pesquisa\nnegativa para Helicobacter pylori. Além disso, também traz exames realizados de rotina há 1\nsemana que foram solicitados por sua ginecologista: Hemoglobina: 10,4 g/dL, hematócrito 30%,\nVCM: 110 fL, HCM 28 pg, CHCM 32g/dL, RDW 10%, Leucócitos totais 3,5 x 10³/mm³ (basófilos\n0,5%/ eosinófilos 2,5%/ mielócitos 0%/ metamielócitos 0%/ bastões 1%/ segmentados 55%/\nlinfócitos 35%/ monócitos 6%) com hiperssegmentação de neutrófilos, plaquetas 87.000, TSH 4,0\nmUI/L (VR: 0,45 - 4,5 mUI/L). Diante da hipótese diagnóstica mais provável, qual a melhor\nestratégia de tratamento para esse paciente?","options":{"A":"Reposição de vitamina B12 parenteral.","B":"Corticoide em dose imunossupressora.","C":"Ara-C em dose padrão por cinco a dez dias, associado a idarrubicina.","D":"Transplante alogênico de células-tronco hematopoiéticas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-246354","number":"246354","sourceNumber":"246354","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 35 anos, vigilante, previamente hígida, comparece ao ambulatório de clínica\nmédica referindo parestesia em membros inferiores de evolução há cerca de um ano. Há 2 meses\nsua mãe faleceu de câncer gástrico e, desde então, está apresentando dificuldade de concentração\ne déficit de memória recente. Após o falecimento de sua mãe a paciente foi submetida a\nendoscopia digestiva alta, que evidenciou gastrite atrófica confirmada por biópsia, com pesquisa\nnegativa para Helicobacter pylori. Além disso, também traz exames realizados de rotina há 1\nsemana que foram solicitados por sua ginecologista: Hemoglobina: 10,4 g/dL, hematócrito 30%,\nVCM: 110 fL, HCM 28 pg, CHCM 32g/dL, RDW 10%, Leucócitos totais 3,5 x 10³/mm³ (basófilos\n0,5%/ eosinófilos 2,5%/ mielócitos 0%/ metamielócitos 0%/ bastões 1%/ segmentados 55%/\nlinfócitos 35%/ monócitos 6%) com hiperssegmentação de neutrófilos, plaquetas 87.000, TSH 4,0\nmUI/L (VR: 0,45 - 4,5 mUI/L). Diante do caso, qual a hipótese diagnóstica mais provável?","options":{"A":"Síndrome mielodisplásica.","B":"Leucemia mieloide aguda.","C":"Anemia perniciosa.","D":"Anemia aplásica."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-227251","number":"227251","sourceNumber":"227251","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"No estado carencial de ferro é comum o seguinte achado no hemograma:","options":{"A":"Neutropenia.","B":"Trombocitose.","C":"Aumento do volume corpuscular médio das hemácias (VCM).","D":"Diminuição do RDW (amplitude de distribuição dos eritrócitos)."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-246728","number":"246728","sourceNumber":"246728","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Não corresponde à anemia ferropriva o seguinte achado:","options":{"A":"Volume corpuscular médio baixo.","B":"Ferritina baixa.","C":"Capacidade total de ligação do ferro baixo.","D":"Ferro sérico baixo.","E":"Hemoglobina corpuscular média baixa."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-243029","number":"243029","sourceNumber":"243029","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, 14 anos, sexo feminino, vai ao consultório acompanhada de sua mãe com\nqueixa de fraqueza, cansaço e falta de apetite há um mês. Há dois anos se tornou vegana e por\nisso não come nenhum tipo de carne. Exame físico: emagrecida, hipocorada +/4+, queilite angular,\ndiscreta fotofobia e leve nistagmo ocular. P: 38 kg, E: 158cm, IMC: 15,2. RCR 2T BNF FC: 99 bpm,\nSat O2: 98%. FR: 37 irpm. A hipótese diagnóstica é deficiência de:","options":{"A":"vitamina K.","B":"zinco e cobre.","C":"zinco e selênio.","D":"vitaminas do complexo B.","E":"zinco selênio e cobre."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-255663","number":"255663","sourceNumber":"255663","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quanto ao tratamento da anemia ferropriva, em geral em quanto tempo após o início do\ntratamento a contagem de reticulócitos deve começar a aumentar? MARQUE A CORRETA:","options":{"A":"1 a 2 dias.","B":"4 a 7 dias.","C":"7 a 14 dias.","D":"2 a 4 semanas."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-246799","number":"246799","sourceNumber":"246799","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em crianças com diagnóstico confirmado de deficiência de\nglicose-6-fosfato-desidrogenase, a medida terapêutica mais importante é:","options":{"A":"esplenectomia eletiva","B":"hemotransfusão preventiva","C":"prevenção da hemólise","D":"exsanguíneo transfusão parcial","E":"transfusão mensal de concentrado de hemácias"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-220287","number":"220287","sourceNumber":"220287","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 45 anos comparece ao consultório do seu clínico, queixando-se de dispneia\naos esforços e fadiga ao se exercitar. É\netilista e faz uso de 1 L de cachaça ao dia há 15 anos. Traz\nconsigo os resultados dos seguintes exames: hemoglobina = 9,5 g/dl; hematócrito = 28%; volume\ncorpuscular médio = 74 fl; hemoglobina corpuscular média = 23 pg; leucócitos = 5.780/mm³;\nplaquetas = 198.000/mm³; ferro sérico = 15 mcg/dl (VR 50-170); ferritina = 5 ng/ml (VR 11-306);\níndice de saturação de transferrina = 15% (20-50%) e capacidade total de ligação do ferro 410\nmcg/dl (VR 250-425). Em relação ao caso descrito, assinale a alternativa CORRETA:","options":{"A":"A anemia pode estar associada à doença celíaca, à síndrome de supercrescimento bacteriano e\nà angiodisplasia colônica.","B":"A histerectomia está indicada para a prevenção de perda sanguínea pela menstruação.","C":"O principal mecanismo da anemia é a mielotoxicidade induzida pelo álcool.","D":"A transfusão de concentrado de hemácias está indicada, uma vez que a paciente está\nsintomática."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-199527","number":"199527","sourceNumber":"199527","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre o diagnóstico diferencial das anemias, assinale a alternativa CORRETA:","options":{"A":"A talassemia menor cursa, mais comumente, com\nanemia hemolítica normocítica e normocrômica.","B":"A anemia microcítica e hipocrômica, com ferro\nsérico e transferrina reduzidos, índice de\nsaturação de transferrina normal e ferritina\naumentada, é compatível com causa ferropriva.","C":"As anemias macrocíticas podem ser encontradas\nna mielodisplasia, na doença de Crohn ileal, no\nhipotireoidismo e em pacientes etilistas.","D":"As anemias hemolíticas por anormalidades intrínsecas dos eritrócitos possuem em comum o\naumento da bilirrubina indireta e da desidrogenase láctica, a redução da haptoglobina\n\ne o teste de Coombs direto positivo."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-202745","number":"202745","sourceNumber":"202745","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Os diagnósticos diferenciais de anemias hipocrômicas/ microcíticas incluem:","options":{"A":"Anemia ferropriva, traço falcêmico e esferocitose hereditária.","B":"Anemia de doença crônica, deficiência de b12 e ferro.","C":"Deficiência de ferro, talassemias e anemia sideroblástica.","D":"Anemia ferropriva, deficiência de b12, traço falsemico.","E":"Deficiência de ferro e ácido fólico, anemia falciforme."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-199625","number":"199625","sourceNumber":"199625","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A doença falciforme é o termo utilizado para definir um grupo de alterações genéticas\ncaracterizadas pelo predomínio da hemoglobina S (HbS). Na doença falciforme é CORRETO\nafirmar:","options":{"A":"A síndrome torácica aguda é um evento agudo e paciente com doença falciforme, caracterizado\npela presença de febre e/ou sintomas respiratórios\n(taquipneia, dispneia, tosse e dor torácica) e a\npresença de infiltrado pulmonar na radiografia de tórax descarta o diagnóstico.","B":"Na anemia falciforme, a crise aguda de sequestro esplênico pode ocorrer mais frequentemente\napós os 6 anos de idade.","C":"Nos pacientes com doença falciforme e osteomielite, o patógeno mais comum é a Salmonella.","D":"No paciente com doença falciforme, a principal causa de aplasia medular eritrocítica é a infecção\npelo Haemophilus, que acomete principalmente\ncrianças na faixa etária de 4 a 10 anos, por seu\ntropismo pelas células precursoras eritropoiéticas."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-212914","number":"212914","sourceNumber":"212914","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação às anemias hemolíticas, todas as afirmativas abaixo estão corretas, exceto:","options":{"A":"Esferocitose hereditária: o diagnóstico baseia-se na anemia crônica, reticulocitose esferocitose\ne\ncurva de fragilidade osmótica diminuída.","B":"Anemia falciforme: predisposição à infecção por bactérias capsuladas.","C":"Deficiência de glicose-6-fosfato-desidrogenase: é comum a história de episódio de hemólise com\nperíodos de remissão, em crianças do sexo masculino.","D":"Talassemia maior: anemia importante, deformidades óssea e dentária podem estar presentes.","E":"Anemia hemolítica autoimune: autoanticorpos se ligam à superfície das hemácias, ocasionando\nsua destruição via sistema complemento ou sistema\nreticuloendotelial."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-196790","number":"196790","sourceNumber":"196790","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Jerônimo é morador da região das montanhas capixabas têm ascendentes italianos,\ntinha manifestações de anemia e foi diagnosticado\ncom Talassemia, sabe-se que há dois tipos; Alfa\n\n(a) e Beta (ß). Marque a CORRETA sobre quais indivíduos / populações são afetados pela\nTalassemia Beta:","options":{"A":"Europeus (Central)","B":"Europeus (Nórdico)","C":"Asiáticos (Sudeste)","D":"Africanos (Costa Atlântica)"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-215136","number":"215136","sourceNumber":"215136","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menino de 4 anos tem diagnóstico de anemia falciforme e é levado ao pronto socorro\ncom quadro agudo de febre e queda importante\ndos níveis de hemoglobina, sendo caracterizado\ncomo episódio aplásico. O agente viral mais frequentemente envolvido nesses episódios é o:","options":{"A":"Citomegalovírus.","B":"Vírus herpes simples.","C":"Vírus Epstein-Baar.","D":"Hantavírus.","E":"Parvovírus B 19."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-187463","number":"187463","sourceNumber":"187463","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Numa consulta em Unidade Ambulatorial Dra Fergie atende Dona Julita, 75 anos, que\ntraz exames laboratoriais numa consulta de\nrevisão. Olhando detidamente o resultado hemograma\na médica faz o seguinte comentário: ?É Dona Julita fique tranquila, no geral está tudo bem, mas... a\nsenhora está com a causa mais frequente de anemia?. Marque a opção CORRETA que indica qual\nseria este tipo mais comum de anemia a que se refere o Drª Fergie:","options":{"A":"Anemia por hiperesplenismo.","B":"Anemia por insuficiência medular.","C":"Anemia megaloblástica.","D":"Anemia ferropriva.","E":"Anemia falciforme."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-172557","number":"172557","sourceNumber":"172557","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 1 ano e 4 meses, em consulta de rotina, sem queixas ou alterações no\nexame físico e crescimento/desenvolvimento,\napresenta o seguinte exame laboratorial\n(Hemograma): Ht: 34,5% (VR: 36%); Hb: 11,5 g/dL (VR: 12 g/dL); RDW: 16% (VR: 11,5 a 14,5%);\n\nreticulócitos: 0,4% (VR: 0,5 a 1,5%); hipocromia e microcitose. Nesse caso:","options":{"A":"A terapia de escolha é a reposição de Fe elementar, por via oral; sugestivo de anemia por\ncarência de ferro.","B":"A terapia de escolha é a cobalamina parenteral (IM); sugestivo de anemia por deficiência de\nvitamina B12.","C":"Encaminhar para acompanhamento com hematologista; sugestivo de anemia hemolítica.","D":"A terapia de escolha é Fe parenteral; sugestivo de sangramento acentuado ou de difícil controle."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-187490","number":"187490","sourceNumber":"187490","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em todas as alternativas abaixo temos achados sugestivos de anemia ferropriva exceto\nna alternativa:","options":{"A":"Pica.","B":"Coiloniquia.","C":"Baixa resposta dos reticulócitos.","D":"Diminuição da capacidade total de ligação do ferro.","E":"Diminuição da ferritina sérica."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-162533","number":"162533","sourceNumber":"162533","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considera-se esplenomegalia de grande monta quando o baço se estende a mais de 8\ncentímetros do rebordo costal, ultrapassa a linha umbilical ou atinge peso superior a 1 kg. Qual das\nseguintes alternativas não representa uma causa frequente desse achado clínico?","options":{"A":"Anemia hemolítica autoimune","B":"Leucemia linfocítica crônica","C":"Cirrose com hipertensão porta","D":"Linfoma de zona marginal","E":"Mielofibrose com metaplasia mieloide"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-162558","number":"162558","sourceNumber":"162558","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual é a principal hipótese diagnóstica para a tríade: trombose de veia porta,\npancitopenia e anemia hemolítica?","options":{"A":"Púrpura trombocitopênica idiopática.","B":"Leucemia promielocítica aguda.","C":"Hemoglobinúria paroxística noturna.","D":"Púrpura trombocitopênica trombótica.","E":"Síndrome hemolítico-urêmica."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155367","number":"155367","sourceNumber":"155367","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente com doença falciforme em crise vaso-oclusiva álgica muito intensa (nota 9 em\n10 na escala analógica). Das condutas a\nseguir, assinale a mais apropriada nesse caso - com\nmaiores evidências de qualidade na literatura médica.","options":{"A":"Ofertar morfina por via parenteral o mais rápido possível.","B":"Mesmo com dor muito intensa, sempre iniciar com analgesia simples (dipirona ou paracetamol),\nsubindo gradativamente a escada de analgesia\nproposta pela OMS.","C":"A transfusão de hemácias deve ser feita, independente da Hb ou do hematócrito do paciente, já\nque reduz a intensidade e a duração da crise álgica.","D":"Hiper-hidratar por via venosa, sem parcimônia, mesmo pacientes euvolêmicos, uma vez que isso\nauxilia na melhora da vaso-oclusão.","E":"A oxigenoterapia é habitualmente contraindicada, já que pode causar vasoconstrição."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155486","number":"155486","sourceNumber":"155486","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em um paciente, com 22 anos de idade, apresentando cãimbras, fraqueza muscular e\nnormotensão arterial, os achados laboratoriais mostraram hipopotassemia (K = 2,5 mEq/L), renina e\naldosterona elevadas no sangue, alcalose metabólica, hipomagnesemia e excreção reduzida de\ncálcio na urina. Pela anamnese e pelas dosagens na urina, foram afastadas as possibilidades de\nvômitos sub-reptícios e abuso de diuréticos. A hipótese diagnóstica mais provável para explicar os\nachados clínicos e laboratoriais, nesse caso, é de:","options":{"A":"Síndrome de Bartter clássica.","B":"Síndrome de Gilteman.","C":"Hiperaldosteronismo primário.","D":"Síndrome de Liddle.","E":"Síndrome de Fanconi."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-148599","number":"148599","sourceNumber":"148599","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de quatro anos é trazida, pela mãe, a uma consulta de puericultura com palidez\ncutânea e fadiga. Foi solicitado hemograma, que apresentou hemoglobina de 8,3 g/dl. Na\ninvestigação da causa da anemia, são importantes alguns conhecimentos. Qual das afirmativas\nabaixo está ERRADA?","options":{"A":"A anemia fisiológica infantil ocorre do 2º ao 4º mês de vida. A anemia em criança com 4 anos de\nidade sempre deve ser pesquisada.","B":"A anemia por deficiência de ferro é hipocrômica e microcítica por reticulocitose.","C":"A anemia por deficiência de vitamina B12 é macrocítica.","D":"A anemia perniciosa é macrocítica.","E":"A anemia sideroblástica apresenta hipocromia com ferro sérico alto."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155398","number":"155398","sourceNumber":"155398","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual o melhor exame para avaliar as reservas corporais de ferro?","options":{"A":"Concentração da hemoglobina corpuscular média.","B":"Transferrina sérica.","C":"Volume corpuscular médio.","D":"Protoporfirina eritrocitária livre.","E":"Ferritina sérica."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155427","number":"155427","sourceNumber":"155427","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pré-escolar de 2 anos e 10 meses, portador de anemia falciforme, é levado para\natendimento médico em um serviço de emergência\ncom queixa de dor abdominal, irritabilidade e\npalidez. Ao exame físico apresentava-se hipocorado (2+/4+), com temperatura axilar de 38°C e\nbaço palpável a 6 cm do rebordo costal esquerdo. Foi solicitado hemograma, que revelou\nleucocitose, Hb= 6 g/dl e reticulocitose. Assinale a opção que indica a provável hipótese\ndiagnóstica\npara o caso descrito:","options":{"A":"Crise aplástica.","B":"Sequestro esplênico.","C":"Cisto de colédoco.","D":"Pancreatite aguda.","E":"Síndrome torácica aguda."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-106404","number":"106404","sourceNumber":"106404","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente hipertenso e diabético de 60 anos vai se submeter a um cateterismo\ncardíaco daqui a 4 horas. Na avaliação\npré-procedimento, você identifica que ele tem um clearence\nde creatinina estimado de 30 ml/minuto por 1,73 m². Ele não tem insuficiência renal aguda. Qual\ndas medidas abaixo irá DEFINITIVAMENTE reduzir o risco de nefropatia induzida por contraste\nneste paciente?","options":{"A":"Dopamina.","B":"Fenoldopam.","C":"Indometacina.","D":"N-acetilcisteína.","E":"Bicarbonato de sódio."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-88916","number":"88916","sourceNumber":"88916","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"NÃO se relaciona à glomerulonefrite pós-estreptocócica (GNPE):","options":{"A":"A reação inflamatória atinge todos os glomérulos de ambos os rins","B":"A perda da integridade da membrana basal diminui o ritmo de filtração glomerular","C":"Há formação de imunocomplexos (Ag-Ac) circulantes com ativação do sistema complemento","D":"A diminuição do volume filtrado aumenta a reabsorção tubular de sódio e água","E":"A hipervolemia representa o principal componente da sua fisiopatologia"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-88939","number":"88939","sourceNumber":"88939","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação à glomerulonefrite difusa aguda (GNDA), podemos afirmar, EXCETO:","options":{"A":"Constitui a principal causa de síndrome nefrítica de início súbito na infância.","B":"A hematúria macroscópica é a forma mais comum de apresentação oligossintomática.","C":"A recuperação espontânea ocorre na maioria absoluta dos pacientes.","D":"A reação inflamatória nos glomérulos é responsável pela hematúria, leucocitúria, proteinúria e\ncilindrúria que ocorrem na doença.","E":"A tríade proteinúria, edema e hematúria é característica da GNDA e serve de base para o\nseu diagnóstico."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-88931","number":"88931","sourceNumber":"88931","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pré-escolar de cinco anos de idade é internado por edema bipalpebral, redução do\nvolume urinário e urina escura. Exame físico na internação: PA = 130 x 100 mmHg; FC = 80 bpm;\ncriança eutrófica, orientada, edema generalizado, leve palidez cutaneomucosa, RCR em 2T e\ncicatrizes compatíveis com lesões de impetigo nos membros superiores. Evoluiu bem com o\ntratamento instituído e teve alta. O melhor exame de laboratório a ser usado como critério de\nprognóstico no acompanhamento ambulatorial é:","options":{"A":"Colesterol.","B":"Complemento sérico (fração C3).","C":"Anti-DNase.","D":"Sedimento urinário.","E":"Antiestreptolisina O."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-59460","number":"59460","sourceNumber":"59460","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menor de 6 anos foi levado à emergência pediátrica referindo edema em pálpebras e\nMMII, diminuição da diurese e urina concentrada. Ao exame: BEG. Orientado. Edema bilateral de\npálpebras, sem flogose. Normocorado. Hidratado. Acianótico. Anictérico. PA: 140-90 mmHg. ACV e\nAR sem alterações. MMII com edema de cacifo (++/4+) até 1/3 médio, sem flogose; lesões\ncicatriciais em tornozelo direito. Genitália masculina sem anormalidades. Relacionado ao caso\nclínico podemos afirmar:","options":{"A":"Trata-se provavelmente de uma síndrome nefrítica, sendo a lesão basicamente glomerular, a\nreabsorção tubular de sódio continua ocorrendo normalmente, o que contribui para a expansão do\nvolume extracelular, hipervolemia e supressão do sistema renina-angiostensina-aldosterona, sendo\na hipertensão observada volume-dependente.","B":"A lesão glomerular é resultado de um processo inflamatório de origem infecciosa, onde o agente\netiológico mais comum é o estreptococo beta-hemolítico do grupo A.","C":"Os sintomas em geral surgem durante uma infecção estreptocócica de vias aéreas superiores ou\nde pele e caracterizam uma síndrome\nnefrítica com edema, hipertensão arterial, hematúria e\noligúria.","D":"A alta hospitalar não deve ser dada antes da normalização da pressão arterial, hematúria, do\ncomplemento sérico e dos níveis de ureia e creatinina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-59102","number":"59102","sourceNumber":"59102","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menino de quatro anos, hígido até então, é internado com história de edema bipalpebral\nbilateral (mais intenso ao acordar) e\noligúria percebidos pela mãe, há cinco dias. A mãe diz que\nvinha percebendo que as roupas com elástico vinham deixando marcas no abdome do menor há\nalguns dias. Nega ter havido quadro similar anteriormente e diz que ele não fez uso de nenhum\nmedicamento. Exame físico: afebril, eupneico, pressão arterial de 80/60 mmHg, edema bipalpebral\nbilateral, de membros inferiores e bolsa escrotal e aumento indolor de volume abdominal com\nmacicez móvel positiva. Exame de urina: densidade urinária: 1015, hemácias: 3/campo, proteína:\n3+/4+: piócitos: 4/Campo, cilindros ausentes. Considerando a principal hipótese diagnóstica e sua\nfisiopatogenia, o tratamento inicial indicado é:","options":{"A":"Corticoide sistêmico.","B":"Albumina humana.","C":"Anti-hipertensivo.","D":"Diurético de alça.","E":"Antibiótico."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-43924","number":"43924","sourceNumber":"43924","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 49 anos, negro, tem o diagnóstico histológico de Glomeruloesclerose Focal\n(GESF) após ser atendido no ambulatório com edema intermitente 2+ em MMII. Seis meses atrás\ntinha creatinina de 0,9 mg/dl. Considerando a evolução de GESF nesse paciente,\ncomparativamente com pacientes de raça branca, qual das abaixo é a mais correta?","options":{"A":"A resposta à corticoterapia é melhor.","B":"A progressão para estágio final da doença é mais rápida.","C":"A manifestação inicial da doença é mais tardia.","D":"Proteinúria não nefrótica é mais frequente.","E":"Nenhuma das respostas anteriores."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-43323","number":"43323","sourceNumber":"43323","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre a GNDA: ( ) A forma mais comum é pós-estreptocócica, onde o provável\nantígeno desencadeante da lesão renal relaciona-se à\ncepas nefritogênicas do estreptococo\nbeta-hemolítico do grupo A, tendo como porta de entrada a pele ou a orofaringe. ( ) O EAS\nevidencia hematúria, proteinúria e piúria. Há retenção de escórias e o complemento sérico (C3)\n\nestá aumentado nas primeiras semanas, confirmando o diagnóstico. ( ) Oligoanúria por mais de 48\na 72 horas, hematúria macroscópica e/ou\nretenção de escórias por mais de 4 semanas são\nalgumas das alterações que indicam a biopsia renal. ( ) A criança com GNDA deve ser mantida\ninternada até a completa normalização das alterações clínicas e laboratoriais decorrentes da\ndoença. Marque a sequência correta:","options":{"A":"V - V - F - F","B":"F - F - F - V","C":"V - F - V - F","D":"F - F - V - F","E":"F - F - F - F"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-44018","number":"44018","sourceNumber":"44018","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre síndrome nefrótica na infância, qual a afirmativa está incorreta?","options":{"A":"A maioria dos casos corresponde à síndrome nefrótica secundária a doenças sistêmicas,\nmetabólicas ou infecciosas.","B":"As principais variantes são lesão histológica mínima e glomeruloesclerose segmentar e focal.","C":"A maioria dos casos ocorre em pacientes do sexo masculino, na idade pré-escolar.","D":"A pressão arterial na síndrome nefrótica com lesão histológica mínima, geralmente, é normal.","E":"Os pacientes com síndrome nefrótica são propensos a infecções bacterianas, principalmente o\nStreptococcus pneumoniae e bactérias Gram-negativas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-43977","number":"43977","sourceNumber":"43977","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em um exame de urina de rotina em uma menina de 12 meses, assintomática, foi\nevidenciado hematúria, confirmado por mais dois exames, sem proteinúria ou outra alteração\nurinária. O pediatra refez toda a anamnese e exame físico e iniciou uma investigação laboratorial.\nQual destes exames seria fundamental neste início para direcionamento da investigação?","options":{"A":"Dosagem de complemento sérico.","B":"Avaliação de dismorfismo eritrocitário.","C":"Audiometria.","D":"Coagulograma.","E":"Função renal."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-32483","number":"32483","sourceNumber":"32483","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma estudante de 19 anos chega ao consultório queixando-se de urina escura após\njogar basquete. Nega sintomas articulares ou\nprurido, mas se lembra de dor de garganta uma\nsemana antes do episódio de urina escura. Ao exame sua pressão arterial é normal e não há\nedema. O restante do seu exame é normal. Hemograma, ureia, creatinina, eletrólitos e\ncomplemento sérico também são normais. O EAS mostra proteína +/4; hemácias campos repletos;\ncilindros hialinos. Qual é o provável diagnóstico?","options":{"A":"Glomerulonefrite pós-estreptocócica.","B":"Nefropatia por IgA.","C":"Glomerulonefrite membranosa.","D":"Glomerulonefrite membranoproliferativa.","E":"Glomerulonefrite por lesões mínimas."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-27339","number":"27339","sourceNumber":"27339","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Escolar de sete anos é levado ao hospital, pois está ?urinando pouco e a urina está\nescura?. Ao exame verifica-se edema generalizado e hipertensão arterial. Dentre as\nglomerulopatias responsáveis por esta síndrome, a mais frequente na infância é:","options":{"A":"Síndrome nefrótica por lesões mínimas","B":"Glomerulonefrite membranoproliferativa","C":"Nefropatia por IgA","D":"Nefropatia associada ao Lúpus Eritematoso Sistêmico","E":"Glomerulonefrite pós-estreptocócica"},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-23093","number":"23093","sourceNumber":"23093","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança escolar de 07 anos foi atendida de urgência por cefaleia. Relatou piodermites\nhá 02 semanas. Não foi encontrada nenhuma\nalteração no exame físico ou anamnese, exceto\npressão arterial no percentil 90P e ganho pequeno de peso e pequeno edema de face. O exame\nsimples de urina mostrou apenas hematúria microscópica. Nega outros sinais e sintomas. O\ndiagnóstico e conduta é:","options":{"A":"Síndrome Nefróitica por glomerulonefrite por lesões mínimas necessitando internação.","B":"Síndrome Nefrítica por glomerulonefrite difusa aguda e dosagem de C3, ureia, creatinina e\ntratamento ambulatorial.","C":"Nefrite intersticial infecciosa, medicada com antibiótico.","D":"Síndrome de Alport, devendo ser dosado a Ig A.","E":"Acidose Tubular Renal Distal, tratada com repouso e controle hipertensivo em regime hospitalar."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-9427","number":"9427","sourceNumber":"9427","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"É INCORRETO sobre a síndrome nefrótica:","options":{"A":"Presença de proteinúria.","B":"Ocorrência de hipoalbuminemia.","C":"Presença de edema.","D":"Aumento da lipase lipoproteica.","E":"Hiperlipidemia."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-355627","number":"355627","sourceNumber":"355627","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma paciente de 26 anos de idade, portadora de anemia falciforme, sem seguimento\nclínico adequado, procura atendimento\nambulatorial com objetivo de retomar o acompanhamento\nrotineiro. Apresentou quatro crises álgicas de falcização, quatro episódios de pneumonias\ncomunitárias e a necessidade de dez transfusões de concentrados de hemácias nos últimos 12\nmeses. No momento, encontra-se com PA 120 mmHg x 80 mmHg, FC 100 bpm, FR 18 irpm, afebril\ne com Sat02 98%,sem queixas álgicas. A respeito deste caso clínico e das ações terapêuticas\nindicadas nesse momento para a paciente, com o intuito de redução das crises álgicas e diminuição\ndas taxas de internações, assinale a alternativa correta:","options":{"A":"avaliação sorológica de doenças transmissiveis pelo sangue e vacinação para pneumococo e\nmeningococo","B":"início de hidroxiureia com objetivo de aumento dos níveis de hemoglobina fetal e redução do\nnúmero de crises de falcização, revisão do calendário vacinal para avaliação de cobertura de\ngermes capsulados e uso de ácido fólico","C":"realização de ecocardiograma transtorácico palpação difusa, pelo elevado risco de hipertensão\npulmonar secundária assintomática nos pacientes portadores de anemia falciforme","D":"administração de hidroxiureia com objetivo de reducão da contagem leucocitária e diminuição do\nrisco de hiperviscosidade sistêmica, principal responsável pelo risco de AVC nesses pacientes","E":"solicitação de ecodoppler transcraniano, pois, em razão do perfil de recorrência das crises, a\navaliação do fluxo sanguíneo cerebral se faz necessária com objetivo de redução do risco de\nacidente vascular cerebral (AVC)."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-363920","number":"363920","sourceNumber":"363920","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual é o principal sintoma da anemia falciforme em lactentes?","options":{"A":"Febre alta.","B":"Icterícia prolongada.","C":"Policitemia.","D":"Dor intensa."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-339765","number":"339765","sourceNumber":"339765","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Que exame complementar deve ser solicitado para elucidação etiológica de uma\npaciente de 70 anos, portadora de anemia megaloblástica por deficiência de vitamina B12 e\nqueixas dispépticas?","options":{"A":"Colonoscopia","B":"Pesquisa do anticorpo antifator intrínseco","C":"Endoscopia com biópsia da segunda porção duodenal","D":"Coombs direto","E":"Mielograma"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-342623","number":"342623","sourceNumber":"342623","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando-se as anemias microcíticas e hipocrômicas, assinale a alternativa\ncorreta:","options":{"A":"têm, como principais diagnósticos diferenciais, a anemia ferropriva, a talassemia e a anemia de\ndoença crônica","B":"ocorrem com aumento de reticulócitos por se trata de anemias hiperproliferativas","C":"o diagnóstico definitivo necessita de mielograma","D":"o tratamento é feito com sulfato ferroso"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-346438","number":"346438","sourceNumber":"346438","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 04 anos, asmática e com diagnóstico de anemia falciforme, apresenta\nquadro de exacerbação da asma, sem febre\nassociada, com radiografia de tórax sem alterações.\nNo dia seguinte, apresentou piora da dispnéia, dor torácica importante (09/10) e saturação de 92%\ncom máscara de oxigênio não reinalante a 15 l/min. Qual o provável diagnóstico? Além de\noxigenação, broncodilatador e expansão volêmica, qual a conduta mais adequada?","options":{"A":"Pneumonia. Iniciar analgésico não opióide e repetir imagem pulmonar;","B":"Pneumonia. Iniciar analgésico não opioide e não repetir imagem pulmonar;","C":"Síndrome torácica aguda. Iniciar analgésico opioide e repetir imagem pulmonar;","D":"Síndrome torácica aguda. Iniciar analgésico opioide e não repetir imagem pulmonar."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-321601","number":"321601","sourceNumber":"321601","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O tratamento para anemia ferropriva, de acordo com o consenso da Sociedade\nBrasileira de Pediatria (SBP) de 2021, consiste na administração de","options":{"A":"ferro elementar na dose de 3 a 6 mg/kg/dia por 6 meses.","B":"ferro elementar na dose de 1 a 2 mg/kg/dia por 6 meses.","C":"glicinato férrico na dose de 0,5 mg/kg/dia por até 30 dias.","D":"glicinato férrico na dose de 2 a 4 mg/kg/dia por 12 meses."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-300894","number":"300894","sourceNumber":"300894","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Malácia é o termo utilizado para gestante que tem:","options":{"A":"aversão a odores.","B":"desejo de comer substâncias não convencionais.","C":"cansaço exacerbado.","D":"aumento do desejo sexual."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-300801","number":"300801","sourceNumber":"300801","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"As vitaminas são compostos orgânicos presentes em pequenas quantidades nos\nalimentos. Não são fontes diretas de energia,\nmas desempenham papel essencial na regulação de\nprocessos metabólicos. Considerando as principais carências vitamínicas na prática clínica, alguns\nsinais e sintomas da deficiência de vitamina B9 são:","options":{"A":"Síndrome carcinoide, alcoólatras, gastrectomizados, anorexia nervosa, uso prolongado de\nIsoniazida, Pirazinamida e Cloranfenicol.","B":"Anemia megaloblástica, leucopenia, anorexia, diarreia, glossite, dermatite, acne, irritabilidade\ne\ndemência.","C":"Hipoprotrombinemia plasmática, hematúria e epistaxe.","D":"Hemólise, síndrome cerebelar, neuropatia periférica, miopatia e retinopatia."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-295360","number":"295360","sourceNumber":"295360","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 25 anos, previamente hígida, apresentou quadro de dores abdominais\nintermitentes associadas a fadiga, dispneia progressiva e palidez cutaneomucosa. Ao exame,\ndescorada moderada, com icterícia leve e baço a 3 cm do rebordo costal esquerdo. Hemograma\ncom HB: 7,5 g/dl, VCM: 105, leucócitos de 2.500/uL, plaquetas de 102.000/uL, DHL de 650 U,\nbilirrubina indireta de 2,8 TGP de 25,0. Ao ultrassom, notada esplenomegalia leve e trombose de\nveia porta. Nesse caso, a hipótese diagnóstica é:","options":{"A":"Aplasia de medula óssea.","B":"Esferocitose hereditária.","C":"Anemia megaloblástica.","D":"Hemoglobinúria paroxística noturna."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-317946","number":"317946","sourceNumber":"317946","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia da doença crônica é caracterizada por","options":{"A":"nível normal de ferro sérico.","B":"transferrina diminuída.","C":"diminuição da ferritina circulante.","D":"reservas de ferro normais ou aumentadas."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-300825","number":"300825","sourceNumber":"300825","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na faixa etária pediátrica, a carência alimentar constitui a causa mais comum de\nanemia, particularmente nos países em\ndesenvolvimento. Quanto à anemia megaloblástica, analise\nas proposições abaixo e, em seguida, assinale a alternativa CORRETA: I. A anemia megaloblástica\né uma forma de anemia macrocítica que ocorre por defeito no metabolismo do ácido nucleico e\nconsequente defeito na divisão celular, com desequilíbrio entre núcleo e citoplasma. II. A anemia\nmegaloblástica é causada por deficiência de vitamina B12 e/ou ácido fólico, mas também pode ser\ndevido a medicações que interferem na síntese de DNA. III. A anemia megaloblástica é provocada\npela deficiência de ferro no organismo. Acarreta prejuízos em curto e longo prazos no\ndesenvolvimento neuropsicomotor e na aprendizagem, além de comprometimento na resposta do\nsistema imunológico.","options":{"A":"Somente I está correta.","B":"Somente I e II estão corretas.","C":"Somente II e III estão corretas.","D":"I, II e III estão corretas."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-300941","number":"300941","sourceNumber":"300941","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente de 13 anos de idade, portador de anemia falciforme está apresentando\npriapismo há 3 horas, de modo contínuo, qual\ndas alternativas abaixo apresenta a conduta inicial\nmais adequada neste caso?","options":{"A":"Solicitar avaliação do urologista para punção do corpo cavernoso por conta do risco de\ndisfunção erétil no priapismo prolongado.","B":"Solicitar ao paciente que esvazie a bexiga, estimular hidratação intensa (via oral e parenteral,\nse\nnecessário), prescrever analgesia de horário com morfina, associada a analgésicos comuns e pedir\navaliação da urologia se a resposta ao tratamento clínico não for satisfatória.","C":"Estimular diurese, indicar suplementação de oxigênio e exsanguineotransfusão, prescrever\nanalgesia com morfina e analgésicos comuns e solicitar avaliação do urologista.","D":"Indicar suplementação de O2, transfusão de concentrado de hemácias e avaliação do urologista."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313234","number":"313234","sourceNumber":"313234","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um escolar de 9 anos é trazido à Unidade Básica de Saúde pela mãe com queixa de\ncansaço, má aceitação alimentar e baixo rendimento escolar. A mãe refere que a criança é muito\nseletiva na aceitação alimentar. O peso e a estatura estão no percentil 10%, mas se apresenta\nhipocorada (++/4+), com FC = 110bpm e FR = 26irpm, sem outras alterações. Considerando essas\ninformações, a alteração mais provável do hemograma é:","options":{"A":"anemia hipocrômica, microcítica com anisocitose","B":"anemia normocrômica, normocítica sem anisocitose","C":"anemia hipocrômica, normocítica sem anisocitose","D":"anemia normocrômica, macrocítica com anisocitose"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313235","number":"313235","sourceNumber":"313235","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma paciente de 9 anos, com anemia falciforme, chegou ao pronto-socorro com história\nde hemiparesia à esquerda há 2 horas. Ao exame\nfísico, encontrava-se consciente, orientada e\nnormotensa. O hemograma mostrou hemoglobina de 8,5g/dL. A tomografia de crânio não mostrou\nanormalidades. Com base nesse caso hipotético a conduta mais adequada seria:","options":{"A":"transfusão simples de concentrado de hemácias filtradas, 15mL/kg","B":"manter apenas observação clínica com hidratação e analgesia","C":"aguardar ressonância magnética de encéfalo","D":"realizar transfusão de troca com hemácias filtradas e fenotipadas"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-316390","number":"316390","sourceNumber":"316390","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre a anemia ferropriva na pediatria, leia as afirmações abaixo e assinale a\nalternativa correta: I - O estágio 1 é\nconhecido como depleção de ferro, em que há redução nos\ndepósitos de ferro no fígado, baço e medula óssea. O principal exame que avalia as reservas de\nferro é a ferritina. II - O estágio 2 cursa com deficiência de ferro e são utilizados para o\ndiagnóstico\no ferro sério que encontra-se baixo, aumento da capacidade total de ligação da transferrina e da\nsaturação de transferrina. III - O estágio 3 é a anemia ferropriva; neste estágio há redução de\nhemoglobina e hematócrito, podendo também haver leucopenia, plaquetose e alteração de\nreticulócitos. IV - O tratamento da anemia ferropriva é realizado por 2 a 6 meses, no mínimo 8\nsemanas. Podme ser usados sais ferrosos ou sais férricos, sendo que estes últimos têm baixo\ncusto e estão relacionados com mais sintomas gastrointestinais, levando a uma má adesão.","options":{"A":"Corretas: I, II e III","B":"Corretas: I, III e IV","C":"Incorretas: II e III","D":"Incorretas: II e IV"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-277401","number":"277401","sourceNumber":"277401","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando os dados a seguir, referentes à anemia em adultos, relacione os tipos de\nanemia e as causas: Tipos de anemia: I - Microcítica II - Normocítica III - Macrocítica Causas: ( )\nDoenças crônicas ( ) Deficiência de ferro ( ) Deficiência de vitamina B12 ( ) Alcoolismo ( )\nTalassemias A sequência correta é:","options":{"A":"II, I, III, III, I","B":"I, I, III, II, III","C":"I, II, II, I, III","D":"II, I, II, I, I"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-285065","number":"285065","sourceNumber":"285065","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação às anemias hipocrômicas e microcíticas:","options":{"A":"A causa mais comum é deficiência de vitamina B12.","B":"Devem ser tratadas com sulfato ferroso.","C":"Devem ser investigadas com mielograma.","D":"Os principais diagnósticos diferenciais são anemia ferropriva, talassemia e anemia de doença\ncrônica","E":"Os reticulócitos geralmente estão aumentados por se tratar de anemia hiperproliferativa"},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-281813","number":"281813","sourceNumber":"281813","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 32 anos, com lúpus eritematoso sistêmico, dá entrada no pronto-socorro\ncom intensa dispneia e dosagem de hemoglobina\nde 3,1 g/dL. O teste de Coombs direto é reagente\n(4+/4+); é solicitada a transfusão de dois concentrados de hemácias, porém o serviço de\nhemoterapia informa que todos os concentrados de hemácias cruzados foram incompatíveis e a\npesquisa de anticorpo irregular foi positiva. Também não foi possível definir o grupo sanguíneo\nABO e Rh do paciente. A conduta recomendada para este paciente é:","options":{"A":"iniciar corticoide e suspender a transfusão.","B":"realizar uma plasmaférese de urgência para retirar o autoanticorpo.","C":"transfundir, lentamente, concentrado de hemácias O Rh negativo, mesmo incompatível.","D":"continuar cruzando bolsas de concentrados de hemácias até encontrar alguma que seja\ncompatível."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-274761","number":"274761","sourceNumber":"274761","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre anemia ferropriva, afirma-se:","options":{"A":"observa-se aumento do número de linfócitos e risco aumentado de intoxicação por cromo.","B":"não se justifica tratamento empírico antes de investigar possíveis causas de sangramento.","C":"os sais de ferro devem ser administrados com as refeições para facilitar a absorção duodenal.","D":"deve-se pesquisar doença celíaca ou infecção por H. pylori quando não houver resposta ao\ntratamento."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-273156","number":"273156","sourceNumber":"273156","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em um exame, quando detectada a alteração no número de eritrócitos e na quantidade\nde hemoglobinas, pode-se identificar como\nconsequência final o quadro de:","options":{"A":"Anorexia.","B":"Hipóxia tecidular.","C":"Isquemia cerebral.","D":"Anoxia cerebral."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-273157","number":"273157","sourceNumber":"273157","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"É função principal do eritrócito:","options":{"A":"Transporte do surfactante.","B":"Transporte do hematócrito.","C":"Transporte da hemoglobina.","D":"Transporte apenas do grupo granulócito."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-265877","number":"265877","sourceNumber":"265877","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando que o oxigênio se liga à porção heme da molécula de hemoglobina,\nassinale a alternativa CORRETA:","options":{"A":"Cada molécula de hemoglobina carrega quatro moléculas de oxigênio.","B":"Cada molécula de meta hemoglobina carrega oito moléculas de oxigênio.","C":"A hemoglobina oxigenada (oxihemoglobina) carrega seis moléculas de oxigênio.","D":"A desoxi-hemoglobina carrega duas moléculas de oxigênio."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-277469","number":"277469","sourceNumber":"277469","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma adolescente de 13 anos é portadora de anemia falciforme (Hb SS). Refere que há\n2 meses apresenta náuseas, vômitos\nesporádicos e dor em cólica no quadrante superior direito do\nabdome, com piora progressiva. Nega sintomas respiratórios. Qual é o exame subsidiário que tem\nmelhor capacidade diagnóstica?","options":{"A":"Hbs Ag","B":"EAS e urocultura","C":"USG","D":"Radiografia de tórax"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-273211","number":"273211","sourceNumber":"273211","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando a dimensão étnico-racial dos agravos à saúde, a anemia falciforme é\numa doença geneticamente transmitida,\ntorneada de tensões e desafios. Considerando a anemia\nfalciforme, analise as proposições abaixo e, em seguida, assinale a alternativa que as classificam\nem V (verdadeira) ou F (falsa) de forma respectivamente CORRETA: I. A origem dos genes\nresponsáveis pela anemia falciforme é africana e esses genes são distribuídos largamente na\npopulação da América Latina devido às altas taxas de miscigenação. II. Como os genes\nresponsáveis pela anemia falciforme não são acoplados aos genes responsáveis pela coloração da\npele, traços faciais ou tipos de cabelo, não podem ser restritos à população brasileira, definida\nsocialmente como ?negra? ou ?parda?. III. A associação feita entre a ?raça negra? e a anemia\nfalciforme tem o efeito pragmático de naturalizar aquilo que não é natural: ?a raça negra?.","options":{"A":"V, F, V.","B":"F, V, F.","C":"V, F, F.","D":"F, V, V."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-254209","number":"254209","sourceNumber":"254209","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente 25 anos, sexo feminino, assintomática , encaminhada para hematologista por\nalterações em exames pré-operatórios de abdominoplastia. O hematologista completou a\ninvestigação diagnóstica com os achados descritos abaixo. Hemograma: Hb 10mg/dl, VCM 25pg,\nRDC 20%; Eletroforese de Hemoglobina: Hemoglobina A1 - 93%; Hemoglobina A2 - 68% e\nHemoglobina Fetal - 0,2% (imagem ao lado); Valores de referência; Hemograma: Hb 13.5-19.6g/dl;\nVCM 77-101FI; HCM 28-33 pg; RDW 11.5-14.5; Eletroforese de Hemoglobina: Hemoglobina A1 -\n\n>= 96,8%; Hemoglobina A2 - entre 2,2 e 3,2% e Hemoglobina Fetal - <0,5%. Baseado apenas nos\nresultados acima descritos, é possível firmar o diagnóstico de:","options":{"A":"Beta talassemia maior.","B":"Beta talassemia menor.","C":"Alfa talassemia.","D":"Anemia ferropriva."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-248906","number":"248906","sourceNumber":"248906","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente de 88 anos, portador de doença arterial obstrutiva periférica em uso de\nantiagregantes plaquetários, vem apresentando quadro de astenia e cansaço, associado a palidez\ncutânea. Apresenta Hb = 7,1g/dL, com VCM = 72 e HCM = 22. Por se tratar de uma anemia\nhipocrômica e microcítica, aventou-se o diagnóstico de anemia ferropriva. Nesse caso, podemos\nafirmar que:","options":{"A":"a ferritina sérica nos casos de anemia ferropriva pode estar alta, principalmente em casos de\nsangramento gastrintestinal crônico","B":"a transfusão sanguínea é recomendada, após solicitação do perfil de ferro, principalmente\ndevido aos sintomas","C":"não será possível manter a hemoglobina elevada se os níveis de ferro sérico estiverem normais\ne a ferritina estiver baixa","D":"o paciente tem indicação apenas de reposição de ferro para tratamento de sua anemia, sem\nnecessidade de transfusão sanguínea"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-248907","number":"248907","sourceNumber":"248907","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando os dados a seguir, referentes à anemia em adultos, relacione os tipos de\nanemia e as causas: Tipos de anemia: I - Microcítica; II - Normocítica; III - Macrocítica; Causas:\n( )\nDoenças crônicas; ( ) Deficiência de ferro; ( ) Deficiência de vitamina B12; ( ) Alcoolismo; ( )\nTalassemias. A sequência correta é:","options":{"A":"II, I, III, III, I","B":"I, I, III, II, III","C":"I, II, II, I, III","D":"II, I, II, I, I"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-229824","number":"229824","sourceNumber":"229824","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O tipo mais frequente de anemia carencial na criança ocorre pela deficiência de ferro.\nNa investigação laboratorial, qual a alteração que\nocorre inicialmente na anemia por deficiência de\nferro?","options":{"A":"Ferritina sérica diminuída.","B":"Ferro sérico diminuído.","C":"Hemoglobina globular média diminuída.","D":"Hematócrito diminuído."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-241699","number":"241699","sourceNumber":"241699","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na doença falciforme, crises de anemia com baixa contagem de reticulócitos são\ncausadas, principalmente, por:","options":{"A":"deficiência de vitamina B12.","B":"deficiência de folato.","C":"infecção por parvovírus B19.","D":"fenômenos de vasoclusão.","E":"hemólise grave."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249852","number":"249852","sourceNumber":"249852","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente do sexo feminino, de 51 anos, queixa-se de cansaço e fraqueza há meses. O\nhemograma demonstra hemoglobina de 9.5 g/dL, hematócrito de 28.1%, VCM de 134 fL associado\na reticulócitos baixos. O hematologista faz um esfregaço de sangue periférico e observa\npolimorfonucleados hipersegmentados com cerca de cinco a seis segmentações. O exame que\nmais contribuiria para o diagnóstico correto seria:","options":{"A":"dosagem de B12 e folato.","B":"biópsia da medula óssea.","C":"ferritina sérica.","D":"eletroforese de hemoglobina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-246534","number":"246534","sourceNumber":"246534","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre as anemias, julgue os seguintes itens. I. Na anemia magaloblástica por\ndeficiência de vitamina B12, observa-se\ndefeito da maturação nuclear. II. Nas anemias carenciais\npor deficiência de ferro, o índice de anisiocitose encontra-se diminuído. III. Nas anemias\nhemolíticas\nautoimunes, pode-se observar aumento do índice de reticulócitos. Pode-se afirmar que apenas:","options":{"A":"o item I está certo.","B":"o item II está certo.","C":"o item III está certo.","D":"os itens I e II estão certos.","E":"os itens I e III estão certos."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-252749","number":"252749","sourceNumber":"252749","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à anemia falciforme, marque a alternativa INCORRETA:","options":{"A":"A presença de neutrofilia crônica, história de sequestro esplênico, aumenta a morbidade e reduz\na sobrevida.","B":"Com frequência os pacientes têm perda da função esplênica, o que aumenta a suscetibilidade\npara infecções, principalmente para o pneumococo.","C":"A crise do sequestro esplênico ocorre por obstrução arterial aguda do baço, causando isquemia\ne atrofia do baço, assim como dor súbita no\nhipocôndrio direito.","D":"As crises álgicas devem ser tratadas com hidratação vigorosa, investigação de fatores\ndesencadeantes, como infecções e analgesia agressiva."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-232231","number":"232231","sourceNumber":"232231","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 55 anos com Artrite Reumatoide (AR) foi\nencaminhada ao ambulatório de hematologia\npor causa de anemia. Ela tem AR há cerca de cinco\nanos e seu nível de hemoglobina vem diminuindo gradualmente de 14 g/dl para 9,5 g/dl. São\nsolicitados exames e observam-se os seguintes parâmetros: hemoglobina de 9,6 g/dl, leucócitos de\n\n8.500 com diferencial normal, plaquetas de 450 mil, ferritina de 240 ng/ml, saturação da\ntransferrina\nde 14%, proteína C reativa de 50 mg/ml. Nesse\ncaso, qual é o mecanismo fisiopatológico causador\nda anemia?","options":{"A":"O aumento da hepcidina induzida por citocinas aumentou a ferroportina e reduziu a absorção de\nferro e saturação da transferrina.","B":"A eritropoiese ineficaz aumentou a degradação de glóbulos vermelhos, a diminuição da\nhepcidina, a diminuição da ferroportina e a saturação da transferrina.","C":"O aumento da hepcidina induzida por citocinas diminuiu a ferroportina, reduziu a absorção de\nferro e a saturação da transferrina.","D":"O aumento da hepcidina induzida por citocinas diminuiu a ferroportina e aumentou a absorção\nde ferro."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-252750","number":"252750","sourceNumber":"252750","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O distúrbio que se caracteriza por deficiência do fator intrínseco por atrofia gástrica\nassociado à presença de anticorpos contra a célula parietal é a(o):","options":{"A":"Anemia hemolítica autoimune.","B":"Anemia perniciosa.","C":"Lúpus eritematoso sistêmico.","D":"Policitemia Vera."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-252751","number":"252751","sourceNumber":"252751","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O distúrbio que se caracteriza por deficiência do fator intrínseco por atrofia gástrica\nassociado à presença de anticorpos contra a célula parietal causa a deficiência de:","options":{"A":"Vitamina D.","B":"Vitamina B12.","C":"Vitamina A.","D":"Vitamina B1."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249491","number":"249491","sourceNumber":"249491","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"No paciente que apresenta diagnóstico de anemia falciforme pelo teste do pezinho, o\nresultado encontrado é:","options":{"A":"HgFSC","B":"HgFSA","C":"HgFA","D":"HgFS"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-249493","number":"249493","sourceNumber":"249493","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quais das alterações bioquímicas apresentadas abaixo estão relacionadas com a\npresença de hemólise?","options":{"A":"LDH, TGO, bilirrubina, haptoglobina.","B":"TGO, LDH, fosfatase alcalina, amilase.","C":"Haptoglobina, bilirrubina, ferritina, fosfatase alcalina.","D":"Ferritina, TGO, ácido úrico, LDH."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-229871","number":"229871","sourceNumber":"229871","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente com astenia em investigação com hematologista, traz consigo exames que\nrevelam: Hb 10mg/dl, VCM 65fL, HCM 25pg, RDW 20%, ácido fólico 5.0ng/ml; vitamina B12\n200pg/ml, Ferro 30mcg/dl, IST 15% e Ferritina 18ng/ml. TIBC 600mcg/dl. Reticulócito 0.1%. Valores\nde referência: Hb 13.5-19.6g/dl; VCM 77-101Fl, HCM 28-33 pg; RDW 11.5-14.5%; ácido fólico\n\n>3.37ng/ml; vitamina B12 300-900pg/ml; Ferro 50-170 mcg/dl; IST 20-50%; Ferritina 23-336ng/ml;\nTIBC 250-425mcg/dl. Reticulócito 0.5-2.1%. O provável\ndiagnóstico é anemia","options":{"A":"ferropriva.","B":"de doença crônica.","C":"Megaloblástica.","D":"hemolítica."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-234389","number":"234389","sourceNumber":"234389","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança de dois anos, portadora de doença falciforme, é atendida na unidade de\npronto atendimento com quadro de febre iniciada há 36 horas, sem outros sintomas associados. O\nexame físico não apresenta alterações além da temperatura de 38,9ºC. A conduta será:","options":{"A":"Acompanhamento ambulatorial e retorno em caso de persistência da febre após 48 a 72 horas\nou antes, se houver piora clínica.","B":"Realização dos seguintes exames complementares: hemograma, hemocultura, urocultura e\nradiografia de tórax; os resultados definirão o plano terapêutico.","C":"Admissão hospitalar e início de antibioticoterapia parenteral, mesmo antes dos resultados dos\nexames laboratoriais.","D":"Prescrição de oseltamivir, pois o exame físico sem alterações sugere doença viral, e esses\npacientes são grupo de risco para influenza grave."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-210536","number":"210536","sourceNumber":"210536","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre as complicações da anemia falciforme, julgue os itens a seguir. l. A crise\n\nvaso-oclusiva pode apresentar derrame articular e a artrocentese deve ser realizada de rotina. ll.\nDor lombar de forte intensidade pode indicar\ninfarto renal que leva à hematúria macroscópica e\ninsuficiência renal. lll. A síndrome torácica aguda é a forma mais comum de complicação pulmonar\nnesses pacientes. lV. Na faixa etária de até 20 anos, o AVC hemorrágico é a principal manifestação\nneurológica. Pode-se afirmar que:","options":{"A":"apenas os itens l, ll e lll estão certos.","B":"apenas os itens ll e lll estão certos.","C":"apenas os itens ll e lV estão certos.","D":"apenas os itens lll e lV estão certos.","E":"apenas os itens l, lll e lV estão certos."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-201946","number":"201946","sourceNumber":"201946","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em crianças com anemia falciforme:","options":{"A":"as crises de dor geralmene respodem ao uso de hidratação oral e antiinflamatório não hormonal","B":"a icterícia é decorrente da predisposição à hepatite","C":"deve-se fazer profilaxia com penicilina V oral, após o 1º quadro de pneumonia","D":"com síndrome torácica aguda apresentando dispneia com taquipneia acentuada, é indicada\ntransfusão simples ou troca parcial de sangue","E":"o sequestro esplênico geralmente tem remissão espontânea, podendo ser de acompanhamento\ndomiciliar"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-214939","number":"214939","sourceNumber":"214939","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considerando os dados a seguir, referentes à anemia em adultos, relacione os tipos de\nanemia e as causas: Tipos de anemia: I - Microcítica; II - Normocítica; III - Macrocítica. Causas:\n( )\nDoenças crônicas; ( ) Deficiência de ferro; ( ) Deficiência de vitamina B12; ( ) Alcoolismo; ( )\nTalassemias. A sequência correta é:","options":{"A":"II, I, III, III, I","B":"I, I, III, II, III","C":"I, II, II, I, III","D":"II, I, II, I, I"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-201739","number":"201739","sourceNumber":"201739","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A gastrite atrófica autoimune está mais frequentemente associada:","options":{"A":"À litíase biliar.","B":"À insuficiência biliopancreática.","C":"Ao lúpus eritematoso sistémico.","D":"À anemia perniciosa."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-216468","number":"216468","sourceNumber":"216468","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"G.F., 67 anos, fez um hemograma que mostrou anemia com aumento importante do\nvolume corpuscular médio. Para melhor investigação do caso, deve-se fazer a dosagem da(o):","options":{"A":"Ferritina.","B":"Cobalamina.","C":"Zinco.","D":"Tiamina."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-214185","number":"214185","sourceNumber":"214185","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia é um marcador clínico importante dos pacientes portadores da doença\nfalciforme, sendo, a transfusão de concentrados\nde hemácias, a intervenção terapêutica habitual\npara estes pacientes. Em relação a tal procedimento indica-se:","options":{"A":"Transfusão de concentrado de hemácias em pacientes com hemoglobina menor que 7,0 g/dL\nobjetivando melhor qualidade de vida.","B":"Sempre que possível deve-se utilizar hemácias fenotipadas para os sistemas RH, Kidd, Kell e\nDuffy.","C":"Tratamento em casos de crises dolorosas.","D":"Em casos de priapismo não há benefícios da realização exsanguíneo transfusão."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-216653","number":"216653","sourceNumber":"216653","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 24 anos de idade, sexo feminino, foi ao ambulatório de clínica médica\ndevido a astenia intensa. Ao exame físico\napresentava mucosas hipocoradas e aumento da\nfrequência cardíaca. Exames laboratoriais mostravam aumento de VCM (acima de 120) com\nferritina normal, ferro sérico e índice de saturação de transferrina também normais. Negava\nmenstruação excessiva e episódios de sangramento. O médico assistente solicitou endoscopia\ndigestiva alta, sendo encontrada pangastrite atrófica. A principal hipótese e exame complementar a\nser solicitado são respectivamente:","options":{"A":"Anemia megaloblástica e anticorpo antimicrossomal.","B":"Talassemia e anticorpo antifator intrínseco.","C":"Anemia perniciosa e anticorpo anticélula parietal.","D":"Anemia megaloblástica anticorpo antimitocondrial."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-214112","number":"214112","sourceNumber":"214112","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre o teste do pezinho: I - deverá ser colhido, idealmente, entre o 3º e o 5º dia de\nvida. II - pacientes submetidos a\nhemotransfusão antes da coleta do teste deverão ter sua coleta\nadiada até 120 dias após a administração do último hemoconcentrado. III - doenças maternas como\nhipertireoidismo podem interferir no resultado do exame do recém-nascido. IV - após 28 dias de\nvida não se deve mais realizar a coleta do teste do pezinho, sendo então indicada seguimento\nclínico rigoroso e investigação laboratorial dos pacientes que apresentarem sintomas de alerta para\nquaisquer das doenças incluídas no programa. Assinale as afirmações corretas relacionadas ao\nteste do pezinho:","options":{"A":"I e III.","B":"I e II.","C":"II e III.","D":"II e IV."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-216456","number":"216456","sourceNumber":"216456","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual das afirmações a seguir com relação à hemoglobina fetal é verdadeira?","options":{"A":"Ela é constituída de subunidade alfa e gama.","B":"Está presente em crianças normais até a idade de 6 anos.","C":"Ela é substituída pela hemoglobina adulta por volta da trigésima oitava semana de gestação.","D":"Ela tem menor afinidade por oxigênio que a hemoglobina adulta."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-216560","number":"216560","sourceNumber":"216560","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Os pais de uma criança recém-nascida estão muito preocupados, pois, no teste do\npezinho, houve observação de \"traço falciforme\". A fim de esclarecê-los sobre o que significa esse\nresultado de exame, as informações que devem ser repassadas aos pais sobre a doença, são:","options":{"A":"A presença de traço falciforme não predispõe a criança às complicações observadas na doença\nfalciforme homozigótica, como a síndrome torácica aguda.","B":"A doença é de transmissão autossômica dominante, portanto, basta um dos pais apresentarem\no traço para a ocorrência da anemia falciforme\nem seus filhos.","C":"A anemia falciforme se desenvolve em 60% dos pacientes portadores do traço falciforme,\nindependentemente de meninos ou meninas.","D":"A expectativa de vida para pacientes com traço falciforme é de 40 anos para meninos e 50 anos\npara meninas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-178808","number":"178808","sourceNumber":"178808","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação ao metabolismo do ferro na Anemia de Doença Crônica, assinale a\nalternativa correta.","options":{"A":"Ferro sérico baixo, ferritina sérica baixa, transferrina sérica baixa.","B":"Ferro sérico baixo, ferritina sérica alta, transferrina sérica baixa.","C":"Ferro sérico normal, ferritina sérica baixa, transferrina sérica normal.","D":"Ferro sérico normal, ferritina sérica baixa, transferrina sérica baixa.","E":"Ferro sérico alto, ferritina sérica alta, transferrina sérica baixa."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-185203","number":"185203","sourceNumber":"185203","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 24 anos foi encaminhada ao ambulatório de hematologia para investigação\nde anemia. Os exames solicitados pelo médico da\nfamília revelaram hiperbilirrubinemia indireta,\nDHL aumentado e COOMBS negativo. O hemograma apresentava hemoglobina = 9,8mg/dL,\nhematócrito 30%, CHCM elevado, VCM normal, e reticulocitose. A principal hipótese diagnóstica é:","options":{"A":"esferocitose","B":"alcoolismo","C":"anemia ferropriva","D":"anemia hemolítica autoimune"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-174095","number":"174095","sourceNumber":"174095","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A droga de escolha para tratamento da hemoglobinúria paroxística noturna, em sua\nforma hemolítica clássica, é a seguinte:","options":{"A":"Ciclosporina.","B":"Rituximabe.","C":"Eculizumabe.","D":"Cetuximabe."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-186468","number":"186468","sourceNumber":"186468","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 35 anos procura atendimento referindo cansaço, principalmente aos\nesforços, tonturas, mal-estar e hipermenorreia.\nNega outras comorbidades, nega uso de\nmedicamentos, nega gestações. Nega tabagismo e etilismo. Ao exame, paciente hipocorada\n(++/4+). Exames laboratoriais: hemoglobina: 8,5 g/dl, VCM: 65 fl, leucócitos: 7.000/mm³, plaquetas:\n230.000/mm³. A causa mais provável para a anemia da paciente é:","options":{"A":"Deficiência de ácido fólico.","B":"Anemia de doença crônica.","C":"Deficiência de ferro.","D":"Deficiência de vitamina B12."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-178787","number":"178787","sourceNumber":"178787","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Após a estabilização clínica de uma criança com anemia falciforme que apresentou\nAVC isquêmico, é realizada uma terapêutica\nespecífica para alteração dos níveis hematimétricos.\nQual é essa terapia e qual é seu objetivo?","options":{"A":"Transfusão sanguínea; aumentar a hemoglobina acima de 10 mg/dL.","B":"Transfusão sanguínea; aumentar a hemoglobina fetal acima de 70%.","C":"Exsanguíneotransfusão parcial; reduzir o nível de Hemoglobina S para menos de 30%.","D":"Exsanguíneotransfusão parcial; reduzir o nível de Hemoglobina S para menos de 60%.","E":"Transfusão sanguínea; aumentar a hemoglobina acima de 12 mg/dL."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-178834","number":"178834","sourceNumber":"178834","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à anemia ferropriva em crianças, considere os seguintes fatores. I. Aumento\nda contagem de reticulócitos ao final da\nprimeira semana de tratamento.; II. Aumento de 1 g/dl na\nhemoglobina após 1 a 2 meses.; III. Aumento da contagem de 3% no hematócrito após 1 a 2\nmeses. Quanto à análise da eficácia do tratamento, está correto o que se apresenta em:","options":{"A":"I, somente.","B":"II, somente.","C":"III, somente.","D":"I e III, somente.","E":"todas."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-186433","number":"186433","sourceNumber":"186433","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de três anos, portador de anemia falciforme, apresentando dor abdominal,\npalidez e prostração. Exame físico: Tax. =\n38,2°C, PA = 80 x 50 mmHg, palidez cutânea 3+/4+,\nicterícia de esclera, FC = 160 bpm, FR = 44 irpm, fígado: 1 cm do RCD, baço: 5 cm do RCE. A\nhipótese diagnóstica mais provável é:","options":{"A":"Hepatite A.","B":"Crise aplástica.","C":"Colelitíase aguda.","D":"Sequestro esplênico."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-185170","number":"185170","sourceNumber":"185170","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mãe leva seu filho lactente de 7 meses para consulta de puericultura, preocupada, pois\nacha seu filho muito pálido, irritado e com pouco apetite, há cerca de 2 meses. Não apresentou\ndoenças anteriores. Foi amamentado ao seio materno até 2 meses, quando iniciou leite de vaca\npuro e retirou o leite materno. Aos 6 meses iniciou, além de leite de vaca, legumes e frutas, que é\na\nalimentação atual. Ganho pondero estatural adequado. Desenvolvimento neuropsicomotor\nadequado. Ao exame, apresenta palidez cutâneo mucosa, abdômen levemente distendido com\nbaço percutível, sem outros achados. Qual a principal hipótese diagnóstica?","options":{"A":"Anemia secundária a doença celíaca.","B":"Anemia falciforme.","C":"Anemia por deficiência de ferro.","D":"Anemia por deficiência de vitamina b12."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-186513","number":"186513","sourceNumber":"186513","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pré-escolar, sexo feminino, 5 anos, há 6 meses em tratamento de anemia não\nresponsiva ao sulfato ferroso na dose de\n5mg/kg/dia, administrado meia hora antes do almoço e\njantar com suco de laranja. Nos antecedentes pessoais, não há nada digno de nota, recebeu\naleitamento materno exclusivo até o sexto mês de vida. O pai teve anemia recorrente na infância.\nAtualmente come adequedamente. Exame físico: paciente pálido, sem outras alterações.\n\nHemograma: Hm: 6.000.000/mm3; Hb: 10,2g/dL; Ht: 30%, VCM: 50 fL; HCM: 16pg; CHCM: 22%;\n\nRDW: 12%; morfologia da série vermelha: hipocromia e microcitose; leucometria: 8.500/mm3 (eos:\n1%, basófilos: 0%, bastões: 2%, seg: 35%,\nlinf: 60%, mon:2%) e plaquetas: 230.000/mm3;\nreticulócitos: 1,6%. Para confirmar a hipótese diagnóstica mais provável, o exame a ser solicitado\né:","options":{"A":"Ferritina.","B":"Mielograma.","C":"Eletroforese de hemoglobina.","D":"Índice de saturação da transferrina."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-186486","number":"186486","sourceNumber":"186486","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente, 1 ano e 6 meses, vem apresentando irritabilidade e dificuldade de manter-se\nde pé há um mês. A família é vegetariana, e a\nmãe não fez pré-natal. Exames laboratoriais: Hm:\n1.460.000/mm3, Hb:5,7g/dL, Ht: 18,7%, VCM: 128fL, HCM: 38,7pg, CHCM: 30,2g/dL; leucometria:\n3.500/mm3 (eos: 2%, bastões; 3% seg: 63%, linf: 30%, mon: 2%); Plaquetas: 100.000/mm3.\n\nAnisocitose (+/4+), macrocitose (+++/4+), macroovalócitos, corpúsculos de Howel-Jolly,\nReticulócitos: 2%, LDH: 900U/L (normal: 240 a\n480U/L), bilirrubina total: 3,5mg/dL, BD: 0,7mg/dL,\nBl: 2,8mg/dL. Esse quadro não teria se instalado caso a família ingerisse habitualmente:","options":{"A":"Ovo.","B":"Sucos de fruta.","C":"Vegetais de cor verde.","D":"Castanhas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-186503","number":"186503","sourceNumber":"186503","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em hemograma de rotina de lactente de 18 meses, foi encontrado Hb: 9,1g/dl, Ht: 28%,\nhemácias: 3.000.000/mm3, esquizócitos, micrócitos e moderada hipocromia, leucometria: normal\nsem eosinofilia. Nunca fez uso de vermífugos, pois recebe água tratada e vive em área com\nsaneamento básico. Usou irregularmente as vitaminas e o ferro profilático prescritos. Recebeu\naleitamento materno exclusivo até os seis meses, depois foi introduzida alimentação complementar\ne leite de vaca in natura. A etiopatogenia deste quadro é:","options":{"A":"Uso precoce de leite de vaca.","B":"Verminose.","C":"Ferropenia.","D":"Deficiência de folato e vitamina B12."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-157269","number":"157269","sourceNumber":"157269","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A necrose da medula óssea secundária ao infarto ósseo predispõe o paciente com\nanemia falciforme a complicações, como a\nosteomielite. O agente etiológico mais associado a essa\ncondição é:","options":{"A":"S. aureus.","B":"Klebsiella.","C":"Salmonella.","D":"S.Pneumoniae.","E":"B-streptococcus."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-154651","number":"154651","sourceNumber":"154651","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação à anemia no recém-nascido, assinale a alternativa correta:","options":{"A":"ocorre pela falta de produção hepática de eritrócitos, principalmente no recém-nascido pré-termo","B":"a concentração de hemoglobina cai gradualmente, atingindo os níveis mais baixos entre a 8ª e a\n12ª semanas de vida do recém-nascido a termo","C":"ocorre devido ao reduzido volume corpuscular médico dos eritrócitos em qualquer idade\ngestacional","D":"a deficiência de ferro é um importante fator etiológico no seu desenvolvimento","E":"a hematopoese encontra-se em estado de baixo fluxo e evolução lenta, proporcional com a\nidade gestacional"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-157034","number":"157034","sourceNumber":"157034","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um pré-escolar de 3 anos é levado ao ambulatório pediátrico para consulta com queixa\nde perversão do apetite e palidez cutânea\nprogressiva. Exame físico: em estado geral regular,\npálido, apático, hidratado, afebril e taquipneico. O murmúrio vesicular é positivo, sem ruídos\nadventícios, com ritmo cardíaco regular, bulhas normofonéticas, sopro sistólico (++/++++) e FC =\n160 bpm. O hemograma revela hemoglobina = 5 g%, hematócrito = 15% e VCM = 63. A ferritina é\nde 5 mg%, e a morfologia das hemácias revela anisocitose. Com relação ao exposto, assinale a\nalternativa correta.","options":{"A":"Para a confirmação diagnóstica de anemia ferropriva, falta a dosagem de ferro sérico.","B":"O tratamento indicado é concentrado de hemácias na dose de 10 mL/kg e ferroterapia oral\ndurante 4 meses.","C":"A concentração sérica de ferritina está nos limites inferiores da normalidade, não podendo\nconfirmar o diagnóstico.","D":"O uso de concentrado de hemácias não se impõe ao tratamento, uma vez que não há sinais de\ninsuficiência cardíaca."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-150253","number":"150253","sourceNumber":"150253","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Escolar de sete anos, do sexo masculino, portador de anemia falciforme, chega ao\npronto-socorro com história de que há quatro horas sofre de cefaleia intensa, acompanhada de\ndiminuição de força muscular em membros superior e inferior esquerdos. A tomografia de crânio\nmostrou tratar-se de acidente vascular cerebral isquêmico (AVC-I). Que tratamento deverá ser feito\ncronicamente como medida preventiva de novos episódios de AVC?","options":{"A":"Intolerância à lactose.","B":"Hemorragia digestiva alta.","C":"Pancreatite aguda recidivante.","D":"Síndrome torácica aguda."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-149270","number":"149270","sourceNumber":"149270","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considere as medidas não farmacológicas de tratamento da dor em anemia falciforme a\nseguir. I. Compressas de água quente/fria; II. Distração; III. Música; IV. Relaxamento. São\nCORRETAS as medidas farmacológicas contidas em:","options":{"A":"I e II, apenas.","B":"II e III, apenas.","C":"I e IV, apenas.","D":"I, II, III e IV."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-138171","number":"138171","sourceNumber":"138171","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual é o marcador que apresenta boa especificidade e sensibilidade e vem sendo\nusado no diagnóstico de glomerulopatia\nmembranosa primária?","options":{"A":"SuPAR","B":"Anti PLA 2R","C":"FAN","D":"NGAL"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-129884","number":"129884","sourceNumber":"129884","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São sinais, sintomas ou achados laboratoriais da síndrome nefrótica:","options":{"A":"Edema de início insidioso, proteinúria maior ou igual a 50 mg/kg/dia; albumina sérica menor que\n2,5 g/dl.","B":"Hipercolesterolemia, proteinúria maior ou igual a 50 mg/kg/dia, edema generalizado, oligúria e\nhematúria.","C":"Proteinúria maior ou igual a 40 mg/kg/dia; albumina sérica menor que 2,5 g/dl; complemento\nsérico baixo e ALSO aumentado.","D":"Edema de início abrupto, oligúria, hematúria e hipertensão arterial; proteinúria maior ou igual a\n50 mg/kg/dia."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-127332","number":"127332","sourceNumber":"127332","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Faz parte da tríade de glomerulonefrite difusa aguda:","options":{"A":"Hematúria ? edema ? hipertensão arterial.","B":"Hematúria ? desidratação ? hipertensão arterial.","C":"Hematúria ? edema ? hipotensão arterial.","D":"Proteinúria maior de 3 g/dia ? desidratação ? hipertensão arterial."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-110184","number":"110184","sourceNumber":"110184","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quais as indicações para biópsia renal em crianças portadoras de síndrome nefrótica,\nem primeiro momento?","options":{"A":"Criança com quadro clínico e laboratorial sugestivo de lesão histológica mínima, sem remissão\naté duas semanas.","B":"Recidiva dos sintomas após seis meses do primeiro tratamento.","C":"Crianças portadoras de hipocomplementemia.","D":"Criança entre 2 e 7 anos de idade."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-111388","number":"111388","sourceNumber":"111388","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação ao tratamento das rabdomiólises, que conduta não pode ser tomada?","options":{"A":"Reposição hídrica agressiva.","B":"Acidificação da urina.","C":"Correção da hiperpotassemia.","D":"Correção da hiperfosfatemia.","E":"Hemodiálise (se necessário)."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-111396","number":"111396","sourceNumber":"111396","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação aos diuréticos, que alternativa é incorreta?","options":{"A":"Triantareno diminui a absorção de sódio nos túbulos distais terminais.","B":"Furosemida diminui a absorção de sódio, potássio e cloro na alça.","C":"Acetazolamida diminui a absorção de sódio nos túbulos proximais.","D":"Espironolactona é um agonista da aldosterona.","E":"Amilorida é um não antagonista da aldosterona e age nos túbulos distais terminais."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-109326","number":"109326","sourceNumber":"109326","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual das drogas a seguir costuma induzir nefrite intersticial aguda, que se manifesta\ncomo síndrome nefrótica?","options":{"A":"Fenoprofeno.","B":"Omeprazol.","C":"Amoxicilina.","D":"Ciprofloxacina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-111367","number":"111367","sourceNumber":"111367","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual assertiva abaixo caracteriza a Tríade Clássica da Síndrome Nefrítica?","options":{"A":"Hematúria macroscópica, hipertensão arterial e desidratação.","B":"Hematúria macroscópica, choque hipovolêmico e desidratação.","C":"Hematúria macroscópica, hipertensão arterial e edema.","D":"Hematúria macroscópica, hipotensão arterial e edema.","E":"Hematúria macroscópica, hipotensão arterial e desidratação."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-110244","number":"110244","sourceNumber":"110244","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A lesão glomerular clássica da nefropatia diabética é:","options":{"A":"fibrose intersticial.","B":"glomerulonefrite por lesões mínimas.","C":"necrose fibrinóide.","D":"glomeruloesclerose focal e segmentar."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-101184","number":"101184","sourceNumber":"101184","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"As figuras A e B (VER IMAGEM) correspondem a um exame radiológico obtido de um\npaciente de 11 meses de idade que se apresentava com edema de mãos e pés, simétrico,\ndoloroso, de início súbito, afebril. A imagem B foi obtida 15 dias após a imagem A, que corresponde\nao primeiro dia do quadro descrito. O diagnóstico mais provável é:","options":{"A":"Osteomielite.","B":"Síndrome mão-pé.","C":"Doença de Kawasaki.","D":"Artrite Idiopática Juvenil (AIJ)."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-103726","number":"103726","sourceNumber":"103726","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São causas de hematúria na infância, EXCETO uma das elencadas abaixo. Aponte-a.","options":{"A":"Uso de hidantoína.","B":"Pielonefrite.","C":"Tumor de Wilms.","D":"Traumatismo."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-83797","number":"83797","sourceNumber":"83797","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa incorreta sobre insuficiência renal:","options":{"A":"São sintomas de uremia crônica: prurido cutâneo, pericardite e anemia.","B":"A ureia é metabólito excretado primariamente pelos rins, sendo o mais importante do\ncatabolismo de proteínas.","C":"São sintomas de insuficiência renal aguda: anorexia, náuseas, soluço, vômitos, hematêmese.","D":"Agentes de contraste radiológico não apresentam relação com insuficiência renal aguda.","E":"Diabetes mellitus, hipertensão, glomerulonefrite crônica são as etiologias mais frequentes de\ninsuficiência renal crônica."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-79532","number":"79532","sourceNumber":"79532","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um menino de 3 anos apresenta febre, Tax = 38,3°C e orofaringe hiperemiada. O\nexame do sedimento urinário revela\nproteinúria de (+) a (++), sem outras alterações. A causa mais\nprovável da proteinúria é:","options":{"A":"A infecção urinária","B":"Síndrome nefrítica","C":"Síndrome nefrótica","D":"Proteinúria transitória"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-79539","number":"79539","sourceNumber":"79539","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A respeito da avaliação do exame parcial de urina, qual é a alternativa CERTA?","options":{"A":"A identificação de cristais de oxalato de cálcio no exame do sedimento urinário é um dado\npatognomônico de doença renal.","B":"A presença de cilindros hemáticos traz forte sugestão de doença glomerular renal.","C":"A presença de eritrócitos, independente de eventuais alterações morfológicas, não permite a\ndeterminação do possível foco do sangramento do trato urinário.","D":"A leucocitúria é quase sempre indicativa de infecção urinária, afastando a possibilidade de\ndoenças granulomatosas renais como a sarcoidose.","E":"Chama-se microalbuminúria a excreção de albumina menor que 100 mg, identificável pelas tiras\nreagentes mais sensíveis."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-85370","number":"85370","sourceNumber":"85370","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança com oito anos de idade, sexo masculino, com queixa principal de vômitos e dor\nde cabeça. A história de sua doença revela\nque iniciou cefaleia há dois dias, de moderada\nintensidade, na região occipital e frontal. Há um dia iniciou vômitos e mal-estar geral, diminuição\ndo\nvolume urinário e hematúria. Antecedentes patológicos: amigdalites de repetição, sendo o último\nepisódio há duas semanas, com febre e dor de garganta. Ao exame físico, a criança está com\nregular estado geral, com edema facial moderado, descorado +/4+, eupneico, agitado, ausculta\npulmonar sem alterações, ausculta cardíaca com taquicardia, sem sopros. HC: discreta leucocitose\ne anemia. ASLO positiva, dosagem sérica de C3 diminuída e C4 normal. EAS: hematúria e\nproteinúria. O quadro descrito é compatível com:","options":{"A":"síndrome nefrótica.","B":"pielonefrite aguda.","C":"lúpus eritematoso sistêmico.","D":"glomerulonefrite aguda."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-84657","number":"84657","sourceNumber":"84657","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 3 meses de idade apresenta quadro clínico de edema generalizado, pressão\narterial normal, proteinúria maciça, hipercolesterolemia e 3 hemácias por campo no sedimento\nurinário. Desta história, o dado que NÃO sugere se tratar de síndrome nefrótica por lesão mínima é:","options":{"A":"Idade.","B":"Proteinúria.","C":"Hipercolesterolemia.","D":"Pressão arterial normal.","E":"Sedimento urinário com hemácias."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-84589","number":"84589","sourceNumber":"84589","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dentre as causas de Insuficiência Renal Aguda Nefrotóxica Exógena estão, exceto:","options":{"A":"Aminoglicosídeos.","B":"Cisplatina.","C":"Tetracloreto de Carbono.","D":"Anfotericina B.","E":"Quinolonas."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-85328","number":"85328","sourceNumber":"85328","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente com 57 anos, sexo feminino, diabética há 10 anos, em uso de\nhipoglicemiantes orais com controle\nsatisfatório da glicemia. Chega à emergência com história de\n\"dor no corpo\" há cerca de 4 dias, de início insidioso e progressivo. Associado ao quadro, queixa-se\nde \"dificuldade para urinar e urina avermelhada\" há 2 dias. Nega a disúria. Apresentou febre no\nperíodo (37.5°C) mal estar geral e prostração. Ao exame físico: apresenta dor à palpação dos\ngrupos musculares, generalizada. Edema +/4+ nos MMII; dispneia. Antecedentes pessoais: HAS\nem uso de atenolol e hidroclorotiazida. Hiperlipidemia, descoberta há um mês e vem usando\nestatina e fibrato desde então. Qual a melhor conduta?","options":{"A":"Iniciar paracetamol 750 mg de 6/6 horas.","B":"Solicitar exames: TGO, TGP, CPK, Mioglobina, ureia e creatinina.","C":"Iniciar com antidepressivo tricíclico.","D":"Solicitar Raio X de tórax, hemocultura e urocultura."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-83822","number":"83822","sourceNumber":"83822","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 6 anos é trazida ao pronto-socorro pela mãe, que informa que a criança está\ncom a urina \"escura\" e com edema em face e em membros inferiores. Sobre este caso clínico, é\ncorreto afirmar:","options":{"A":"o diagnóstico provável é de glomerulonefrite","B":"pode ser relacionado à infecção estreptocócica prévia","C":"incidência aumentada em crianças entre 2 e 6 anos","D":"o quadro é compatível com síndrome nefrítica","E":"todas as afirmações acima estão corretas"},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-83835","number":"83835","sourceNumber":"83835","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 6 anos é trazida ao pronto-socorro pela mãe, que informa que a criança está\ncom a urina \"escura\" e com edema em face e em membros inferiores. Para confirmar o diagnóstico,\nque exames, dentre os abaixo, poderão ser solicitados?","options":{"A":"EAS e complemento sérico","B":"ASO e urocultura","C":"EAS e urocultura","D":"EAS e ecodoppler venoso de membros inferiores","E":"EAS e proteinúria de 24 horas"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-78103","number":"78103","sourceNumber":"78103","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Para o tratamento inicial da síndrome nefrótica corticossensível em crianças de 1 a 18\nanos de idade, a recomendação do grupo\ninternacional de especialistas em nefrologia Kidney\nDisease Improving Global Outcomes (KDIGO) é:","options":{"A":"prednisona por via oral, durante 1 a 2 semanas, em dose única diária de 1 mg/kg/dia. A seguir,\nreduzir para 0,5 mg/kg/dia em dose única diária (em dias alternados) e continuar, por dois a cinco\nmeses, fazendo-se redução da dose.","B":"prednisona por via oral, durante 4 a 6 semanas, em dose única diária de 2 mg/kg/dia. A seguir,\nreduzir para 1,5 mg/kg/dia em dose única diária (em dias alternados) e continuar, por dois a cinco\nmeses, fazendo-se redução da dose.","C":"prednisona por via oral, durante 4 a 6 semanas, em dose única diária de 1 mg/kg/dia. A seguir,\nreduzir para 0,5 mg/kg/dia em dose única diária (em dias alternados) e continuar, por dois a cinco\nmeses, fazendo-se redução da dose.","D":"prednisona por via oral, durante 4 a 6 semanas, em dose única diária de 2 mg/kg/dia. A seguir,\nreduzir para 1,0 mg/kg/dia em dose única diária (em dias alternados) e continuar, por dois a cinco\nmeses, fazendo-se redução da dose."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-61261","number":"61261","sourceNumber":"61261","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com respeito à avaliação do exame parcial de urina, qual a alternativa correta?","options":{"A":"a identificação de cristais de oxalato de cálcio no exame do sedimento urinário é um dado\npatognomônico de doença renal.","B":"a presença de cilindros hemáticos traz forte sugestão de doença glomerular renal.","C":"a presença de eritrócitos, independendo de eventuais alterações morfológicas, não permite a\ndeterminação do possível foco do sangramento de trato urinário.","D":"a leucocitúria é quase sempre indicativa de infecção urinária, afastando a possibilidade de\ndoenças granulomatosas renais como a sarcoidose.","E":"chama-se microalbuminúria a excreção de albumina abaixo de 100 mg, identificável pelas tiras\nreagentes mais sensíveis."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-63690","number":"63690","sourceNumber":"63690","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"No plantão, no pronto-socorro do Hospital Evangélico Goiano, chega um paciente\njovem, 20 anos, sexo masculino com queixa\nde ganho de peso e inchaço há 2 dias. Paciente é\npreviamente hígido, não usa medicações e tem hábitos de vida saudáveis. Ele refere ter percebido\nurina escura e em menor quantidade, precedendo o quadro de inchaço e sentir algum cansaço há 1\ndia. Ao exame fisico você nota paciente taquicárdico, com pressão arterial 190/110 mmHg,\ndescorado ++/4+ e com edema de membros inferiores +++/4+ simétrico. Dentro do contexto clínico\ndo caso, qual a hipótese diagnóstica sindrômica mais provável e quais exames devem ser\nsolicitados para avaliação inicial do paciente?","options":{"A":"Síndrome nefrótica. Clearance de creatinina e proteinograma sérico.","B":"Síndrome nefrítica. Hemograma, creatinina e sedimento urinário com pesquisa de dismorfismo\neritrocitário na urina.","C":"Síndrome nefrótica. Albumina sérica, dosagem de colesterol e proteinúria de 24 horas.","D":"Síndrome nefrítica. Ultrassonografia do trato urinário e função renal além da pesquisa de\ndismorfismo eritrocitário na urina."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-61267","number":"61267","sourceNumber":"61267","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com respeito à nefrite intersticial aguda, identifique a alternativa correta:","options":{"A":"os anti-inflamatórios não esteroides desencadeiam nefrite intersticial crônica, mas não a nefrite\nintersticial aguda.","B":"a doença é comum, sendo responsável por cerca de metade dos casos de hematúria e\nproteinúria associada.","C":"a nefrite intersticial por drogas se estabelece dias a semanas após o início do tratamento.","D":"são comuns níveis de proteinúria maciça (acima de 3 g/24h), embora possam ocorrer casos de\nproteinúria discreta.","E":"o tratamento com altas doses de imunossupressores, por tempo prolongado, normalmente não\naumenta o risco de infecções sérias ou mortais."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-63203","number":"63203","sourceNumber":"63203","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São características da síndrome hepatorrenal, EXCETO:","options":{"A":"Histologicamente os rins são normais.","B":"O uso de análogos de vasopressina associada à albumina tem bons resultados\ntemporariamente.","C":"Insuficiência hepática com sódio urinário baixo.","D":"Reversível com transplante hepático.","E":"Eosinofilia e eosinofilúria."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-69197","number":"69197","sourceNumber":"69197","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Rodrigo, escolar de 9 anos de idade, chega à Santa Casa de Misericórdia de Goiânia\ncom história de edema bipalpebral matinal e\nurina escura há 2 dias, sem outras queixas. Ao exame:\npeso = 28 kg; PA = 120 x 85 mmHg (acima p95). Estado geral bom, eupneico, com edema\nbipalpebral (++/4+). Ausculta cardiorrespiratória normal. Presença de lesões pustulocrostosas em\nmembros inferiores. Marque a alternativa correspondente à conduta CORRETA:","options":{"A":"Acompanhamento ambulatorial/solicitar urina I/penicilina benzatina 1.200.000 U e furosemida.","B":"Acompanhamento ambulatorial/solicitar urina I e C3/penicilina benzatina 1.200.000 UI.","C":"Internação/solicitar hemograma, urina I e C3/penicilina benzatina 600.000 UI.","D":"Internação/solicitar urina I, C3 e proteinúria de 24 horas/penicilina benzatina 600.000 U e\nfurosemida.","E":"Internação/solicitar urina I, proteinúria de 24 horas/penicilina benzatina 1.200.000 UI,\nfurosemida\ne nifedipino."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62737","number":"62737","sourceNumber":"62737","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A síndrome nefrótica na criança, é uma doença renal decorrente de proteinúria = 50\nmg/kg/dia e com valores de albumina sérica = 2,5 g%. O quadro completo inclui, ainda, edema e\nhipercolesterolemia. Em crianças corticossensíveis, porém recidivantes frequentes, as drogas\ncomumente utilizadas em substituição à prednisona são:","options":{"A":"tacrolimus e sirolimus.","B":"azatioprina e rituximab.","C":"ciclosporina A e ciclofosfamida.","D":"albendazol e rapamicina."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62756","number":"62756","sourceNumber":"62756","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quando se utiliza o meio de contraste iodado, há necessidade de interromper antes e\napós o exame radiológico o uso da seguinte\nmedicação:","options":{"A":"ciclofosfamida.","B":"paracetamol.","C":"metformina.","D":"azitromicina."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-53548","number":"53548","sourceNumber":"53548","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Homem, 27 anos, é trazido à Emergência por agitação psicomotora, agressividade e\nalucinações auditivas e visuais. Queixa-se de fraqueza muscular difusa. Ao exame, TAx 38°C, FC\n120 bpm, PA 150/100 mmHg. A urina apresenta coloração de chá escuro. EAS revela proteinúria\nsem hematúria. A pesquisa de cocaína na urina é positiva. Qual o provável diagnóstico clínico?","options":{"A":"Rabdomiólise.","B":"Nefropatia por IgA.","C":"Delirium tremens.","D":"Leptospirose.","E":"Encefalopatia hepática."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-51056","number":"51056","sourceNumber":"51056","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A furosemida age inibindo a reabsorção de sódio em qual das seguintes estruturas?","options":{"A":"Ducto coletor.","B":"Túbulo contorcido proximal.","C":"Túbulo contorcido distal.","D":"Parte descendente da alça de Henle.","E":"Parte ascendente da alça de Henle."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-51068","number":"51068","sourceNumber":"51068","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O senhor Onofre, 69 anos de idade, com hipertensão arterial de longa data\ndesenvolveu, em um período de seis meses,\nhipertensão arterial mais grave. Apesar da medicação\nanti-hipertensiva, sua pressão arterial costumeira passou de 140/90 mmHg para 170/110 mmHg.\n\nHá um mês, teve um episódio de \"edema pulmonar súbito\", que provocou sua hospitalização por\numa semana. O senhor Onofre continuou a tomar\nsua medicação anti-hipertensiva com aderência à\nprescrição após essa internação, mas desenvolveu claudicação intermitente na perna esquerda.\n\nEmbora o senhor Onofre seja tabagista de longa duração, não apresentou outros problemas\nclínicos. Qual é a causa mais provável do distúrbio clínico apresentado pelo senhor Onofre?","options":{"A":"Feocromocitoma.","B":"Coarctação da aorta.","C":"Estenose da artéria renal.","D":"Agravamento primário da pressão arterial.","E":"Hiperaldosteronismo primário."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-49026","number":"49026","sourceNumber":"49026","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menina de 8 anos, há 1 semana com alteração visual, vômitos e cefaleia. Há 2 horas\napresentou convulsão do tipo tônico-colônica\ngeneralizada e ficou sonolenta. Há 1 hora apresentou\nnova convulsão e desde então está sonolenta. Mãe nega crise anterior. Informa também que há 15\ndias tomou benzetacil para amidalite. Ao exame: criança com bom estado geral, hidratada,\nacianótica, anictérica, afebril, FC de 70 bpm, PA de 180 x 120 mmhg, edema palpebral bilateral e\nedema de membro inferior. Sem sinais de irritação meníngea. O diagnóstico mais provável é:","options":{"A":"Síndrome nefrótica.","B":"Síndrome nefrítica.","C":"Hipertensão essencial.","D":"Epilepsia.","E":"Encefalite Viral."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-48826","number":"48826","sourceNumber":"48826","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa que responde corretamente a pergunta abaixo. Vários membros\nde uma família apresentam alcalose\nmetabólica hipocalêmica. Qual dos seguintes achados, se\npresente em todos os membros da família afetados, seria mais sugestivo ao diagnóstico de\nSíndrome de Gitelman?","options":{"A":"Hiperuricosúria","B":"Hipercalciúria","C":"Hipomagnesemia","D":"Fraqueza muscular severa","E":"Apresentação no recém-nato"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-53582","number":"53582","sourceNumber":"53582","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Que droga é usada para o tratamento do diabetes insipidus durante a gravidez?","options":{"A":"Angiotensiva.","B":"Acetato de desmopressiva (DDAVP).","C":"Ocitocina.","D":"Renina.","E":"Metformina."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-34072","number":"34072","sourceNumber":"34072","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de oito anos de idade vai ao pronto atendimento de pediatria com história de\nedema, iniciado há dois dias, diminuição da diurese, hematúria macroscópica e hipertensão arterial.\nA mãe relata que o filho apresentou amigdalite há sete dias, tendo sido tratado com antibióticos.\n\nAvaliando esta história clínica, quais exames são os mais importantes para o diagnóstico?","options":{"A":"Dosagem de proteínas e lipídeos séricos.","B":"Urina tipo I e complemento C3.","C":"Urina tipo I e antiestreptolisina.","D":"Proteinúria de 24 horas e eletroforese de proteínas."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-26945","number":"26945","sourceNumber":"26945","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Cícero, 50 anos, foi internado com história de edema generalizado há 4 meses. Negava\ndispnéia ou icterícia. Vinha trabalhando normalmente. Ao exame físico, demonstrava anasarca,\ncorado, anictérico, PA=130/80 mmHg, FC=84 bpm. Sem sinais de congestão pulmonar ou de\ninsuficiência cardíaca. No dia 4 de internação apresentou forte dor em hemitórax direito\nacompanhada de dipneia, cianose, PA=90/70 mmHg e FC=120 bpm. O Rx de tórax estava normal.\nAs condutas para o esclarecimento diagnóstico do evento agudo e da doença de base são\nrespectivamente:","options":{"A":"arteriografia pulmonar e biópsia hepática","B":"mapeamento pulmonar ventilação/perfusão e ecocardiograma","C":"TC de tórax e biópsia renal","D":"mapeamento pulmonar ventilação/perfusão e proteinúria de 24 horas","E":"arteriografia pulmonar e biópsia renal"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-23023","number":"23023","sourceNumber":"23023","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente do sexo masculino, com 28 anos, está em tratamento com\npoliquiomioterapia para hanseníase (dapsona,\nrifampicina e clofazimina). Apresentou, no quarto\nmês de tratamento, diminuição do volume urinário, rash cutâneo, dor lombar e elevação de ureia e\ncreatinina. O diagnóstico mais provável, nesse caso, é:","options":{"A":"Glomerulonefrite crescêntica associada à hanseníase.","B":"Nefrite intersticial aguda por rifampicina.","C":"Necrose tubular aguda associada à dapsona.","D":"Síndrome hemolítica-urêmica associada à clofazimina."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-23025","number":"23025","sourceNumber":"23025","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Leia o caso clínico a seguir. Um paciente de 28 anos, do sexo masculino, procurou\natendimento médico devido a edema generalizado\nhá dois meses, hipertensão arterial, história\nprévia de três episódios de hematúria macroscópica isolada nos últimos dois anos, sem\ninvestigação. Os exames solicitados revelaram: creatinina = 1,5 mg/dl, ureia = 52 mg/dl, dosagem\nde C3 normal, EAS com proteinúria +++, hemácias= 55000, pesquisa de hemácias dismórficas na\nurina positiva com presença de acantócitos, proteinúria = 3,9 g/24horas, hipoalbuminemia e\nhipercolesterolemia, sorologias positivas para vírus B, C e HIV negativas, FAN não reagente,\nultrassom renal com rins de tamanho e volume normais. Foi submetido à biópsia renal\npercutânea.Os achados histopatológicos e o diagnóstico mais provável, nesse caso, são,\nrespectivamente:","options":{"A":"Presença de depósitos subepiteliais (spikes) com espessamento das alças capilares -\nglomerulonefrite membranosa.","B":"Espessamento das alças capilares com aspecto de duplo contorno - glomerulonefrite\nrapidamente progressiva.","C":"Proliferação mesangial com expansão de matriz mesangial e depósito de IgA e C3 no mesângio\n\n- nefropatia por IgA.","D":"Glomerulonefrite proliferativa com predomínio de infiltrado neutrofílico - glomerulonefrite\ndifusa\naguda (GNDA)."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-27145","number":"27145","sourceNumber":"27145","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O tratamento básico da glomerulonefrite difusa aguda é:","options":{"A":"Dieta hipossódica; repouso no leito; corticoterapia; erradicação do estreptococo","B":"Dieta hipossódica; repouso no leito; restrição hídrica; erradiacação do estreptococo","C":"Dieta hipolipídica; repouso no leito; corticoterapia e erradicação do estreptococo","D":"Dieta hipolipídica; restrição hídrica; sedação; penicilina benzatina","E":"Hidratação e repouso"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-27001","number":"27001","sourceNumber":"27001","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Berenice, 8 anos, apresenta cefaleia intensa, tonturas e urina escura. Ao exame físico,\napresentava FC= 110bpm, PA= 175/110mmHg e Tax = 36,9ºC, sem outros sinais ou sintomas. O\ndiagnóstico mais provável é:","options":{"A":"Glomerulonefrite aguda.","B":"Enxaqueca.","C":"Hepatite A.","D":"Sinusite.","E":"Hipertensão maligna."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-8997","number":"8997","sourceNumber":"8997","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Hematúria é:","options":{"A":"qualquer número de hemácias observadas no sedimento urinário, pelo menos em duas de três\namostras de urina recente.","B":"mais de cinco hemácias observadas no sedimento urinário, pelo menos em duas de três\namostras de urina recente.","C":"uma ou duas hemácias no sedimento urinário em qualquer amostra de urina.","D":"presença de reação positiva na área para hemoglobina na tira reagente."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-274008","number":"274008","sourceNumber":"274008","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia é um dos problemas mais comuns no atendimento pediátrico. Sobre as\ncausas de anemia, assinale a alternativa\nCORRETA:","options":{"A":"A esferocitose hereditária apresenta teste de fragilidade osmótica com curva hemolítica.","B":"A talassemia resulta de uma alteração enzimática hereditária que afeta a estabilidade da célula\neritróide.","C":"A reticulocitose, a persistência de hemoglobina fetal, a esferocitose hereditária e deficiência\nde\nfolato são causas de macrocitose.","D":"A hemoglobinúria paroxística noturna e as anemias microangiopáticas são exemplos de anemias\nhipoproliferativas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-250260","number":"250260","sourceNumber":"250260","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mãe, em consulta médica, traz sua filha de 1 ano e 6 meses, queixando que a criança\ntem problema na absorção do ferro. A menina faz\nuso de sulfato ferroso há um ano, de forma\nregular, obedecendo o tempo de uma hora na administração antes das refeições e persiste com\nanemia. Aleitamento materno exclusivo até o sexto mês de vida. Antecedentes pessoais sem\nintercorrências. Alimentação atual carne vermelha 3 vezes por semana, frutas, carne branca, arroz.\nExame físico palidez +/4+. Exames leucócitos 5.500/mm³ (neutrófilos 45%, linfócitos 50%,\nmonócitos 4%, eosinófilos 1%), Hb 10,7g/dL, VCM 55, HCM 25, CHCM 30, RDW 13%, análise do\nesfregaço de sangue periférico: hipocromia, microcitose, pontiados basófilos, reticulócitos 3%.\n\nDevemos solicitar qual exame para confirmar a hipótese diagnóstica mais provável?","options":{"A":"Biópsia de duodeno.","B":"Curva de resistência globular osmótica.","C":"Biópsia de medula óssea.","D":"Eletroforese de hemoglobina."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-250276","number":"250276","sourceNumber":"250276","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A doença falciforme é um grupo de distúrbios genéticos com manifestações sistêmicas\ncaracterizadas por hemólise crônica e complicações agudas que podem levar a risco de morte e\ngraus variáveis de disfunções orgânicas. Com relação as complicações agudas da doença\nfalciforme, marque a opção INCORRETA:","options":{"A":"A crise vaso-oclusiva é a principal manifestação clínica da doença falciforme e pode ocorrer em\npacientes com idade inferior a seis meses. A dor resulta de isquemia e pode ser de extrema\nintensidade. A primeira manifestação da crise vaso-oclusiva pode ocorrer na forma de dactilite\nisquêmica (dor e edema de mãos e pés).","B":"A crise aplástica leva a aplasia permanente da série vermelha por conta da citotoxicidade do\nParvovírus aos precursores hematopoiéticos, nem sempre acompanhada do exantema\ncaracterístico.","C":"A associação entre síndrome torácica aguda e crise álgica é comum. Episódios graves e\nrecorrentes da síndrome torácica aguda podem\nevoluir para hipertensão pulmonar e cor pulmonale.","D":"O sequestro esplênico é diagnosticado mediante sinais de agudização da anemia e aumento\nabrupto do baço. O quadro pode evoluir para\nchoque hemorrágico e óbito."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-176186","number":"176186","sourceNumber":"176186","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre as anemias, é correto afirmar, EXCETO:","options":{"A":"Embora o estafilococo seja muito comum como etiologia de osteomielite em outros contextos, a\nprincipal etiologia na osteomielite relacionada à necrose óssea isquêmica do paciente com anemia\nfalciforme é a salmonela. Episódios vaso-oclusivos no paciente falcêmico estão necessariamente\nassociados à piora da hemólise e queda da hemoglobina.","B":"Cirurgias abdominais podem levar à anemia megaloblástica por deficiência de vitamina B12\natravés de vários procedimentos e\nmecanismos diferentes: gastrectomia, síndrome da alça cega\ncom supercrescimento bacteriano e ressecção do íleo. Valores elevados de ácido metilmalônico e\nde homocisteína ajudam na confirmação diagnóstica.","C":"A anemia ferropriva evolui em etapas específicas: primeiro ocorre a queda da ferritina, depois\nocorre a queda da hemoglobina e, por\núltimo, ocorre a queda do VCM. Entretanto, considerando\nque a ferritina pode aumentar em resposta à inflamação, uma ferritina normal ou mesmo elevada,\ndependendo do contexto clínico, não exclui o diagnóstico de ferropenia.","D":"Embora boa parte dos casos de anemia hemolítica autoimune seja idiopática, alguns estão\nassociados a lúpus eritematoso sistêmico,\nleucemia linfoide crônica ou linfomas. Casos refratários à\nprednisona podem ser tratados com esplenectomia ou até mesmo imunoglobulina.","E":"A anemia aplásica, embora tenha esse nome, pode se apresentar como pacitopenia. Parece\nhaver uma associação entre esta patologia e a\nhemoglobinúria paroxística noturna."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155277","number":"155277","sourceNumber":"155277","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre anemia aplásica, é correto afirmar, EXCETO:","options":{"A":"Esplenomegalia e reticulocitopenia são achados comuns.","B":"Apesar de o nome remeter a uma única linhagem celular, geralmente o paciente se apresenta\ncom pancitopenia.","C":"A patogênese mais comum parece ser a supressão medular autoimune mediada por células T.","D":"O tratamento de escolha para pacientes adultos jovens com doador compatível é o transplante\nde medula óssea alogênico.","E":"Para pacientes acima de 40 anos, prefere-se o tratamento com globulina antitimócito e\nciclosporina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-139238","number":"139238","sourceNumber":"139238","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação à Síndrome Hemolítica-Urêmica (SHU) clássica, pós-diarréica na criança,\nassinale a opção CORRETA.","options":{"A":"Em geral, tem Coombs direto positivo.","B":"A maoria tem boa evolução.","C":"Caracteriza-se por hematúria, anemia e proteinúria.","D":"É mais comum em adolescentes.","E":"É sempre causada por infecção por E. Coli ( O 157:H7)."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-131854","number":"131854","sourceNumber":"131854","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na síndrome nefrótica, a biópsia renal está indicada em qual(is) caso(s)?","options":{"A":"Em pacientes com mais de um ano de idade.","B":"Em pacientes com hipertensão arterial e complemento sérico aumentado.","C":"Em pacientes com hipoalbuminemia < 2,0 g/dL.","D":"Em pacientes que não responderam à prednisona oral por 6 semanas.","E":"Em pacientes com hematúria macroscópica ou hipertensão sustentada, ou complemento sérico\ndiminuído."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-105658","number":"105658","sourceNumber":"105658","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, 15 anos procurou atendimento médico, com relato de febre e disúria há\ndois dias. Contava que já havia apresentado\no mesmo quadro por três vezes e melhorou com uso\nde antibiótico. Exame físico normal, exceto PA 150/100mmHg. EAS com leucocitúria, proteinúria 3+\ne hematúria. Diante do exposto, pode-se afirmar:","options":{"A":"O diagnóstico mais provável é de quadro obstrutivo.","B":"Esse adolescente pode apresentar comprometimento glomerular, visto nível da proteinúria.","C":"O adolescente deverá receber novo esquema de antibiótico, que reverterá os achados do EAS,\nseguido de profilaxia.","D":"Deve-se prescrever novo esquema antibiótico e tranquilizar o adolescente.","E":"Deve-se prescrever antibiótico e seguir com tratamento cirúrgico."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-84894","number":"84894","sourceNumber":"84894","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dentre as glomerulonefrites abaixo, marque a opção cujos níveis de complemento\nséricos permanecem dentro da normalidade:","options":{"A":"Nefropatia por IgA.","B":"Glomerulonefrite lúpica.","C":"Glomerulonefrite membranoproliferativa idiopática.","D":"Glomerulonefrite por endocardite bacteriana.","E":"Glomerulonegrite pós-estreptocócica."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-84912","number":"84912","sourceNumber":"84912","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Marque a opção CORRETA: I - A síndrome nefrótica é uma síndrome clinicolaboratorial\ndecorrente do aumento da permeabilidade\nglomerular às proteínas plasmáticas, caracterizando-se\npor: edema, proteinúria \"maior ou igual a\" 3,5 g/24h, hipoalbuminemia, complicações\ntromboembólicas e dislipidemia; II - Há uma tendência a tromboses ? tanto venosas quanto arteriais\n\n? em pacientes nefróticos e isso ocorre devido à predominância de fatores pró-coagulantes em\nrelação aos fibrinolíticos. Quanto maior a proteinúria, maior a chance de eventos desse tipo; III -\nDentre as glomerulopatias que comumente cursam com síndrome nefrótica estão a glomerulopatia\npor lesões mínimas, a Glomeruloesclerose Segmentar e Focal (GESF) e a glomerulopatia\nmembranosa, sendo que essas duas últimas podem apresentar hematúria microscópica; IV - A\nglomerulopatia por lesões mínimas é mais comum em crianças e em mais de 60% dos casos é\nprimária. Mas, dentre as causas secundárias, temos: Anti-Inflamatórios Não Hormonais (AINH),\ndoença de Hodgkin e alguns tumores sólidos.","options":{"A":"I e II estão corretas.","B":"I e III estão corretas.","C":"I, II e III estão corretas.","D":"I, III e IV estão corretas.","E":"Todas estão corretas."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62609","number":"62609","sourceNumber":"62609","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, 45 anos, internado para tratamento de infecção urinária. Na admissão, seus\nexames mostravam: Cr: 1,2 mg/dl; Ur: 50 mg/dl.\nIniciada antibioticoterapia com Amicacina; no 4°\ndia de uso do antibiótico evolui com aumento de escórias nitrogenadas (ureia: 112 mg/dl; Cr: 2,6\nmg/dl) sem redução do volume urinário: Com relação ao caso, é correto afirmar, EXCETO:","options":{"A":"Principal causa é necrose tubular aguda;","B":"Pode apresentar-se clinicamente com poliúria;","C":"Concentração urinária de sódio é maior que 40 mEq/L;","D":"Presença de cilindros granulares no EAS;","E":"Fração de excreção de sódio menor que 1%."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62666","number":"62666","sourceNumber":"62666","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma criança de 3 anos e 8 meses, branca, feminina, foi picada por abelha e, após sete\ndias, apresentou edema facial matutino e oligúria, quando procurou o Setor de Urgência do Hospital\nda Criança. Ao exame físico, apresentava estatura de 99 cm (Z escore 0), peso 14,400 g (Z escore\n\n- 0,5); temperatura axilar de 36°C; pressão arterial de 100 x 60 mmHg; edema facial e de membros\ninferiores. A paciente foi hospitalizada e os exames solicitados revelaram hemograma sem\nanormalidades, ureia sérica de 30 mg/dl e creatinina de 0,6 mg/dl, sendo o clearance de creatinina\n47,7 ml/min/m² SC. Havia 4+ de proteínas na urina com presença de cilindro granular 1+ e 6\nhemácias por campo (400x). A proteinúria de 12 horas, noturna, foi 61 mg/h/m² SC e a relação\nproteína/creatinina em urina, amostra única, 2,84. Ionograma sem alterações, com sódio 137 mEq/l;\npotássio 4,0 mEq/l; cloreto 100 mEq/l. Proteína sérica total de 3,5 g/dl; albumina 1,5 g/dl;\nglobulinas\n2,0 g/dl; colesterol total 300 mg/dl, HDL 40 mg/dl, LDL 135 mg/dl, triglicérides 400 mg/dl.\n\nComplemento C3 = 120 mg%, C4 = 31 mg% e imunoglobulinas lgG 300 mg/dl, lgM 500 mg/dl, lgA\n45 mg/dl, todos determinados pela técnica e imunodifusão radial. Título de ASLO 250 U Todd,\nHbsAg negativo. A hipótese diagnóstica mais provável para este paciente é :","options":{"A":"Síndrome Nefrítica Difusa Aguda (GNDA);","B":"Síndrome Nefrótica;","C":"Alergia Alimentar;","D":"Glomerulopatia primária;","E":"Doença do Soro."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-47438","number":"47438","sourceNumber":"47438","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A manifestação mais precoce da Nefropatia Diabética é o aparecimento de:","options":{"A":"Queda do ritmo de filtração glomerular.","B":"Hipertensão arterial.","C":"Edema de membros inferiores.","D":"Microalbuminúria.","E":"Retenção nitrogenada."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-47467","number":"47467","sourceNumber":"47467","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma mulher de 25 anos de idade, com síndrome nefrótica (lesão mínima) é vista no\nserviço de emergência com edema de membro inferior direito. US Doppler do membro inferior\nmostra trombose da veia femoral superficial. Qual das seguintes não é um mecanismo de\nhipercoagulabilidade nesta desordem?","options":{"A":"Coagulação intravascular disseminada crônica.","B":"Os baixos níveis séricos de proteína C e proteína S.","C":"Aumento da agregação plaquetária.","D":"Hiperfibrinogenemia.","E":"Níveis séricos baixos de antitrombina III."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-311493","number":"311493","sourceNumber":"311493","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente submetido a By-pass gástrico há 10 anos para tratamento de obesidade\nmórbida vem ao consultório com queixas de dor,\nparestesias, fraqueza e glossite. A glicemia de\njejum é de 115 mg/dl, com Hb glicada de 5,6%. A provável causa da neuropatia periférica em\nquestão é:","options":{"A":"Diabetes Mellitus tipo 2.","B":"Deficiência de retinol.","C":"Deficiência de vitamina C.","D":"Síndrome de Wernicke.","E":"Deficiência de cobalamina."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-308634","number":"308634","sourceNumber":"308634","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre a Anemia Falciforme, é INCORRETO afirmar:","options":{"A":"É uma anemia hemolítica crônica.","B":"Eritrócitos em forma de foice causam oclusão dos vasos.","C":"Pode haver envolvimento do pulmão, com síndrome torácica aguda.","D":"Na hemoglobina S. a valina substitui o ácido glutâmico no sexto aminoácido da cadeia beta.","E":"do ponto de vista epidemiológico ocorre quase exclusivamente em asiáticos."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-302119","number":"302119","sourceNumber":"302119","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente de dois anos, com anemia falciforme, chegou ao pronto-socorro com história\nde dor em membros inferiores, febre de 38,5ºC\ne tosse há três dias. Ao exame físico está\nhipocorado ++/4+, eupneico, sem hepatoesplenomegalia, sem edema ou sinais flogísticos em\nmembros inferiores. Raio-X de tórax normal. A conduta adequada para o caso é:","options":{"A":"analgesia - internar com antibioticoterapia via parenteral","B":"analgesia - liberar com antibioticoterapia via oral","C":"analgesia - encaminhar para reavaliação ambulatorial","D":"anti-inflamatório - liberar com antibioticoterapia via oral","E":"analgesia - hidratação oral"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-263700","number":"263700","sourceNumber":"263700","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Senhora Ilda, 65 anos de idade, viúva há 2 anos, costureira aposentada, fumante\ninveterada, procurou a UBS (Unidade Básica de\nSaúde) de sua comunidade com queixas de\ncansaço e sensação de queimação em seus pés nos últimos seis meses. Um hemograma mostrou\nanemia com VCM (Volume Corpuscular Médio) aumentado. Qual das seguintes alternativas é a\ncausa mais provável de sua anemia?","options":{"A":"Talassemia.","B":"Deficiência de ferro.","C":"Perda sanguínea gastrointestinal crônica.","D":"Falta de fator intrínseco.","E":"Doenças da tireoide."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-263719","number":"263719","sourceNumber":"263719","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Quais as alterações são comumente encontradas em um paciente com anemia\nferropriva?","options":{"A":"VCM baixo e RDW alto.","B":"VCM baixo e RDW baixo.","C":"VCM baixo e RDW normal.","D":"VCM alto e RDW alto.","E":"VCM alto e RDW baixo."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-263755","number":"263755","sourceNumber":"263755","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Segundo a OMS, a cada ano nascem, no Brasil, cerca de 2.500 crianças portadoras de\ndoença falciforme (DF). Em funções relacionadas\nà hemoglobinopatia, 20% delas não vão atingir 5\nanos de idade.","options":{"A":"Pacientes com resultado HbFA na eletroforese de hemoglobina na triagem neonatal deverão ser\nencaminhados, imediatamente, para atendimento de pessoa com doença falciforme.","B":"A doença falciforme é uma anemia hemolítica hereditária autossômica dominante, caracterizada\npor um tipo de hemoglobina mutante.","C":"A dificuldade de opsonização em pacientes com doença falciforme não os torna mais\nsusceptíveis às infecções por germes encapsulados (dentre outros).","D":"Pacientes com Doença Falciforme que apresentam sintomas neurológicos agudos devem ser\nsempre encaminhados para ambulatório de neurologia pediátrica.","E":"O diagnóstico laboratorial da doença falciforme é realizado pela detecção da Hemoglobina S\n(HbS) e da sua associação com outras frações."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-278967","number":"278967","sourceNumber":"278967","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O curso clínico da forma HbSS da doença falciforme geralmente é:","options":{"A":"Benigno.","B":"Grave.","C":"Leve.","D":"Moderado.","E":"Indeterminado."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-252399","number":"252399","sourceNumber":"252399","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual dos seguintes testes é o que apresenta melhor relação custo-benefício na\nsuspeição de deficiência de cobalamina?","options":{"A":"Folato sérico","B":"Níveis séricos de homocisteína","C":"Vitamina B12 sérica","D":"Pepsinogênio sérico","E":"Níveis séricos de metilmalonato"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-203600","number":"203600","sourceNumber":"203600","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São manifestações clínicas da Anemia falciforme, EXCETO:","options":{"A":"Priapismo.","B":"Crescimento e desenvolvimento puberal precoce.","C":"Retinopatias proliferativas.","D":"Vasculopatia cutânea.","E":"Síndrome mão-pé."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-175017","number":"175017","sourceNumber":"175017","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia microcítica caracterizada por ferro sérico diminuído, TIBC diminuído, ferritina\nnormal ou aumentada e RDW normal é:","options":{"A":"Anemia ferropriva.","B":"Talassemia.","C":"Anemia de doença crônica.","D":"Anemia sideroblástica.","E":"Anemia falciforme."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-175076","number":"175076","sourceNumber":"175076","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma lactente de dois anos, com anemia falciforme, chegou ao pronto- socorro com\nhistória de dor em membros inferiores, febre de 38,5 °C e tosse há três dias. Ao exame fisíco está\nhipocorado ++/4+, eupneico, sem hepatoesplenomegalia, sem edema, ou sinais flogisticos em\nmembros inferiores. Raio X de tórax normal. A conduta adequada, somente para esse caso, é:","options":{"A":"analgesia - liberar com antibioticoterapia via oral.","B":"analgesia - internar com antibioticoterapia via parenteral.","C":"analgesia - encaminhar para reavaliação ambulatorial.","D":"anti-inflamatório - liberar com antibioticoterapia via oral.","E":"anti-inflamatório - liberar com analgésicos via oral."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-177531","number":"177531","sourceNumber":"177531","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Maria Clara tem 7 anos, portadora de anemia falciforme, deu entrada no pronto\natendimento com quadro de febre, dor na\nregião da perna direita. Ao exame físico, a criança\nencontrava-se febril, hipocorada++/4+, com edema, dor à manipulação e hiperemia na região da\nperna direita. Mãe relata que a criança sofreu uma queda há 9 dias na perna direita. Selecione a\nopção que corresponde ao diagnóstico e os dois principais microrganismos envolvidos.","options":{"A":"Osteomieliete; Staphylococcus aureus e Streptococcus pyogenes","B":"Osteomielite; Salmonella e Staphylococcus aureus","C":"Osteomielite; Salmonella e Streptococcus pyogenes","D":"Celulite; Staphylococcus aureus e Streptococcus pyogenes","E":"Celulite; Salmonella e Streptococcus pyogenes"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-154427","number":"154427","sourceNumber":"154427","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 54 anos, sexo masculino, negro, casado, lavrador, natural e procedente de\nCodó - MA. Desconhece comorbidades.\nProcurou o posto de saúde referindo cansaço aos esforços\nhabituais, dificultando suas atividades laborativas há algumas semanas. Mais recentemente, notou\nperda de apetite, palpitações, sonolência excessiva e dores de cabeça recorrentes. Era\npreviamente hígido e disposto. Realizou exames laboratoriais que evidenciaram: Hemoglobina =\n7,2 VCM 68 RDW 15,3% Cr 1,1 Ur 42. Sinais vitais: PA = 140 x 90; FC 106; FR 17; Temperatura\n36,5ºC. Qual a sua principal hipótese diagnóstica e recomendação?","options":{"A":"Anemia da doença crônica. Investigar neoplasias malignas.","B":"Anemia ferropriva por déficit nutricional. Iniciar reposição parenteral de ferro imediata e\norientar\nhábitos alimentares.","C":"Anemia falciforme. Eletroforese de hemoglobina e tranfusão sanguínea.","D":"Hemólise por crise hipertensiva. Realização de MAPA e início de tratamento anti-hipertensivo.","E":"Anemia ferropriva por perda crônica. Realização de Endoscopia digestiva alta e colonoscopia."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-160439","number":"160439","sourceNumber":"160439","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A Doença Falciforme (DF) é uma das doenças hereditárias mais comuns no mundo. A\nmutação teve origem no continente africano e pode ser encontrada em populações de diversas\npartes do planeta, com altas incidências na África, Arábia Saudita e Índia. No Brasil devido à\ngrande presença de afrodescendentes, que são uma das bases da população do país, a DF\nconstitui um grupo de doenças e agravos relevantes. É CORRETO afirmar que:","options":{"A":"Os pacientes são mais predispostos a infecções causadas por bactérias não capsuladas, por\ndeficiência de opsonização.","B":"A esplenomegalia é comum em qualquer faixa etária nos portadores de hemoglobina SS.","C":"O homem com traço falciforme, também conhecido por traço de Hb S ou heterozigoto para Hb S,\ntambém costuma ser anêmico e necessitar de tratamento.","D":"A vacinação deve ser completa, inclusive para pneumococo, meningococo e gripe (duas doses\ncom intervalo de um mês, na primovacinação).","E":"Por ser uma anemia hemolítica, observa-se hiperbilirrubinemia direta e o número de reticulócitos\né aumentado."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-160389","number":"160389","sourceNumber":"160389","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 4 anos portadora de malformação congênita é encaminhada ao ambulatório\nde pediatria. Peso: 16kg. Hemograma: Ht: 28%, Hb:\n9,0g/dL e VCM: 66mm³. Diante da suspeita de\nanemia ferropriva, o pediatra instituiu tratamento com xarope de sulfato ferroso (250mg/10mL), 2,5\nmL uma vez ao dia. Na consulta de puericultura, um mês depois, os índices hemáticos\npraticamente não se alteraram. A melhor conduta nesse caso será:","options":{"A":"Manter a dose de sulfato ferroso e aguardar mais um mês.","B":"Iniciar investigação para outras causas de anemia.","C":"Orientar a nutrição e liberar a correção cirúrgica.","D":"Administrar transfusão de concentrado de hemácias.","E":"Corrigir a dose de ferro necessária para o tratamento."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-103932","number":"103932","sourceNumber":"103932","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"É indício inequívoco de glomerulopatia:","options":{"A":"Cilindros hemáticos no EAS.","B":"Proteinúria 1 g/d.","C":"Hematúria.","D":"Cilindros hialinos no EAS.","E":"Queda do complemento."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-107973","number":"107973","sourceNumber":"107973","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação à síndrome nefrótica, pode-se afirmar:","options":{"A":"A teoria \"underfill \" é a mais aceita na atualidade.","B":"Em pacientes idosos com síndrome nefrótica, é necessário considerar causas secundárias como\nMieloma Múltiplo e neoplastia de pulmão.","C":"Pacientes apresentam colesterol total, LDL e triglicerídios aumentados com HDL sempre muito\nreduzido.","D":"Síndrome nefrótica por lesões mínimas é exclusiva de crianças e adultos jovens.","E":"O Diabetes mellitus tipo 2 constitui-se na mais importante causa de síndrome nefrótica primária."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-103974","number":"103974","sourceNumber":"103974","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pedrinho está com 8 anos de idade e iniciou quadro de edema generalizado associado\nà dor abdominal com diminuição da diurese.\nSua mãe o levou a uma Unidade de Pronto\nAtendimento (UPA). Ao exame clínico, apresentava-se com pressão 90 x 50 mmHg e ascite. O\nexame do sedimento urinário demonstrou proteinúria e discreta hematúria. Sua albumina sérica\nestava baixa e o colesterol aumentado. Nesse caso, além das medidas gerais, a conduta\nmedicamentosa de escolha seria:","options":{"A":"furosemida","B":"captopril","C":"atenolol","D":"prednisona","E":"imunoglobulina"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-87606","number":"87606","sourceNumber":"87606","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente do sexo feminino, 64 anos, hipertensa e coronariopata, abriu quadro de dor\nabdominal moderada há 3 dias. Hoje pela manhã notou pronunciada piora da dor abdominal, iniciou\nsubitamente uma dor descrita como insuportável em primeiro pododáctilo esquerdo e começou a\napresentar vômitos recorrentes, cefaléia e confusão mental. Acompanhante comenta ainda não ter\nobservado exteriorização de diurese pela paciente hoje. Informa que há 11 dias foi submetida a\numa cineangiocoronariografia (cateterização femoral esquerda), com colocação de stent não\nfarmacológico em 1/3 proximal da A. descendente anterior, e vinha evoluindo sem precordialgia\ndesde então. Faz uso de AAS 100 mg/d, Clopidogrel 75 mg/d (este último recém-iniciado após o\nprocedimento descrito), Losartana 100 mg/d, Atenolol 50 mg/d e Atorvastatina 80 mg/d. Exame\nfísico revela uma paciente corada, com edema bipalpebral e de MMII, acianótica, com FR de 24\nirpm, sem esforço. A PA é de 170 X 100 mmHg, FC de 68 bpm. Observam-se ainda pulmões\nlimpos, e ausculta cardíaca com B4, sem sopros. Pulsos pediosos palpáveis. Perfusão capilar\nperiférica lentificada em primeiro pododáctilo esquerdo. Laboratório de entrada: Hb: 13,6; 13.800\nleucócitos, sendo 74% PMN e 10% de eosinófilos, sem desvio à esquerda; 162.000 plaquetas; Na:\n135 mEq/L; K: 6,6 mEq/L Creatinina: 3,1 mg/dl; U: 96 mg/dl; Gli:120 mg/dl; amilase elevada.\n\nTroponina I normal; CK total (300 U/L); CK-MB normal; EAS com cilindros granulosos e piúria.\nECG: sobrecarga volumétrica do VE, apenas. Rx\ntórax: hilos pulmonares ingurgitados, área\ncardíaca normal. Pergunta-se: A alteração da função renal no caso acima mais provalvemente se\ndeve a:","options":{"A":"Ateroembolismo por colesterol;","B":"Vasculite sistêmica associada ao Clopidogrel;","C":"Dissecção de porção supra-renal de Aorta abdominal;","D":"Nefropatia por contraste;","E":"Rabdomiólise."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-87498","number":"87498","sourceNumber":"87498","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 20 anos, sexo feminino, com quadro de febre, rinorreia, gotejamento\npós-nasal e hematúria macroscópica. Qual a principal hipótese diagnóstica?","options":{"A":"Nefropatia por IgA.","B":"Nefrite lúpica.","C":"Glomerulonefrite pós-infecciosa.","D":"Glomerulopatia membranosa.","E":"Nefrite tubulointersticial aguda."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-65598","number":"65598","sourceNumber":"65598","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa correta em relação à Síndrome Nefrótica.","options":{"A":"É uma síndrome que se caracteriza por proteinúria acima de 3,0 g/1,73 m² de superfície\ncorporal/dia;","B":"Em adultos, a Glomeruloesclerose Segmentar e Focal (GESF) é a segunda causa mais comum\nde síndrome nefrótica em nosso meio (Brasil).","C":"A doença de lesão mínima e a Glomeruloesclerose Segmentar e Focal (GESF) são altamente\nresponsivas à corticoterapia.","D":"Os pacientes com síndrome nefrótica apresentam um estado de hipercoagulabilidade sendo\npropensos à formação de trombos venosos e, mais raramente, arteriais;","E":"Pacientes com síndrome nefrótica não apresentam risco aumentado a infecções."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-65624","number":"65624","sourceNumber":"65624","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à rabdomiólise, é CORRETO afirmar que:","options":{"A":"O consumo de álcool etílico é uma das mais importantes causas de miopatia e rabdomiólise,\nsendo responsável por 20% dos casos.","B":"A mioglobinúria é uma característica invariável da rabdomiólise e sua ausência exclui o\ndiagnóstico.","C":"Hiperfosfatemia e hipercalcemia são observadas precocemente com frequência na rabdomiólise.","D":"A dosagem da CK, por si só, já permite predizer quais pacientes progredirão para insuficiência\nrenal mioglobinúrica.","E":"A Coagulação Intravascular Disseminada (CIVD) é uma complicação que raramente ocorre na\nrabdomiólise."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-52179","number":"52179","sourceNumber":"52179","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual a principal medida na profilaxia da nefrotoxidade por contraste iodado?","options":{"A":"Fazer bicarbonato de sódio 1 ml/kg/H, EV, 12h antes e depois do procedimento.","B":"Hidratação com SF 0,9%.","C":"Suspender medicamentos nefróticos 48h antes do procedimento.","D":"Acetilcisteína 600 mg, VO, 6/6h.","E":"Acetilcisteína + Vitamina C."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-52193","number":"52193","sourceNumber":"52193","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Na crise renal esclerodérmica, qual a melhor opção terapêutica?","options":{"A":"Bloqueadores dos canais de cálcio.","B":"IECA.","C":"Ciclofosfamida.","D":"Ciclosporina.","E":"Azatioprina."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-348477","number":"348477","sourceNumber":"348477","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher, 25 anos, com queixa de dor epigástrica, fadiga, dificuldade em concentração e\ndormência em mãos e pés. Foi realizado um hemograma que mostrou Hb de 9,8g/dL, Ht de 33%,\nVCM de 105fL, RDW de 16%. Quais exames complementares são necessários para o diagnóstico\ndefinitivo e qual o tratamento indicado para essa paciente?","options":{"A":"Dosagem de ferro sérico, ferritina e capacidade total de ligação ao ferro; suplementação oral de\nferro.","B":"Dosagem de vitamina B12 sérica e endoscopia digestiva alta; injeção mensal de vitamina B12.","C":"Dosagem de vitamina B12 e ultrassonografia abdominal; suplementação oral de vitamina B12.","D":"Dosagem de reticulócitos, bilirrubinas, LDH, coombs direto e indireto; suplementação oral de\nferro."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-348443","number":"348443","sourceNumber":"348443","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, 13 anos, sexo masculino, dá entrada em UPA 24 horas, queixando-se de\ndor de forte intensidade (08 em 10 segundos a escala visual analógica de dor) em membro inferior\nesquerdo com início há 4 horas. A mãe deu em casa um comprimido de dipirona 500mg e\naumentou a oferta de líquidos, porém não houve melhora da dor. Informa que o paciente vem\napresentando rinorreia, tosse produtiva e febre baixa (38,5 °C) há 3 dias. HPP: Possui diagnóstico\nde anemia falciforme desde os primeiros meses de vida e normalmente apresenta hemoglobina\nbasal em torno de 8,0g/dL. Vacinação adequada para a idade. Ao exame físico inicial, paciente\napresenta-se em REG, fáscie de dor, hipocorado 3+/4+, acianótico, anictérico, desidratado 2+/4+ e\nafebril. FC: 110bpm, FR: 24irpm e SpO2: 95% em ar ambiente. Oroscopia e Otoscopia sem\nalterações. Ausência de sinais meníngeos. ACV: RCR em 2T, BNF e SS. Pulsos amplos e boa\nperfusão periférica. AR: MVF em ápices e bases, roncos discretos em ambos hemitóraces.\n\nAbdominal: Atípico, RHA presentes, indolor e ausência de massas ou visceromegalias. Exame\ngenital sem alterações. Membros inferiores\nsimétricos, ausência de sinais inflamatórios e limitação\ndos movimentos à esquerda. Diante do quadro clínico apresentado, quais são as condutas\nterapêuticas e propedêuticas iniciais?","options":{"A":"Após a avaliação inicial, o paciente pode ser liberado para uso de analgésicos comuns em casa.\n\nA princípio como se trata apenas de quadro álgico não há necessidade de realização de exames\nlaboratoriais ou da radiografia de tórax. Os familiares devem ser orientados em relação a sinais de\npiora clínica para retorno à unidade de pronto atendimento.","B":"Manter o paciente em observação, fornecer hidratação endovenosa, otimizar a analgesia, e\nrealizar a transfusão de concentrado de\nhemácias com urgência devido sinais de gravidade iniciais.\nSolicitar exames laboratoriais e radiografia de tórax para exclusão de complicações bacterianas.","C":"Manter o paciente em observação, iniciar hidratação endovenosa, associar analgésicos comuns,\nantiinflamatórios não esteroidais e opioides de horário para dor. Solicitar exames laboratoriais e\nradiografia de tórax para exclusão de complicações bacterianas e avaliar a necessidade de\ntransfusão sanguínea.","D":"Após a avaliação inicial, o paciente pode ser liberado para uso das medicações analgésicas\norais em casa. Exames laboratoriais para\nexclusão de complicações bacterianas e radiografia de\ntórax devem ser mostrados em reavaliação que deve ocorrer no máximo em 48 horas."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-330894","number":"330894","sourceNumber":"330894","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente, cujos pais são portadores de traço falciforme, vem para primeira consulta de\npuericultura com resultado do teste do pezinho na pesquisa de hemoglobinopatias apresentando\npadrão HbAF. Ao constatar esse padrão de hemoglobina, o que se conclui?","options":{"A":"Filho de pais com traço falciforme apresentando traço falciforme.","B":"Filho de pais com traço falciforme apresentando anemia falciforme.","C":"Filho de pais com traço falciforme apresentando padrão normal.","D":"Não deve ser filho do casal com esse resultado."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-313389","number":"313389","sourceNumber":"313389","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Adolescente, 16 anos, sexo feminino, vem para consulta referindo realizar dieta vegana\nrestrita. Qual nutriente poderá entrar em deficiência e deverá ser reposto por seu pediatra que é\nfundamental na conversão da homocisteína em metionina e na conversão do metiltetra-hidrofolato\nem tetrahidrofolato influenciando toda a síntese de DNA celular?","options":{"A":"Piridoxina.","B":"Ácido fólico.","C":"Colecalciferol.","D":"Cianocobalamina."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-288140","number":"288140","sourceNumber":"288140","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia pode ser a causa de uma astenia, porém pode ser consequência de outras\npatologias. Em relação à anemia, assinale a afirmativa CORRETA:","options":{"A":"A anemia ferropriva grave apresenta eritrócitos com macrocitose.","B":"A anemia hemolítica, embora marcante, está entre as formas mais comuns de anemia.","C":"Os eritrócitos na uremia podem adquirir numerosas projeções espinhosas regularmente\nespaçadas.","D":"A macrocitose é caracterizada pela presença de eritrócitos microcíticos e hipocrômicos."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-267334","number":"267334","sourceNumber":"267334","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente A.C.O., 5 meses de vida, vai a sua primeira consulta de puericultura no Centro\nde Saúde Escola. A mãe queixa-se de que a\nfilha é muito pálida e dorme muito. Está em\naleitamento materno exclusivo. Na história familiar, a mãe relata que foi diagnosticada com câncer\ngástrico e na ocasião realizou cirurgia no estômago, mas não sabe dar maiores detalhes sobre o\nprocedimento e não faz reposição de micronutrientes. Ao exame físico, o médico nota baixo peso,\npalidez cutâneo-mucosa 3+/4+, taquicardia, fígado palpável no rebordo costal direito e baço\npalpável a 1 cm do rebordo costal esquerdo. Pela hipótese de síndrome anêmica, o médico solicita\nexames para elucidação diagnóstica, incluindo hemograma com urgência. O resultado do\neritrograma é: Hemoglobina 7,0 g/dl, Hematócrito 21%, VCM 105 fl, HCM 28 pg, RDW 20%. Com\nbase nessa situação clínica, assinale a principal hipótese diagnóstica e o tratamento proposto:","options":{"A":"Anemia megaloblástica; iniciar reposição de vitamina B12 e ácido fólico.","B":"Anemia ferropriva; iniciar reposição de ferro.","C":"Anemia falciforme; iniciar profilaxia com penicilina benzatina ou fenoximetilpenicilina\npotássica e\nácido fólico.","D":"Anemia autoimune; iniciar prednisona."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-255320","number":"255320","sourceNumber":"255320","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa que apresenta a alteração encontrada na deficiência de G6PD:","options":{"A":"Alteração enzimática.","B":"Alteração da membrana do eritrócito.","C":"Alteração numérica quantitativa da cadeia de hemoglobina.","D":"Alteração qualitativa de cadeia de hemoglobina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-254173","number":"254173","sourceNumber":"254173","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa que indica uma causa de anemia microcítica.","options":{"A":"Insuficiência renal crônica","B":"Deficiência de Vitamina B12","C":"Talassemia","D":"Hemorragia aguda"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-247700","number":"247700","sourceNumber":"247700","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente portador de anemia falciforme, atualmente com 4 anos de vida, é atendido no\npronto atendimento com taquidispneia, palidez cutâneo-mucosa, dor torácica, FC 166 bpm, SO?\n\n88% em ar ambiente, obnubilado, PA 88/33 mmHg, pulsos finos, com tempo de reperfusão de 4-5\nsegundos, tax 39ºC, com murmúrio vesicular reduzido em base direita, associado a estertores\nsubcrepitantes homolaterais. Em relação ao paciente em questão, assinale a afirmativa que melhor\nsintetiza o atendimento de emergência:","options":{"A":"Oferta de oxigênio por dispositivo de alto fluxo, acesso venoso calibroso, coleta de culturas,\ninfusão de cristaloide e antibioticoterapia de largo espectro e glicemia capilar.","B":"Intubação orotraqueal em sequência rápida, acesso venoso calibroso, infusão de cristaloide,\ndobutamina e antibiótico de largo espectro.","C":"Oferta de oxigênio por cateter nasal, acesso venoso calibroso, glicemia capilar, coleta de\nexames laboratoriais, infusão de cristaloide e\ndopamina e antibiótico de largo espectro para\ntratamento de broncopneumonia.","D":"Oferta de oxigênio por cateter nasal, acesso venoso calibroso, coleta de exames, infusão de\ncristaloide, infusão de concentrado de hemácias e antibiótico de largo espectro."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-221365","number":"221365","sourceNumber":"221365","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Marque a afirmativa CORRETA levando-se em consideração o diagnóstico de\nSíndrome torácica aguda.","options":{"A":"A mortalidade é extremamente baixa.","B":"A oxigenoterapia está indicada apenas em hipoxemia severa.","C":"Caracteristicamente não há dor torácica.","D":"Podem ocorrem infartos pulmonares."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-221046","number":"221046","sourceNumber":"221046","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Criança de 2 anos é levada ao pronto atendimento com quadro de dor nas pernas, na\nregião lombar e nas mãos que se encontram edemaciadas. Febre baixa não aferida. Ao exame\nfísico apresenta-se chorosa, não permitindo a mobilização dos membros e das mãos. Palidez 3+/4,\nescleras ictéricas. Frequência cardíaca = 154 bpm; baço palpável a 4 cm do RCE; edema no dorso\ndas mãos e dedos, com discreta hiperemia. Exames laboratoriais iniciais: Hb = 6,5 g/dl; Htc = 19%;\nVCM = 78; reticulócitos = 6%; leucócitos totais = 18.640/mm³; neutrófilos = 48%; linfócitos = 56%;\neosinófilos = 1%; plaquetas = 180.000/mm³; bilirrubinas totais = 9,0 mg/dl; bilirrubina direta = 2,8\nmg/dl; bilirrubina indireta = 6,2 mg/dl; TGO = 40 UI/L; TGP = 51 UI/L. Em relação ao quadro acima,\no diagnóstico mais provável é:","options":{"A":"Anemia falciforme em crise de falcização.","B":"Hepatite viral com reação articular.","C":"Anemia ferropriva em paciente com artrite idiopática juvenil.","D":"Leucemia linfoide aguda."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-213962","number":"213962","sourceNumber":"213962","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mãe agenda consulta para o filho de 10 meses na UBS para solicitar um hemograma,\npois acha que o menino está com anemia.\nDurante a inspeção o médico verifica mucosas\nhipocoradas e sopro cardíaco discreto. Mãe refere que o filho nasceu a termo com 2,8 kg e que\nteste de pezinho veio sem alterações. Não está fazendo puericultura pois \"morava no sítio e achava\nmuito difícil ir até a unidade básica rural apenas para passar com a enfermeira\". Sobre o caso\nacima marque a alternativa CORRETA.","options":{"A":"Inicialmente o médico deve solicitar o hemograma para confirmar a suspeita de anemia.","B":"Anemia carencial por ferro é a causa mais comum de anemias, principalmente na infância.\nsendo alta sua suspeição no caso acima.","C":"No caso acima o tratamento via oral já pode ser iniciado com reposição por 2 meses na dose de\n1-2 mg por kg ao dia de ferro elementar.","D":"O melhor é prescrever um polivitamínico, pois pode haver a carência de outros minerais e\nvitaminas."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-208587","number":"208587","sourceNumber":"208587","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Uma mulher de 38 anos, portadora de mioma uterina, tem apresentado perda menstrual\naumentada nos últimos 6 meses. Está com taxa de hemoglobina = 8,5g/dL. Espera-se encontrar,\ntambém, exames laboratoriais com:","options":{"A":"ferro sérico baixo, capacidade total de ligação do ferro elevada e VCM = 70fL","B":"eritropoetina baixa, capacidade total de ligação do ferro baixa e VCM = 68fL","C":"ferro sérico baixo, eritropoetina baixa e VCM = 72fL","D":"ferro sérico baixo, saturação baixa, ferritina normal e VCM = 87FI","E":"nenhuma das alternativas anteriores"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-208565","number":"208565","sourceNumber":"208565","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"De acordo com Protocolo Clínico e Diretrizes Terapêuticas - Portaria SAS/MS,\n1.247/2014, constitui-se em exame não obrigatório para o diagnóstico de anemia ferropriva:","options":{"A":"hemograma com avaliação do esfregaço periférico","B":"ferritina","C":"ferro sérico","D":"contagem de plaquetas","E":"avaliação dos índices hematimétricos"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-185261","number":"185261","sourceNumber":"185261","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa que indica alterações do eritrograma sugestivas de talassemia:","options":{"A":"Hb:8 VCM:90","B":"Hb:10 VCM:110","C":"Hb:12 VCM:70","D":"Hb:6 VCM:80","E":"Hb:9,6 VCM:64"},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-177326","number":"177326","sourceNumber":"177326","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um lactente de 1 ano e 2 meses é trazido para consulta de puericultura. Trata-se de\numa criança sem doença de base, nascida a\ntermo, sem intercorrências. Apresenta boas condições\nde moradia e higiene e nunca recebeu vitaminas, ferro ou vermífugos. Recebeu leite materno\nexclusivo até os 6 meses, quando foram introduzidos leite de vaca integral e alimentação\ncomplementar. Seu hemograma coletado há 15 dias mostrava Hb = 9,2g/dl, Ht = 28% e hemácias =\n3.000.000/mm³. E mais: leucócitos normais, sem eosinofilia, hipocromia moderada e microcitose. A\npossível causa para essas alterações hematológicas é:","options":{"A":"introdução tardia da alimentação complementar","B":"ausência de suplementação de ferro após os 6 meses","C":"ausência de vermifugação precoce","D":"consumo precoce de leite de vaca","E":"nenhuma das alternativas anteriores"},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-181557","number":"181557","sourceNumber":"181557","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente sexo masculino, 72 anos, hipertenso controlado, antecedente de cirurgia de\nvesícula há um ano, relata fraqueza progressiva há 4 meses, especialmente aos esforços. Nega\noutros sintomas associados. Apetite preservado. Ao exame, apresenta-se pálido (2+/4+), FC\n98bpm, FR 18irm, PA 140×90 mmHg. Sem outras anormalidades no exame físico. Traz\nhemograma colhido na UBS há 1 semana: Hb 7,2; Ht 19; VCM 68; HCM 20; RDW 19. Leucograma\ne contagem plaquetária normais. Qual a abordagem inicial para o referido caso?","options":{"A":"Reposição de ferro via preferencialmente oral e solicitar novo hemograma e reticulócitos de\ncontrole em 2 semanas.","B":"Reposição de vitamina B12 intra-muscular semanal associada a ácido fólico oral, com controle\nlaboratorial em 2 semanas.","C":"Solicitar exames endoscópicos do trato gastrointestinal para excluir fonte de perda sanguínea\ncrônica e iniciar reposição de ferro oral.","D":"Solicitar cinética do ferro e, caso confirme ferropenia, iniciar reposição de ferro via\npreferencialmente oral."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-181102","number":"181102","sourceNumber":"181102","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mãe chega ao posto de saúde com filho de 4 meses. Refere que como \"não tem leite\"\nprefere alimentar a criança exclusivamente com leite de cabra. Com essa informação devemos\nprescrever a suplementação de:","options":{"A":"Vitamina D;","B":"Complexo B;","C":"Vitamina C;","D":"Ácido Fólico."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-181578","number":"181578","sourceNumber":"181578","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um lactente de 20 dias é trazido a uma Unidade Básica de Saúde por sua mãe. Ela\nestá ansiosa com o resultado do teste do pezinho. O menino nasceu de 38 semanas pesando\n\n3.050 gramas. O resultado foi entregue por uma atendente e não foi explicado se havia\nanormalidades. Os resultados são os\nseguintes: Diante do exposto, qual é a conduta adequada\npara o caso?","options":{"A":"Explicar que se trata de um caso de doença falciforme e deverá iniciar, em momento adequado,\npenicilina e\n\nácido fólico.","B":"Explicar que a criança tem o traço falciforme e orientar o acompanhamento de crescimento e\ndesenvolvimento.","C":"Explicar que o teste está normal e orientar o acompanhamento de crescimento e\ndesenvolvimento.","D":"Explicar que a criança tem o traço falciforme e deverá iniciar, em momento adequado, penicilina\ne ácido fólico."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-167806","number":"167806","sourceNumber":"167806","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente de 20 anos, com anemia crônica e hepato-esplenomegalia discreta, negando\nhemotransfusão prévia. Das doenças hematológicas, qual o diagnóstico provável?","options":{"A":"Talassemia major (FF)","B":"Anemia falciforme (SS)","C":"Púrpura trombocitopênica idiopática","D":"Associação de hemoglobinopatias (SF,SC)"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-156439","number":"156439","sourceNumber":"156439","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Durante a investigação de uma anemia ferropriva em uma criança de 9 anos de idade,\nqual dos seguintes resultados EXCLUI de vez a deficiência de ferro?","options":{"A":"Aspirado de medula óssea com reserva de ferro normal.","B":"Volume globular médio normal.","C":"Aumento do TIBC.","D":"Ferritina sérica normal."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-158122","number":"158122","sourceNumber":"158122","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa que apresenta a associação INCORRETA entre doença e\nprovável agente etiológico:","options":{"A":"Síndrome mielodisplásica - benzeno.","B":"Tuberculose - silicose.","C":"Mesotelioma de pleura - asbestose.","D":"Anemia aplástica - amianto."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-158194","number":"158194","sourceNumber":"158194","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"H.B.C., 3 anos e 6 meses, menina, vem à consulta anual de pediatria, sem queixas. A\ncriança é filha única e fica na creche em período integral. De antecedentes fisiológicos, a mãe\nrefere que a criança nasceu prematura de 35 semanas, sem outras intercorrências. Na história\nalimentar, a mãe refere amamentação em seio materno exclusivamente até os três meses de idade,\nquando passou a dar fórmula infantil industrializada de primeiro semestre. Introduziu alimentos\ncomplementares aos 4 meses e leite de vaca integral a partir do 6º mês. Atualmente almoça e janta\na comida da família. Come arroz, macarrão, feijão, tomate, batata e carne de boi ou frango. Não\ncome muita carne e não gosta de outros legumes nem de verdura. Toma suco, come bolachas\nrecheadas e salgadinhos industrializados. Nunca tomou sulfato ferroso. De antecedentes\npatológicos, refere que a criança tem muitos resfriados e já teve vários episódios de diarreia desde\no nascimento. Ao exame físico, peso: 16,8 kg; comprimento: 96 cm; frequência cardíaca: 96 bpm;\nfrequência respiratória: 24 irpm; temperatura: 36,6 ºC. Está em bom estado geral, hidratada,\nanictérica e hipocorada (+1/+4). Ao exame físico segmentar, não foi encontrada qualquer\nanormalidade. Em relação a essa criança, são fatores de risco para o desenvolvimento de anemia\nferropriva:","options":{"A":"A interrupção precoce do aleitamento materno exclusivo, introdução precoce de fórmula infantil e\nnão introdução de profilaxia com ferro.","B":"Prematuridade, interrupção prepoce do aleitamento materno exclusivo, introdução precoce do\nleite de vaca e não introdução de profilaxia com ferro.","C":"Prematuridade, introdução precoce de fórmula infantil e não ingestão dos alimentos ricos em\nferro.","D":"Interrupção precoce do aleitamento materno exclusivo, infecções de vias respiratórias\nsuperiores, infecções intestinais de repetição e não\ningestão dos alimentos ricos em ferro."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-137012","number":"137012","sourceNumber":"137012","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente do sexo feminino, 25 anos, portadora de Lúpus Eritematoso Sistêmico\nhá cerca de 2 anos, com manifestações\nhematológicas (anemia leve, normocrômica e\nnormocítica), cutâneas (eritema malar fotossensível) e articulares (poliartrite não erosiva,\ntransitória). Há cerca de oito meses vem apresentando hipertensão arterial, edema periorbital e\nde membros inferiores e urina espumosa. Exames mostram proteinúria de 1,2 g/24 h, creatinina\nde 1,4 mg/dL. O caso descrito trata-se de provável Nefrite Lúpica e a conduta adequada\ndeve ser:","options":{"A":"Tratar com ciclofosfamida endovenosa associada a Metotrexato oral.","B":"Tratar com prednisolona oral na dose de 1 mg/kg/dia associado a hidroxicloroquina na dose de\n250 mg/dia.","C":"Confirmar com mais exames laboratoriais e biópsia renal para melhor definição da terapêutica.","D":"Tratar com pulsoterapia combinada de metilprednisolona e rituximabe, endovenosas."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-136737","number":"136737","sourceNumber":"136737","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação as glomerulonefrites, podemos afirmar que: I - As glomerulonefrites\n\npós-infecciosas estão relacionadas após episódios de faringites ou impetigos causados por cepas\nde estreptococos do grupo beta-hemolítico. II -\nOutras infecções também podem ser associadas\ncom glomerulonefrites, incluindo estados de bacteremias por Staphylococcus aureus. III - A hepatite\nB, hepatite C, o HIV e citalomegaviroses também podem causar glomerulonefrites.","options":{"A":"I e III estão corretas.","B":"I e II estão corretas.","C":"II e III estão corretas .","D":"Todas as afirmativas estão corretas."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-136756","number":"136756","sourceNumber":"136756","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A análise dos sedimentos e seus elementos urinários nos proporciona uma vasta\nquantidade de informações com baixo custo e de forma não invasiva. Assinale a alternativa mais\ncorreta dentre as abaixo:","options":{"A":"A presença de hematuria com dismorfismo eritrocitário, cilindros hemáticos e proteinúria não\nindicam a presença de glomerulonefrites","B":"A urina para o exame deverá ser coletada do primeiro jato após criteriosa antissepsia local","C":"A piúria como alteração única pode indicar uma infecção no trato urinário","D":"A proteinúria maciça é patognomônica de síndrome nefrítica"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-84996","number":"84996","sourceNumber":"84996","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 72 anos, diabética tipo 2, admitida no pronto-socorro com dor precordial, com\ndiagnóstico após 2 horas da admissão de Infarto Agudo do Miocárdio (IAM) com supra de ST.\nExames laboratoriais na admissão: ureia: 72 mg/dl; creatinina: 1,0 mg/dl; Na: 140 mEq/L; K: 4,0\nmEq/L; glicemia: 142 mg/dl. Realizou cineangiocoronariografia e angioplastia primária de lesão\noclusiva em 1/3 médio da artéria descendente anterior. Manteve estabilidade hemodinâmica na\ninternação. Após 48h do procedimento, apresentou elevação das escórias nitrogenadas e acidose\nmetabólica compensada. A causa mais provável da lesão renal aguda é:","options":{"A":"Diabetes Mellitus.","B":"Nefrotoxicidade.","C":"Hipovolemia.","D":"Hipoperfusão secundária ao IAM."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-88429","number":"88429","sourceNumber":"88429","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Dos medicamentos abaixo, qual não está associado à nefrite intersticial alérgica?","options":{"A":"Penicilinas.","B":"Eritromicina.","C":"Rifampicina.","D":"Sulfas."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-360636","number":"360636","sourceNumber":"360636","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Entre as alternativas apresentadas abaixo assinale qual apresenta o principal fator\ndesencadeante de síndrome torácica aguda em crianças com doença falciforme:","options":{"A":"Anemia","B":"Suspensão de hidroxiureia","C":"Trauma","D":"Infecção"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-309757","number":"309757","sourceNumber":"309757","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um menino de 18 meses apresenta palidez. Ela toma 1.800ml de leite de vaca por dia.\nO exame físico é significante somente quanto a evidência de obesidade e palidez. Sem outras\nalterações. Qual exame de laboratório tem maior probabilidade de revelar o diagnóstico:","options":{"A":"RX de tórax","B":"Exame de fezes para ovos e parasitas","C":"Hemograma completo","D":"Haptoglobina do soro","E":"Aspirado de medula óssea"},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-309770","number":"309770","sourceNumber":"309770","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente sem comorbidades prévias, sexo feminino, 19 anos, em investigação de\nquadro ictérico. Exames laboratoriais com\npresença de anemia normocítica e normocrômica,\nbilirrubinas aumentadas a custas de indireta, transaminases normais, aumento de LDH e presença\nde esquizócitos em sangue periférico. Se houvesse a possibilidade de solicitar mais 1 exame para\nconfirmar a principal hipótese sindrômica, qual deveria ser solicitado:","options":{"A":"Ferritina","B":"Lipase","C":"Fosfatase alcalina","D":"Coombs direto","E":"Coombs indireto"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-247064","number":"247064","sourceNumber":"247064","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"E.E.P., 23 anos, sexo feminino, sem antecedentes patológicos significativos, procura o\nPronto-Socorro com queixas de fraqueza progressiva há duas semanas, acompanhada de\npalpitações aos pequenos esforços. Nega febre ou uso de medicamentos. Notou urina mais escura.\nAo exame físico, apresenta-se: pálida +++, ictérica +, FC 120 bpm, PA = 110 x 70 mmHg, FR 20\nirpm, RCR2T com sopro sistólico panfocal; MV fisiológico simétrico; abdômen: fígado não palpável,\nponta de baço palpável, sem edemas. Qual a principal hipótese diagnóstica?","options":{"A":"Púrpura trombocitopênica trombótica.","B":"Anemia hemolítica autoimune.","C":"Anemia ferropriva.","D":"Púrpura trombocitopênica idiopática.","E":"Anemia por deficiência de B12."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-247132","number":"247132","sourceNumber":"247132","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A Hepatite Autoimune (HAI) é um importante diagnóstico etiológico no contexto das\nhepatites crônicas na infância. O diagnóstico de HAI compreende critérios clínicos, laboratoriais,\nsorológicos, histopatológicos e de exames de imagem. Sobre a HAI, é CORRETO afirmar que:","options":{"A":"Pacientes com HAI têm risco aumentado para outras doenças autoimunes, como retocolite\nulcerativa, artrite reumatoide, doença celíaca e colangite esclerosante autoimune.","B":"O título dos anticorpos antinúcleo e antimúsculo liso não importam no diagnóstico da HAI tipo 1,\nsendo classificados positivos mesmo em baixos títulos.","C":"A necrose em saca-bocado é uma alteração histopatológica patognomônica e exclusiva da HAI.","D":"Toda criança com HAI deverá ser submetida à investigação da anatomia das vias biliares com\ncolangiorressonância, para detectar a presença de atresia de vias biliares.","E":"O tratamento de escolha para manutenção da remissão da HAI é a prednisona em altas doses."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-247134","number":"247134","sourceNumber":"247134","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A reticulocitose é um bom indicador de eritropoiese. Assim, a anemia que costuma\ncursar com reticulocitose é","options":{"A":"Anemia carencial ferropriva.","B":"Anemia por deficiência de vitamina B12.","C":"Esferocitose hereditária.","D":"Anemia de Blackfan-Diamond.","E":"Talassemia."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-216821","number":"216821","sourceNumber":"216821","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual das alternativas abaixo apresenta alteração encontrada na anemia por deficiência\nde ferro e talassemia?","options":{"A":"Ferritina elevada.","B":"Capacidade total de ligação de ferro >360 ?g/dl.","C":"Ferro sérico < 30 ?g/dl.","D":"Microcitose."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-221207","number":"221207","sourceNumber":"221207","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa CORRETA sobre a suplementação de ferro.","options":{"A":"Para recém-nascidos de 1500 a 2500g a dose de ferro deve ser de 3mg/Kg/dia.","B":"Os riscos e benefícios da introdução precoce ou tardia de ferro profilático para prematuros estão\nbem definidos na literatura.","C":"Para recém-nascidos prematuros de 1000 a 1499g, a dose preconizada de ferro é 2mg/Kg/dia.","D":"Para recém-nascidos com peso de nascimento inferior a 1000g, preconiza-se dose de ferro de\n4mg/Kg/dia."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-221231","number":"221231","sourceNumber":"221231","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Marque a afirmativa CORRETA levando-se em consideração o diagnóstico de\nSíndrome torácica aguda.","options":{"A":"A mortalidade é extremamente baixa.","B":"A oxigenoterapia está indicada apenas em hipoxemia severa.","C":"Caracteristicamente não há dor torácica.","D":"Podem ocorrem infartos pulmonares."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-214080","number":"214080","sourceNumber":"214080","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Sobre a necessidade de ferro, assinale V para as afirmativas Verdadeiras e F para as\nFalsas. ( ) Pode-se afirmar que, durante a adolescência, o aumento da necessidade de ferro se faz\nprincipalmente pelo aumento da formação de tecido ósseo, perda sanguínea pós-menarca e pelas\ndietas pobres em ferro, muito comuns na adolescência e causadas por diversos fatores. ( ) Na fase\nde desaceleração de crescimento, a perda sanguínea pós-menarca também é uma grande\nresponsável pela deficiência de ferro nas meninas, a qual é potencializada com ciclos menstruais\nirregulares, algo muito comum nos primeiros dois anos após a menarca, apesar da oferta nutricional\nnormal. ( ) A instalação de deficiência de ferro de maneira gradual, podendo ser assintomática ou\noligossintomática, sendo que a anemia ferropriva só acontece no terceiro estágio de deficiência de\nferro. Assinale a sequência CORRETA de cima para baixo:","options":{"A":"V ? V ? V.","B":"F ? F ? F.","C":"V ? V ? F.","D":"V ? F ? F.","E":"F ? V ? V."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-177088","number":"177088","sourceNumber":"177088","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pré-escolar, dois anos e dois meses, sexo masculino, é levado à consulta de rotina.\nDesenvolvimento neuropsicomotor adequado. Anamnese nutricional: quatro a cinco mamadeiras de\nleite de vaca ao dia, eventual ingestão de carne vermelha e de verduras. Exame físico: sobrepeso\nevidente, hipocorado ++/4+, sem outras anormalidades. O diagnóstico mais provável é que o\n\npré-escolar seja portador de anemia:","options":{"A":"ferropriva","B":"falciforme","C":"hemolítica","D":"de Fanconi"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183526","number":"183526","sourceNumber":"183526","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"J.M.S., 65 anos de idade, comparece ao ambulatório de Clínica Médica com história de\n5 meses de evolução de fraqueza e hiporexia.\nEmagrecimento de 16 kg nesse período. Ao exame\nfísico, apresenta: palidez cutaneomucosa +++ / 4+, anictérico, eupneico e emagrecido. PA =\n130/80 mmHg FC 100 bpm RCR2T com SS panfocal MV fisiológico simétrico Abdome: flácido,\ndoloroso em FID onde se palpa tumoração endurecida e móvel de cerca de 5 cm. Edema MMII +.\nSeu hemograma de entrada mostra: Hb 7,5 g% Ht 20% VCM 64,51 fl HCM 24,1 pg Leucócitos\n\n5.500 (65% segmentados, 30% linfócitos, 5% monócitos) Plaquetas 480.000/mm³. Qual dos perfis\na seguir melhor se enquadra a esse caso?","options":{"A":"Ferro sérico baixo, transferrina livre elevada e ferritina sérica diminuída.","B":"Ferro sérico normal, Índice de saturação de transferrina normal e ferritina sérica diminuída.","C":"Ferro sérico e Índice de saturação de transferrina diminuídos e ferritina sérica normal.","D":"Não é esperada alteração significativa no perfil de ferro.","E":"O diagnóstico depende do achado de sideroblastos na medula óssea."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183417","number":"183417","sourceNumber":"183417","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente do sexo feminino, 20 anos de idade, é transferida de Hospital de Naviraí - MS\npara o HU-UFGD com história de fraqueza progressiva há 15 dias, evoluindo com palpitações e\ndispneia aos esforços e olhos amarelados e urina escura há 3 dias. O exame físico revela palidez\ncutâneo-mucosa +++/4+, icterícia +/4+, Taquicardia (FC = 120 bpm); FR = 24 irpm. SS panfocal.\nAbdome: flácido, indolor, ponta de baço palpável. Ausência de edemas ou púrpuras. Seu\nhemograma de entrada mostra: Hb = 5,4 g/dl; VCM = 105 fl; leucócitos = 11.000 (80% neutrófilos,\n18% linfócitos, 2% monócitos); plaquetas = 350.000/mm³. Assinale a alternativa que se relaciona\nCORRETAMENTE ao caso da análise.","options":{"A":"Os achados de reticulocitose e elevação de LDH sugerem anemia perniciosa.","B":"Hiperbilirrubinemia indireta e reticulocitopenia fazem pensar em anemia aplástica.","C":"O aspirado de medula óssea está indicado para pesquisa de síndrome mielodisplásica.","D":"Reticulocitose, elevação de LDH e teste de Coombs direto positivo são esperados.","E":"Devem ser solicitados exames de avaliação hepática e marcadores de hepatites virais."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183355","number":"183355","sourceNumber":"183355","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Considere o caso a seguir. João, de dois anos de idade, é levado pela mãe à consulta\nde rotina com o pediatra com queixa de\npalidez. O desenvolvimento neuropsicomotor é normal para\na idade, mas, na rotina alimentar, a mãe relata ingesta de cinco mamadeiras de leite de vaca ao dia\ne dificuldade na aceitação de carne vermelha, frutas e verduras. Ao exame físico, apresenta\nobesidade, hipocorado +2/4+, hidratado, e não apresenta mais nenhuma outra anormalidade.\n\nDiante desse caso, o diagnóstico mais provável é que João seja portador de qual tipo de anemia?","options":{"A":"Hemolítica.","B":"Ferropriva.","C":"Megaloblástica.","D":"De Fanconi.","E":"Falciforme."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183531","number":"183531","sourceNumber":"183531","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Com relação à triagem neonatal para hemoglobinopatias, em qual das alternativas a\nseguir o resultado não caracteriza o paciente como portador de doença falciforme?","options":{"A":"FS.","B":"FSD.","C":"FSC.","D":"FAS.","E":"FSA."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-183459","number":"183459","sourceNumber":"183459","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual dos fatores a seguir não tem relação com anemia por deficiência de ferro na\ncriança?","options":{"A":"Erro alimentar.","B":"Prematuridade.","C":"Parasitoses intestinais.","D":"Doença hemolítica crônica.","E":"Substituição do leite materno pelo leite de vaca sem suplementação de ferro até os 2 anos de\nidade."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155644","number":"155644","sourceNumber":"155644","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Ao contrário do senso comum, o baço no adulto não é um órgão sem utilidade e a\nesplenectomia não é um procedimento sem consequência para o paciente. Assinale a alternativa\nque representa uma complicação infecciosa tardia desse procedimento:","options":{"A":"Infecção por fungos.","B":"Sepse fatal devido à infecção por amebas de vida livre.","C":"Hiperinfestação de parasitas intestinais.","D":"Infecção por CMV.","E":"Infecção por germes encapsulados."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-151631","number":"151631","sourceNumber":"151631","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente, sexo feminino, 60 anos, dá entrada no PAM com história de fraqueza\nprogressiva nos últimos 7 dias, palidez\nintensa, notando que os olhos ficaram bastante amarelos,\ninclusive pensa estar com hepatite. Nunca apresentou este quadro anteriormente. No exame físico,\napresenta mucosas hipocoradas 3+/4+, ictéricas 2+/4+, com baço palpável a 3 cm do RCE. Traz\nhemograma com Hb = 7,5 g/dl; Ht = 23%; séries branca e plaquetária normais, apenas com\nobservação de presença de eritroblastos. Traz também resultado de dosagem de bilirrubinas com\ntotal de 3,4 mg/dl (até 1,2), indireta de 2,9 mg/dl (até 0,8) e direta de 0,5 mg/dl (até 0,4). O\nplantonista solicitou transfusão, mas o banco de sangue avisou que o teste de aglutinação direta\nestava positivo, impedindo a transfusão. Qual o seu diagnóstico?","options":{"A":"Anemia aplástica.","B":"Talassemia minor.","C":"Anemia hemolítica imune.","D":"Anemia falciforme."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155683","number":"155683","sourceNumber":"155683","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"São diagnósticos diferenciais de anemia microcítica, EXCETO:","options":{"A":"Deficiência de folato.","B":"Deficiência de ferro.","C":"Intoxicação por chumbo.","D":"Talassemia.","E":"Anemia Sideroblástica."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155620","number":"155620","sourceNumber":"155620","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"O que não causa deslocamento para a esquerda na curva de dissociação da\noxiemoglobina?","options":{"A":"Alcalose.","B":"Hipotermia.","C":"Diminuição de 2,3 - DPG.","D":"Formas anormais de hemoglobina.","E":"Aumento de 2,3 - DPG."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-155645","number":"155645","sourceNumber":"155645","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A anemia é um dos principais problemas de saúde pública mundial, chegando a afetar\num quarto da população do planeta, segundo o\nMinistério de Saúde. Sobre esse tema, qual das\nalternativas está INCORRETA?","options":{"A":"A dose de tratamento para crianças com anemia por deficiência de ferro é de 1 a 2 mg de ferro\nelementar.","B":"Segundo a OMS, a anemia por deficiência de ferro é leve a moderada se a hemoglobina fica\nentre 7 a 12 g/dl e grave se a hemoglobina for menor que 7 g/dl, com pequenas variações de\nacordo com a idade, gênero ou presença de gestação.","C":"Embora o valor da hemoglobina seja amplamente utilizado para avaliação de anemia por\ndeficiência de ferro, ela tem baixa especificidade e sensibilidade, e um biomarcador do status do\nferro, como a ferritina sérica, deve ser solicitado em conjunto.","D":"O ferro é mais bem absorvido no duodeno e no jejuno proximal.","E":"Todos os recém-nascidos apresentam uma diminuição nos níveis de hemoglobina após o\nnascimento, devido ao aumento da pressão parcial de oxigênio arterial e da saturação da\nhemoglobina."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-151058","number":"151058","sourceNumber":"151058","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 69 anos, com queixa de fadiga, dispneia aos esforços e tontura. Ao exame\napresenta-se hipocorada, Frequência cardíaca (FC): 100bpm, sem outros achados relevantes. Nos\nexames laboratoriais revelam: Hemoglobina e Hematócrito (g/dL/%): 8,0 e 24%, respectivamente\n(Referencia (ref): 12-15/36-45%), leucócitos totais:10.500 (ref: 4.000 a 11.000), plaquetas: 900.000\n(ref:150.000-450.000), DLH: 159 (ref<250) e VSH (mm/h): 24 (ref<20). Qual a melhor justificativa\npara trombocitose apresentada pela paciente?","options":{"A":"Tromboembolismo pulmonar.","B":"Anemia hemolítica autoimune.","C":"Deficiência de ferro.","D":"Endocardite bacteriana."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-107752","number":"107752","sourceNumber":"107752","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"J.A.S., 63 anos, sexo feminino, portadora de diabetes mellitus, hipertensão arterial,\ndoença renal crônica estágio 3, comparece para\nconsulta ambulatorial com níveis pressóricos\nacima da meta e edema de membros inferiores. No momento, em uso de losartana 50 mg 12/12h.\nExames: Hb: 12,2; Ht: 36; Creatinina 1,5 mg/dl; Uréia 40; Sódio: 137 mEq/dl; Potássio: 4,4 mEq/dl;\nProteinúria 24: 1800 mg/24h; Hemoglobina glicosilada 6,2%. Com base nesses dados, qual das\nseguintes classes de anti-hipertensivos está contraindicada para essa paciente?","options":{"A":"Diurético tiazídico.","B":"Diurético poupador de potássio.","C":"Beta bloqueador.","D":"Inibidor de enzima de conversão da angiotensina.","E":"Bloqueador de canal de cálcio."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-107773","number":"107773","sourceNumber":"107773","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"D.S.L., 28 anos, sexo feminino, SIDA, em tratamento com TAARV, evoluiu com\naumento progressivo dos níveis pressóricos nos\núltimos 2 anos. Os exames iniciais mostraram:\nHb10,3; Ht31; creat = 2,1 mg/dl; Ur = 63 mg/dl; Na = 140 mEq/dl; potássio = 5,1 mEq/dl; urina 1 =\nhemáceas 80/por campo (referência 1-5); proteína +/4+; leucócitos 2/por campo (referência 1-5);\nnitrito negativo. Proteinúria 24h = 1,4 mEq/dl. Optado por realizar biópsia renal. Qual dos\ndiagnósticos abaixo não é hipótese diagnóstica para esse quadro?","options":{"A":"Lesões mínimas.","B":"Glomerulonefrite membrano-proliferativa.","C":"Lupus like.","D":"Glomerulonefrite por lgA.","E":"Glomeruloesclerose segmentar e focal."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62285","number":"62285","sourceNumber":"62285","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"A GNDA (glomerulonefrite difusa aguda pós-estreptocócica) tem como tríade\ncaracterística:","options":{"A":"Anúria, hipertensão arterial e proteinúria.","B":"Edema, hipertensão arterial e hematúria.","C":"Edema, anúria e proteinúria.","D":"Edema, hipertensão arterial e hipercolesterolemia.","E":"Edema, hematúria e hipercolesterolemia."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-62414","number":"62414","sourceNumber":"62414","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Em relação à síndrome nefrótica em pediatria, são indicações de biópsia renal todas as\ncondições abaixo, exceto:","options":{"A":"Idade menor de 1 ano.","B":"Falta de resposta à terapia com corticoide após 4 a 8 semanas de tratamento.","C":"Primeiro episódio de proteinúria.","D":"Idade superior a 10 anos.","E":"Complemento baixo no início do quadro."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-45872","number":"45872","sourceNumber":"45872","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente feminina de 50 anos encontra-se em terapia substitutiva renal (diálise) devido\nà insuficiência renal e proteinúria nefrótica.\nUltimamente vem se queixando de macroglossia,\nparestesia em mãos em trajeto de nervo mediano, dor e aumento de volume abdominal em\nhipocôndrio direito. Exames complementares demonstram aumento importante de fosfatase\nalcalina, níveis de transaminases normais, hipoalbuminemia e hipergamaglobulinemia monoclonal,\nalém de exame de imagem confirmando hepatomegalia. Qual o diagnóstico mais provável?","options":{"A":"Doença de Wilson","B":"Deficiência de a1-antitripsina","C":"Hemocromatose","D":"Amiloidose","E":"Doença de Gaucher"},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-45868","number":"45868","sourceNumber":"45868","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Paciente feminina, 25 anos, queixando edema de membros inferiores e face há 20 dias\nvem à consulta para sua avaliação. Ao exame físico, apresenta pressão arterial = 120/80 mmHg,\nhipocorada, hidratada, edema de membros inferiores de +++/4+. Já tem alguns exames realizados\nrecentemente: creatinina = 0,8, potássio = 4,1, sódio = 144, ureia = 30, C3 = 10, C4 = 30,\nproteinúria de 24 horas 3,8 g. Baseado neste quadro, é correto afirmar:","options":{"A":"Os níveis de complemento reduzidos sugerem glomerulonefrite membranosa idiopática.","B":"Considerando a proteinúria em níveis nefróticos o diagnóstico mais provável é glomerulonefrite\ndifusa aguda.","C":"Os níveis reduzidos de complemento afastam a possibilidade de glomerulonefrite por lúpus\neritematoso sistêmico.","D":"Nefrite lúpica é pouco provável, pois a proteinúria está muito elevada e não há perda de função\nrenal.","E":"Sorologias de hepatite B e C devem ser solicitadas, pois podem causar glomerulopatia com\nredução do complemento."},"answer":"E","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-45531","number":"45531","sourceNumber":"45531","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Os pacientes com anemia falciforme têm maior incidência de infecções bacterianas\ncausadas por bactérias encapsuladas, como\npneumococos ou hemófilos. A causa dessa morbidade\nestá relacionada a:","options":{"A":"Diminuição da contagem de leucócitos circulantes.","B":"Infartos pulmonares recorrentes.","C":"Diminuição da produção de imunoglobulinas.","D":"Asplenia funcional.","E":"Anemia crônica."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-45453","number":"45453","sourceNumber":"45453","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa correta.","options":{"A":"Glomerulonefrite Difusa Aguda pós-estreptocócica cursa com hipocomplementemia por um\nperíodo de dois anos.","B":"Na Glomerulonefrite Difusa Aguda pós-estreptocócica ocorre infiltração dos glomérulos de\ncélulas inflamatórias e depósitos imunes tipo granular.","C":"A Glomerulonefrite Membranoproliferativa se manifesta mais frequentemente como Síndrome\nNefrítica.","D":"A Glomerulonefrite Membranosa não apresenta melhora espontânea devendo-se iniciar\ncorticoterapia em todos os casos.","E":"Nenhuma das anteriores."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-31910","number":"31910","sourceNumber":"31910","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Um paciente do sexo feminino, de 10 anos, procura o pronto-socorro devido a edema\nde membros inferiores há uma semana e urina\nescura. Ao exame físico, a paciente encontra-se\nbastante edemaciada e com hipertensão arterial. Foi realizado um exame de urina na entrada que\ndetectou hematúria. Qual outro exame deverá ser solicitado para o diagnóstico definitivo?","options":{"A":"Lipidograma.","B":"Creatinina sérica.","C":"Ultrassonografia de rins e vias urinárias.","D":"Complemento sérico.","E":"Proteínas totais e frações."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-22633","number":"22633","sourceNumber":"22633","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Qual das medidas para prevenir ou atenuar a insuficiência renal aguda mostrou-se\neficaz?","options":{"A":"dopamina em doses renais.","B":"infusão de fator natriurético atrial.","C":"infusão de soro fisiológico 0,9% previamente e após a infusão de contraste radiológico.","D":"diuréticos de alça endovenoso em altas doses.","E":"infusão de fator de crescimento semelhante à insulina."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-22661","number":"22661","sourceNumber":"22661","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Assinale a alternativa que NÃO contém um diagnóstico diferencial de asma brônquica.","options":{"A":"Obstrução mecânica de vias aéreas, DPOC, síndrome de löeffler.","B":"Carcinoma brônquico, discinesia de laringe, bronquiectasia.","C":"Aspergilose broncopulmonar alérgica, fístula traqueoesofágica, fibrose cística.","D":"Embolia pulmonar, síndrome de hiperventilação, asbestose.","E":"Bronquiolite, insuficiência cardíaca, anel vascular."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-359373","number":"359373","sourceNumber":"359373","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 35 anos foi diagnosticada com anemia ferropriva. Após três meses de\ntratamento com reposição oral de sulfato\nferroso de forma adequada e aderente, os exames\nrevelaram que não houve elevação das reservas de ferro ou aumento da hemoglobina. Assinale a\nalternativa que NÃO apresenta um diagnóstico diferencial para a refratariedade ao tratamento\ndescrito:","options":{"A":"Doença celíaca.","B":"Gastrite atrófica associada ao H. Pylori.","C":"Gastrite autoimune.","D":"Ressecção ileal."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-263048","number":"263048","sourceNumber":"263048","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Gestante de 25 anos, primigesta, sem comorbidades, vem à Unidade Básica de Saúde\ncom o seguinte resultado de hemograma: Hb\n10,1g/dL; hematócrito 29%; hemácias 3.000.000/mm³;\nvolume corpuscular média 104fL/mL; hemoglobina corpuscular média 34,8pg; leucócitos totais\n9.500/mm³; presença de neutrófilos hipersegmentados. Atualmente, com idade gestacional por US\nde primeiro trimestre de 18 semanas e em uso de sulfato ferroso profilático desde 12 semanas.\n\nDiante deste resultado, assinale a CONDUTA MAIS ADEQUADA:","options":{"A":"Prescrição de ácido fólico por via oral e reavaliação do hemograma em 30 dias","B":"Prescrição de sulfato ferroso terapêutico e reavaliação do hemograma em 30 dias","C":"Prescrição de vitamina b12 por via intramuscular e reavaliação do hemograma em 15 dias","D":"Prescrição de vitamina b12 por via oral e reavaliação do hemograma em 15 dias"},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-263055","number":"263055","sourceNumber":"263055","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Davi, 12 meses de idade, reside com os pais que são vegetarianos, na zona rural.\nRecebeu leite materno exclusivo até os 6\nmeses de idade, quando substituiu por leite de cabra in\nnatura, frutas e papa salgada. Atualmente, além de leite, sua alimentação é rica em vegetais\nfolhosos, legumes, frutas e chás caseiros. Ingere cerca de três ovos por semana, porém não faz\nuso de carne de boi, frango ou peixe. Não realiza acompanhamento com pediatra e vai à unidade\nbásica de saúde apenas para vacinação. Mãe leva o filho para consulta, pois está achando-o\nirritado e com hiporexia. Ao exame: peso: 10 kg, estatura: 70 cm, palidez cutaneomucosa\nacentuada, esclera com tom azulado, fígado não palpado e baço palpado sob o rebordo costal\nesquerdo. Demais aparelhos sem alterações. Qual a deficiência MAIS PROVÁVEL, que esta\ncriança está apresentando?","options":{"A":"Ácido fólico.","B":"Cobre.","C":"Ferro.","D":"Vitamina B12."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-233787","number":"233787","sourceNumber":"233787","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Menino de sete anos, diagnosticado com anemia falciforme (SS) pelo teste do pezinho\né atendido na UBS. Mãe informa que a criança já\nesteve internada por cinco vezes devido a\nquadros relacionadas à sua doença. Os relatórios médicos indicaram dois episódios de crise álgica,\num episódio de síndrome torácica aguda e um episódio de priapismo. A medida RECOMENDADA\nPARA PREVENIR as situações descritas é prescrever:","options":{"A":"Ácido fólico uso contínuo.","B":"Antibioticoterapia profilática.","C":"Atividades físicas ao ar livre.","D":"Hidratação oral frequente."},"answer":"D","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-233818","number":"233818","sourceNumber":"233818","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 35 anos vai à UPA queixando-se de dispneia e palpitação. É portadora de\npustulose subcórnea e está em uso de prednisona e dapsona há 20 dias. Ao exame físico,\napresenta PA 120/80 mmHg, FC 109 bpm, FR 23 irpm, SpO? em ar ambiente 94%. Encontra-se\nalerta, orientada, com mucosas descoradas e ictéricas. O restante do exame físico não apresenta\nalterações. Exames de laboratório: Hb 3,9g/dl; Hct 15,3%; VCM 105 fl; HCM 31pg; CHCM 32 g/dl;\nRDW 19,2%; LG 8.600/mm³; Plq 210.000/mm³; LDH 1.200U/L; BT 3,2 mg/dl; BD 0,4 mg/dl;\nreticulócitos 12,2%. Coombs direto negativo; exame de urina: heme positivo, 3 hemácias/campo.\nAssinale o diagnóstico mais provável nesse caso:","options":{"A":"Anemia hemolítica autoimune.","B":"Anemia megaloblástica.","C":"Anemia por deficiência de glicose-6-fosfato desidrogenase.","D":"Anemia sideroblástica."},"answer":"C","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-203172","number":"203172","sourceNumber":"203172","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 68 anos queixa-se de dormência nos membros inferiores e dificuldade para\ndeambular. Familiares referem que ela está irritada e com perda de memória nos últimos meses.\nFoi submetida à ressecção ileal há 10 anos devido à complicação de doença de Crohn que, desde\nentão, está sob controle. O hemograma evidencia anemia (hematócrito 28%) com hemácias\nmacrocíticas (VCM 110 fl) e neutrófilos hipersegmentados no sangue periférico. Dentre as opções\nabaixo, qual é a causa MAIS PROVÁVEL das alterações clínicas e laboratoriais apresentadas pela\npaciente?","options":{"A":"Deficiência de ácido fólico.","B":"Má absorção de vitamina B12.","C":"Perda intestinal crônica de ferro.","D":"Produção deficiente de fator intrínseco."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-203410","number":"203410","sourceNumber":"203410","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Mulher de 83 anos comparece a uma consulta médica para controle de hipertensão\narterial sistêmica, diabetes melito tipo 2 e\ndepressão. Ela se queixa de fadiga e edema vespertino\ndiscreto de membros inferiores. Faz uso de atenolol 50 mg/dia, gliburida 5 mg BID e paroxetina 20\nmg/dia. PA = 152 x 88 mmHg; peso = 42 kg. Ao exame, apresenta palidez cutâneo-mucosa e\nedema periférico 1+. Sem outras alterações ao exame físico. Hemoglobina = 9,6 g/dl (hemácias\nnormocíticas e normocrômicas), leucograma e plaquetas dentro dos limites de normalidade. Na =\n136 mEq/L; K = 4,9 mEg/L; Cl = 108 mEq/L; HCO3- = 18 mEq/L; creatinina = 1,5 mg/dl e glicose =\n178 mg/dl. Enzimas hepáticas normais. Qual é a causa MAIS PROVÁVEL da anemia?","options":{"A":"Anemia de doença crônica secundária de diabetes.","B":"Anemia secundária à doença renal crônica.","C":"Deficiência de folato devido à baixa ingestão de alimentos associada à depressão.","D":"Perda oculta de sangue nas fezes devido a um tumor no cólon."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-203234","number":"203234","sourceNumber":"203234","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Pré-escolar, masculino, três anos de idade comparece à Unidade Básica de Saúde\n(UBS) para consulta de retorno, com resultado\nde hemograma: hemácias = 4 x10?/mm³;\nhemoglobina = 8,1g/dl; hematócrito = 25%; VCM = 68 fl; HCM = 20 pcg; CHCM = 28,7%; RDW =\n20%; global de leucócitos = 5.870 células/mm³ (neutrófilos = 42%; L = 43%; M = 10%; E = 2%; B =\n3%); plaquetas = 620.000/mm³. Idade gestacional de 39 semanas, peso ao nascimento de 2.950\ngramas. Fez uso de leite materno exclusivo por quatro meses e, desde então, quando a mãe\nretornou ao trabalho, passou a tomar leite de vaca (1.000 ml/dia). Fez uso irregular de sulfato\nferroso profilático no primeiro ano de vida. Atualmente, com peso e altura adequados à idade e\níndice de massa corporal de escore Z +3. Assinale a conduta mais adequada para esse caso:","options":{"A":"Indicar o tratamento com ferro parenteral, por via intramuscular, administrado na UBS, três vezes\npor semana.","B":"Iniciar o tratamento com ferro por via oral na dose de 3mg/Kg/dia de ferro elementar em uma ou\nduas doses ao dia.","C":"Solicitar exames complementares: ferro sérico, transferrina e saturação da transferrina para\nesclarecimento diagnóstico.","D":"Suspender o uso do leite de vaca e derivados, orientar dieta diversificada e adequada para a\nidade."},"answer":"B","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-clinica-medica-med-clm-17-174787","number":"174787","sourceNumber":"174787","collectionBlock":"med:med-clinica-medica-med-clm-17","collectionLabel":"MED · MED CLM 17","documentBlock":"","area":"Clínica Médica","specialty":"Clínica Médica","topic":"MED CLM 17","subtopic":"","stem":"Lactente de 18 meses de idade, sabidamente com drepanocitose SS, sem caderneta\nde acompanhamento, há dois dias apresentada dor sem\nlocalização precisa, dispneia, aumento da\npalidez, prostração, taquicardia sem 3ª bulha, febre até 38,5ºC. Fígado palpado a 3 cm do rebordo\ncostal direito e baço grau II de Boyd à palpação. Presença de crepitações esparsas nas bases de\nambos os hemitórax. Saturação de O? = 89%. O hemograma revela: hemoglobina = 6,5 g/dl;\nhemácias = 2.800.000/mm³; hematócrito = 21,5%; leucócitos = 22.200/mm³; bastonetes = 10%;\nsegmentados = 60%; linfócitos = 30%. Plaquetas = 200.000/mm³ e reticulócitos = 9%. A radiografia\nde tórax mostra pequena condensação pulmonar em ambas as bases. Em relação a este caso,\nassinale a conduta considerada ERRADA:","options":{"A":"Hiperidratação, uma vez e meia a necessidade hídrica diária.","B":"Iniciar antibioticoterapia.","C":"Oxigenoterapia.","D":"Transfusão de glóbulos vermelhos."},"answer":"A","source":"Clinica médica/MED CLM 17/MED CLM 17.txt","sourceLabel":"MED · MED CLM 17","images":[],"optionImages":{},"commentImages":[],"tags":["Clínica Médica","MED CLM 17","MED"],"answerSource":"explicit","commentDeferred":true}]};
